export class CognitiveAnalyst {
    /**
     * Audita se o código de um arquivo é condizente com sua docstring/propósito.
     */
    static async analyzeIntent(filename: string, content: string, orchestrator: any): Promise<any | null> {
        // Extrai docstring (heurística simples para TS/Python)
        const docstring = CognitiveAnalyst.extractDocstring(content);
        if (!docstring || docstring.length < 10) return null;

        const prompt = CognitiveAnalyst.buildPrompt(filename, docstring, content);

        try {
            const res = await orchestrator.contextEngine.cognitiveReason(prompt);
            if (!res || !res.status) return null;

            const match = res.status.match(/\{.*\}/s);
            if (!match || !match[0]) {
                logger.warn(`⚠️ Resposta da IA para ${filename} não contém JSON válido.`);
                return null;
            }

            const data = JSON.parse(match[0]);
            if (!data.consistent) {
                return {
                    file: filename,
                    line: 1,
                    severity: data.severity || "MEDIUM",
                    issue: `Desvio de Intenção: ${data.issue}`,
                    agent: "cognitive_analyst",
                    role: "ARCHITECT",
                    emoji: "🧠",
                    stack: "Cognitive",
                    evidence: data.issue,
                    context: "CognitiveIntent"
                };
            }
        } catch (e) {
            logger.error(`❌ Falha na análise cognitiva de ${filename}: ${e}`);
        }
        return null;
    }

    private static extractDocstring(content: string): string | null {
        // Python style
        const pyMatch = content.match(/^(?:'''|""")(.*?)(?:'''|""")/s);
        if (pyMatch && pyMatch[1]) return pyMatch[1].trim();

        // TS/JS style (JSDoc at top)
        const tsMatch = content.match(/^\/\*\*[\s\S]*?\*\//);
        if (tsMatch && tsMatch[0]) return tsMatch[0].replace(/\/\*\*|\*\/|\*/g, "").trim();

        return null;
    }

    private static buildPrompt(filename: string, doc: string, code: string): string {
        return `Audite se o código abaixo cumpre sua docstring.
ARQUIVO: ${filename}
DOCSTRING: "${doc}"
CÓDIGO (Resumo): ${code.slice(0, 2000)}
RESPONDA EM JSON: {"consistent": true/false, "issue": "...", "severity": "..."}`;
    }
}

export class LogicAuditor {
    constructor(private hubManager?: HubManagerGRPC) {}

    /**
     * Realiza uma auditoria completa no arquivo via motor Rust AST.
     */
    async scanFile(filename: string, content?: string): Promise<any[]> {
        if (!this.hubManager) {
            logger.warn(`⚠️ [LogicAuditor] HubManager not provided for ${filename}`);
            return [];
        }

        try {
            const result = await this.hubManager.analyzeFile(filename, content);
            if (!result || !result.findings) return [];

            return result.findings.map((f: any) => ({
                file: filename,
                line: f.line,
                issue: f.message,
                severity: f.severity.toLowerCase(),
                category: f.category,
                context: "LogicAuditor (Rust AST)",
                snippet: f.snippet || ""
            }));
        } catch (error) {
            logger.error(`❌ [LogicAuditor] Hub analysis failed for ${filename}: ${error}`);
            return [];
        }
    }

    /**
     * Valida se uma interação (linha de código) é segura.
     */
    static isInteractionSafe(content: string, fileName: string): { isSafe: boolean, reason: string } {
        // This could also be migrated to Rust in the future
        const dangerous = ["eval(", "exec(", "child_process.execSync"];
        for (const d of dangerous) {
            if (content.includes(d)) return { isSafe: false, reason: `Uso de ${d} detectado.` };
        }
        return { isSafe: true, reason: "" };
    }
}

export class MultiLineRule {
    static check(lines: string[], i: number, stripped: string, file: string, errs: any[]) {
        const isConsec = i > 0 && stripped === "" && (lines[i - 1]?.trim() === "") && (i < 2 || lines[i - 2]?.trim() !== "");
        if (isConsec) errs.push({ file, line: i + 1, issue: "MD012", severity: "low" });
        const isBlock = i > 0 && i < lines.length - 1 && stripped === "" && (lines[i - 1]?.trim() || "").startsWith(">") && (lines[i + 1]?.trim() || "").startsWith(">");
        if (isBlock) errs.push({ file, line: i + 1, issue: "MD028", severity: "medium" });
    }
}

export class InstanceGrouper {
    static async group(tsRoot: string): Promise<Map<string, AgentInstance[]>> {
        const groups = new Map<string, AgentInstance[]>();
        const stacks = ["Bun", "Flutter", "Go", "Kotlin", "Python", "Rust", "TypeScript", "Zig"];
        const cats = ["Audit", "Content", "Strategic", "System"];

        // Try batch extraction first (Rust-powered via gRPC)
        try {
            const hub = HubManagerGRPC.getInstance();
            const status = await hub.getStatus();
            const extractor = status ? new FingerprintExtractor(hub) : new FingerprintExtractor();
            if (status) logger.info("✅ [InstanceGrouper] Hub gRPC conectado — usando fingerprint AST nativo.");
            else logger.warn("⚠️ [InstanceGrouper] Hub não respondeu — usando fallback local.");
            const batchResults = await extractor.batchExtract(tsRoot);

            if (batchResults.size > 0) {
                stacks.forEach(stack => {
                    cats.forEach(cat => {
                        const dir = path.join(tsRoot, stack, cat);
                        if (!fs.existsSync(dir)) return;

                        fs.readdirSync(dir)
                            .filter(f => /\.(ts|tsx|go|kt|py|dart)$/.test(f))
                            .forEach(tf => {
                                const name = tf.replace(/\.(ts|tsx|go|kt|py|dart)$/, "").toLowerCase();
                                const key = `${cat}/${capitalize(name)}/${stack}`;
                                const fp = batchResults.get(key);

                                if (fp) {
                                    const list = groups.get(name) || [];
                                    list.push({ stack, cat, fp, path: path.join(dir, tf) });
                                    groups.set(name, list);
                                }
                            });
                    });
                });
                return groups;
            }
        } catch (error: unknown) {
            logger.warn("⚠️ [InstanceGrouper] Erro ao tentar batch extraction via Hub:", error instanceof Error ? error.message : String(error));
            // gRPC hub not available or failed — fall through to local extraction
        }

        // Fallback to sequential scanning if batch failed
        for (const stack of stacks) {
            for (const cat of cats) {
                const dir = path.join(tsRoot, stack, cat);
                if (fs.existsSync(dir)) {
                    await this.scanDir(dir, stack, cat, groups);
                }
            }
        }
        return groups;
    }

    private static async scanDir(dir: string, stack: string, cat: string, groups: Map<string, AgentInstance[]>) {
        const files = fs.readdirSync(dir).filter(f => /\.(ts|tsx|go|kt|py|dart)$/.test(f));
        for (const tf of files) {
            const name = tf.replace(/\.(ts|tsx|go|kt|py|dart)$/, "").toLowerCase();
            const content = fs.readFileSync(path.join(dir, tf), "utf-8");
            const fp = tf.endsWith(".py")
                ? await extractPythonFingerprint(content, capitalize(name))
                : await extractTSFingerprint(content, capitalize(name));

            if (fp) {
                const list = groups.get(name) || [];
                list.push({ stack, cat, fp, path: path.join(dir, tf) });
                groups.set(name, list);
            }
        }
    }
}

