export class VetoStrategy {
    /**
     * Determina se um nó deve ser ignorado na auditoria.
     */
    static isVetoed(node: ts.Node, sourceFile: ts.SourceFile, ctx: { domain: string; isTechnical: boolean; inDocstring?: boolean }): boolean {
        // 1. Veto de Comentários
        if (this.isComment(node)) return true;

        // 2. Veto de Docstrings (JSDoc)
        if (this.isDocstring(node, ctx)) return true;

        // 3. Veto por Domínio: Se for EXPERIMENTATION, ignorar não-críticos
        if (ctx.domain === "EXPERIMENTATION" && !this.isCriticalRisk(node)) {
            return true;
        }

        // 4. Veto de Definições Técnicas: Ignorar se estiver em contexto de regras
        if (ctx.isTechnical && this.isRuleDefinition(node)) {
            return true;
        }

        return false;
    }

    private static isComment(node: ts.Node): boolean {
        const text = node.getFullText();
        const trimmed = text.trim();
        return trimmed.startsWith("//") || trimmed.startsWith("/*");
    }

    private static isDocstring(node: ts.Node, ctx: { inDocstring?: boolean }): boolean {
        const text = node.getText();
        if (text.startsWith("/**") || text.startsWith("/*")) return true;
        return ctx.inDocstring || false;
    }

    private static isCriticalRisk(node: ts.Node): boolean {
        const text = node.getText().toLowerCase();
        return text.includes("eval(") || text.includes("exec(");
    }

    private static isRuleDefinition(node: ts.Node): boolean {
        const text = node.getText();
        return ["patterns", "rules", "regex", "diretriz"].some(kw => text.includes(kw));
    }
}

export class Path {
    private _path: string;

    constructor(path: string) {
        this._path = path ? resolve(path).replace(/^[a-z]:/, (m) => m.toUpperCase()) : path;
    }

    toString(): string {
        return this._path;
    }

    absolute(): Path {
        return new Path(resolve(this._path));
    }

    async exists(): Promise<boolean> {
        return existsSync(this._path);
    }

    async isFile(): Promise<boolean> {
        try {
            return statSync(this._path).isFile();
        } catch {
            return false;
        }
    }

    parent(): Path {
        return new Path(dirname(this._path));
    }

    name(): string {
        return basename(this._path);
    }

    stem(): string {
        const n = this.name();
        const parts = n.split('.');
        if (parts.length > 1) {
            return parts.slice(0, -1).join('.');
        }
        return n;
    }

    basename(): string {
        return basename(this._path);
    }

    relativeTo(other: Path): string {
        const from = resolve(other.toString());
        const to = resolve(this._path);
        if (process.platform === "win32") {
            const fromLower = from.toLowerCase();
            const toLower = to.toLowerCase();
            if (fromLower === toLower) return "";
            if (toLower.startsWith(fromLower)) {
                return to.slice(from.length).replace(/^[\\/]/, "");
            }
        }
        return relative(from, to);
    }

    join(...parts: string[]): Path {
        return new Path(join(this._path, ...parts));
    }
}

export class PatternFinder {
    constructor(private hub: HubManagerGRPC) {}

    /**
     * Executes pattern finding across project files.
     * Since the system is Hub-Native, it delegates the actual regex analysis back to the Hub or Rust sidecar.
     */
    public async find(
        contextData: Record<string, FileContextData>,
        extensions: string[],
        rules: AuditRule[],
        ignoredFiles: string[],
        persona: any
    ): Promise<AuditFinding[]> {
        const allFindings: AuditFinding[] = [];
        const files = Object.keys(contextData);

        for (const file of files) {
            const ext = path.extname(file);
            if (!extensions.includes(ext)) continue;
            if (ignoredFiles.includes(path.basename(file))) continue;

            const content = contextData[file].content;
            if (!content) continue;

            // Delegate to Hub for high-performance regex analysis
            const results = await this.hub.analyzeCode(content, persona.id, persona.stack);
            
            results.forEach(f => {
                if (f.file === "embedded_content") f.file = file;
                allFindings.push(f);
            });
        }

        return allFindings;
    }
}

export class VetoEngine {
    /**
     * Decide se uma linha deve ser ignorada na varredura.
     */
    static shouldSkip(line: string, filePath: string, domain: string = "PRODUCTION"): boolean {
        const clean = line.trim();

        // 1. Veto Estrutural (Comentários)
        if (clean.startsWith("//") || clean.startsWith("/*") || clean.startsWith("*") || clean.startsWith("#")) {
            return true;
        }

        // 2. Veto de Domínio (Experimentação vs Crítico)
        if (domain === "EXPERIMENTATION" && !line.toLowerCase().includes("critical")) {
            return true;
        }

        // 3. Veto de Teste (Permite tudo em arquivos de teste)
        if (filePath.includes("/tests/") || filePath.includes(".test.") || filePath.includes(".spec.")) {
            return true;
        }

        // 4. Heurística de Definição de Regra (Regex escrito em string não é execução)
        if (this.isRuleDefinition(line)) {
            return true;
        }

        return false;
    }

    /**
     * Detecta se a linha é uma definição de regra técnica (ex: regex = "/.../").
     */
    static isRuleDefinition(line: string): boolean {
        const lower = line.toLowerCase();
        const patterns = [
            /regex\s*[:=]/,
            /pattern\s*[:=]/,
            /rules\s*[:=]/,
            /diretriz:/,
            /["']ev["']\s*\+\s*["']al/ // Ofuscação de eval em definições
        ];
        return patterns.some(p => p.test(lower));
    }

    /**
     * Detecta se o contexto é matemático técnico (evita confusão com moeda).
     */
    static isTechnicalMathContext(line: string): boolean {
        const techKeywords = ['alpha', 'progress', 'offset', 'dp', 'sp', 'x', 'y', 'width', 'height', 'radius', 'velocity', 'phase', 'lerp', 'sin', 'cos'];
        const moneyKeywords = ['price', 'amount', 'balance', 'cost', 'total', 'tax', 'fee'];

        const lower = line.toLowerCase();
        if (moneyKeywords.some(k => lower.includes(k))) return false;

        return techKeywords.some(k => new RegExp(`\\b${k}\\b`).test(lower));
    }
}

export class SilentErrorStrategy {
    /**
     * Varre um arquivo em busca de erros lógicos silenciados (try/catch vazio ou continue).
     */
    static audit(sourceFile: ts.SourceFile): any[] {
        const issues: any[] = [];

        function visitor(node: ts.Node) {
            if (ts.isCatchClause(node)) {
                checkCatchClause(node);
            }
            ts.forEachChild(node, visitor);
        }

        function checkCatchClause(node: ts.CatchClause) {
            if (isSilentCatch(node) && !ASTIntelligence.isNodeSafe(node, sourceFile)) {
                addIssue(node);
            }
        }

        function isSilentCatch(node: ts.CatchClause): boolean {
            const statements = node.block.statements;
            if (statements.length === 0) return true;
            if (statements.length > 1) return false;

            const first = statements[0]!;
            return ts.isContinueStatement(first) || ts.isEmptyStatement(first);
        }

        function addIssue(node: ts.Node) {
            const { line, character } = sourceFile.getLineAndCharacterOfPosition(node.getStart());
            issues.push({
                file: sourceFile.fileName,
                line: line + 1,
                column: character + 1,
                issue: "Captura de erro silenciosa detectada (Try/Catch vazio ou suprimido).",
                severity: "high",
                context: "LogicAuditor"
            });
        }

        ts.forEachChild(sourceFile, visitor);
        return issues;
    }
}

export class SourceCodeParser {
    private tsParser: TypeScriptParser;
