export class ObservabilityStrategy {
    /**
     * Valida se um log contém telemetria manual que deve ser padronizada.
     */
    static audit(node: ts.Node, sourceFile: ts.SourceFile): { isSafe: boolean, reason: string } {
        // Apenas processamos a chamada completa ou acesso direto para evitar redundância
        if (!ts.isCallExpression(node) && !ts.isPropertyAccessExpression(node)) return { isSafe: true, reason: "" };

        // Se estiver em contexto de teste ou metadata, ignora
        if (ASTIntelligence.isNodeSafe(node, sourceFile)) {
            return { isSafe: true, reason: "Contexto seguro: Telemetria permitida." };
        }

        const text = node.getText();
        if (text.includes("performance.now()") || text.includes("Date.now()") || text.includes("console.time")) {
            // Permitir se for atribuição para variável de start (s, start, startTime)
            let curr: ts.Node | undefined = node;
            while (curr && !ts.isVariableDeclaration(curr)) {
                curr = curr.parent;
            }

            if (curr && ts.isVariableDeclaration(curr)) {
                const varName = curr.name.getText();
                if (/^s$|^start/i.test(varName)) {
                    return { isSafe: true, reason: "Início de captura de métricas permitido." };
                }
            }

            return {
                isSafe: false,
                reason: "Telemetria manual detectada. Use o sistema de logs padronizado do Orquestrador. [Severity: STRATEGIC]"
            };
        }

        return { isSafe: true, reason: "Log informativo seguro." };
    }
}

export class MarkdownStructureAgent {
    private raw: string[];
    private res: string[] = [];
    private state = { seen: {} as Record<string, number>, inCb: false };

    constructor(rawLines: string[]) {
        this.raw = rawLines;
    }

    /**
     * Executa a limpeza estrutural pesada (Refinement).
     */
    executeRefinement(): string[] {
        for (let i = 0; i < this.raw.length; i++) {
            const line = this.raw[i];
            if (line === undefined) continue;
            if (this.processLine(line, i)) {
                continue;
            }
        }
        return this.res;
    }

    private processLine(line: string, idx: number): boolean {
        const stripped = line.trimEnd();

        // Gerenciamento de blocos de código
        if (this.handleCodeBlock(stripped, line)) {
            return true;
        }

        // Processamento de Cabeçalhos
        if (stripped.trim().startsWith("#")) {
            this.applyHeaderLogic(stripped.trim(), idx);
            return true;
        }

        // Conteúdo regular
        if (stripped.trim() !== "" || (this.res.length > 0 && this.res[this.res.length - 1] !== "")) {
            this.res.push(stripped);
        }
        return false;
    }

    private handleCodeBlock(stripped: string, original: string): boolean {
        if (stripped.trim().startsWith("```")) {
            this.state.inCb = !this.state.inCb;
            this.res.push(original);
            return true;
        }
        if (this.state.inCb) {
            this.res.push(original);
            return true;
        }
        return false;
    }

    private applyHeaderLogic(line: string, idx: number): void {
        if (this.res.length > 0 && this.res[this.res.length - 1] !== "") {
            this.res.push("");
        }

        const h = MarkdownUtil.deduplicateHeader(line, this.state.seen);
        this.res.push(h);
        MarkdownUtil.applyHeaderPadding(this.res, this.raw, idx);
    }
}

