export class RiskPolicy {
    static determineRiskLevel(cyclomatic: number, cognitive: number, mi: number): "LOW" | "MODERATE" | "HIGH" | "CRITICAL" {
        if (cyclomatic > 50 || mi < 9) return "CRITICAL";
        if (cyclomatic > 20 || mi < 10) return "HIGH";
        if (cyclomatic > 10 || mi < 20) return "MODERATE";
        return "LOW";
    }

    static determineQualityGate(mi: number, cc: number, defectDensity: number, sloc: number = 0): "GREEN" | "YELLOW" | "RED" {
        // 🔬 Technical Sovereignty: Componentes abaixo do nível de hotspot (>20) e sem defeitos são GREEN.
        if (cc <= 20 && defectDensity === 0) return "GREEN";
        if (mi >= 15 && cc <= 20 && defectDensity <= 0.5) return "GREEN";
        if (mi >= 8 && cc <= 40 && defectDensity <= 2) return "YELLOW";
        return "RED";
    }
}

export class PatchManager {
    constructor(private projectRoot: string) { }

    async applyAndValidate(filePath: string, newContent: string, issue: string, orchestrator: Orchestrator): Promise<boolean> {
        const fullPath = new Path(this.projectRoot).join(filePath).toString();
        const backupPath = fullPath + ".bak";

        // Backup
        if (fs.existsSync(fullPath)) {
            fs.renameSync(fullPath, backupPath);
        }

        try {
            fs.writeFileSync(fullPath, newContent, 'utf-8');
            winston.info(`✨ [Healer] Remendo aplicado em ${filePath}. Validando...`);

            // Validação Cruzada
            const auditResults = await orchestrator.auditEngine.runStrategicAudit(orchestrator, `Cura de arquivo: ${filePath}`);
            const stillBroken = auditResults[0].some((f: any) => f.file === filePath && f.issue === issue);

            if (!stillBroken) {
                winston.info(`✅ [Healer] Cura CONFIRMADA em ${filePath}.`);
                if (fs.existsSync(backupPath)) fs.unlinkSync(backupPath);
                return true;
            } else {
                winston.warn(`❌ [Healer] Cura REPROVADA (problema persiste). Revertendo...`);
                this.revert(fullPath, backupPath);
                return false;
            }
        } catch (err) {
            winston.error(`❌ [Healer] Erro fatal durante a aplicação da cura: ${err}`);
            this.revert(fullPath, backupPath);
            return false;
        }
    }

    private revert(fullPath: string, backupPath: string) {
        if (fs.existsSync(backupPath)) {
            if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath);
            fs.renameSync(backupPath, fullPath);
        }
    }
}

export class Indexer {
    constructor(private projectRoot: string, private hubManager?: HubManagerGRPC) { }

    async updateIndex(): Promise<IndexData> {
        logger.info("📡 Iniciando indexação soberana via Hub Proxy (gRPC)...");
        const startTime = Date.now();
        const indexData = this.getEmptyIndex();

        if (!this.hubManager) {
            logger.warn("⚠️ HubManager not provided to Indexer. Returning empty index.");
            return indexData;
        }

        try {
            const processedFiles = await this.hubManager.indexProject(this.projectRoot);

            if (!processedFiles || !Array.isArray(processedFiles)) {
                throw new Error(`Invalid response from Hub indexer.`);
            }

            for (const pf of processedFiles) {
                const metadata: FileMetadata = {
                    classes: pf.classes || [],
                    functions: pf.functions || [],
                    exports: pf.exports || [],
                    lines: pf.lines || 0
                };
                this.integrateResult(indexData, pf.path, metadata);
            }

            const duration = ((Date.now() - startTime) / 1000).toFixed(2);
            logger.info(`✅ Indexação nativa concluída: ${indexData.stats.totalFiles} módulos em ${duration}s.`);
        } catch (e: any) {
            logger.error(`🚨 Falha crítica no motor de indexação: ${e.message}`);
        }
        return indexData;
    }

    private getEmptyIndex(): IndexData {
        return {
            lastUpdate: new Date().toISOString(), files: {},
            stats: { totalFiles: 0, totalClasses: 0, totalFunctions: 0, totalExports: 0 },
        };
    }

    private integrateResult(indexData: IndexData, file: string, metadata: FileMetadata) {
        indexData.files[file] = metadata;
        indexData.stats.totalFiles++;
        indexData.stats.totalClasses += metadata.classes.length;
        indexData.stats.totalFunctions += metadata.functions.length;
        indexData.stats.totalExports += metadata.exports.length;
    }
}

