export class ThresholdEvaluator {
    static evaluate(metrics: MetricsResult): string[] {
        const issues: string[] = [], isS = metrics.isShadow, lim = { cc: isS ? 15 : 50, cog: isS ? 10 : 30, mi: isS ? 20 : 10, nest: isS ? 3 : 5, cbo: isS ? 2 : 10 };
        if (metrics.cyclomaticComplexity > lim.cc) issues.push(`CC ${metrics.cyclomaticComplexity} > ${lim.cc}`);
        if (metrics.cognitiveComplexity > lim.cog) issues.push(`Cognitive ${metrics.cognitiveComplexity} > ${lim.cog}`);
        if (metrics.maintainabilityIndex < lim.mi) issues.push(`MI ${metrics.maintainabilityIndex.toFixed(1)} < ${lim.mi}`);
        if (metrics.nestingDepth > lim.nest) issues.push(`Nesting ${metrics.nestingDepth} > ${lim.nest}`);
        if (metrics.cbo > lim.cbo) issues.push(`CBO ${metrics.cbo} > ${lim.cbo}`);
        if (metrics.qualityGate !== "GREEN") issues.push(`Quality Gate: ${metrics.qualityGate}`);
        return issues;
    }
}

export class SpacingRules implements LintRule {
    check(lines: string[], i: number, stripped: string, file: string, context: { hMap: Map<string, number>, errs: any[] }): void {
        const isBlank = stripped === "";
        const prevIsBlank = i > 0 && lines[i - 1]?.trim() === "";
        const prevPrevIsNotBlank = i < 2 || lines[i - 2]?.trim() !== "";

        if (i > 0 && isBlank && prevIsBlank && prevPrevIsNotBlank) {
            context.errs.push({
                file, 
                line: i + 1, 
                issue: "MD012: Multiple consecutive blank lines", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: "Multiple blank lines",
                context: "MarkdownAuditor"
            });
        }

        const nextLine = lines[i + 1]?.trim() || "";
        const prevLine = lines[i - 1]?.trim() || "";
        if (i > 0 && i < lines.length - 1 && isBlank && prevLine.startsWith(">") && nextLine.startsWith(">")) {
            context.errs.push({
                file, 
                line: i + 1, 
                issue: "MD028: Blank line inside blockquote", 
                severity: "medium", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: "Blank line in blockquote",
                context: "MarkdownAuditor"
            });
        }
    }
}

export class MultiLineRule {
    static check(lines: string[], i: number, stripped: string, file: string, errs: any[]) {
        const isConsec = i > 0 && stripped === "" && (lines[i - 1]?.trim() === "") && (i < 2 || lines[i - 2]?.trim() !== "");
        if (isConsec) errs.push({ file, line: i + 1, issue: "MD012", severity: "low" });
        const isBlock = i > 0 && i < lines.length - 1 && stripped === "" && (lines[i - 1]?.trim() || "").startsWith(">") && (lines[i + 1]?.trim() || "").startsWith(">");
        if (isBlock) errs.push({ file, line: i + 1, issue: "MD028", severity: "medium" });
    }
}

export class DeltaEngine {
    static compute(legacy: AtomicFingerprint, current: AtomicFingerprint, agent: string): AgentDelta[] {
        const deltas: AgentDelta[] = [];
        if (legacy.name.toLowerCase() !== current.name.toLowerCase())
            deltas.push({ dimension: "name", legacy: legacy.name, current: current.name, severity: "CRITICAL", context: `Agent identity mismatch for ${agent}` });

        if (legacy.rulesCount !== current.rulesCount)
            deltas.push({ dimension: "rulesCount", legacy: String(legacy.rulesCount), current: String(current.rulesCount), severity: "MEDIUM", context: `Rule count divergence` });

        if (legacy.hasReasoning !== current.hasReasoning)
            deltas.push({ dimension: "reasoning", legacy: String(legacy.hasReasoning), current: String(current.hasReasoning), severity: "CRITICAL", context: "Strategy logic MISSING" });

        const legacyMethods = legacy.methods.filter(m => !m.startsWith("_"));
        const currentMethods = current.methods || [];

        for (const lm of legacyMethods) {
            const camelName = lm.replace(/_([a-z])/g, (_, p1: string) => p1.toUpperCase());
            const match = currentMethods.find(cm => cm === lm || cm === camelName || cm.toLowerCase() === lm.replace(/_/g, "").toLowerCase());

            if (!match) {
                deltas.push({
                    dimension: "Method",
                    legacy: lm,
                    current: "MISSING",
                    severity: "HIGH",
                    context: `Method '${lm}' from legacy not found in current implementation.`
                });
            }
        }
        return deltas;
    }

    static computeScore(deltas: AgentDelta[]): number {
        let score = 100;
        const penalties = { CRITICAL: 50, HIGH: 30, MEDIUM: 15, INFO: 2 };
        for (const d of deltas) {
            score -= penalties[d.severity as keyof typeof penalties] || 0;
        }
        return Math.max(0, score);
    }
}

export class QualityEvaluator {
    static calculateMaintainabilityIndex(volume: number, cyclomaticComplexity: number, sloc: number): number {
        if (sloc <= 0) return 100;
        const logVolume = Math.log(Math.max(1, volume));
        const logLOC = Math.log(sloc);
        let mi = 171 - 5.2 * logVolume - 0.23 * cyclomaticComplexity - 16.2 * logLOC;
        mi = mi * 100 / 171;
        return Math.max(0, Math.min(100, mi));
    }

    static determineRiskLevel(cyclomatic: number, cognitive: number, mi: number): "LOW" | "MODERATE" | "HIGH" | "CRITICAL" {
        return RiskPolicy.determineRiskLevel(cyclomatic, cognitive, mi);
    }

    static determineQualityGate(mi: number, cc: number, defectDensity: number, sloc: number = 0): "GREEN" | "YELLOW" | "RED" {
        return RiskPolicy.determineQualityGate(mi, cc, defectDensity, sloc);
    }

    static validateShadowCompliance(metrics: any): { compliant: boolean; reason: string } {
        if (!metrics.isShadow) return { compliant: true, reason: "Não é um shadow" };
        if (metrics.shadowComplexity > 15) return { compliant: false, reason: `Complexidade shadow (${metrics.shadowComplexity}) > 15` };
        if (metrics.maintainabilityIndex < 20) return { compliant: false, reason: `MI (${metrics.maintainabilityIndex.toFixed(1)}) < 20` };
        if (metrics.nestingDepth > 3) return { compliant: false, reason: `Aninhamento (${metrics.nestingDepth}) > 3` };
        return { compliant: true, reason: "Shadow complacente" };
    }

    static getMIStatus(mi: number): string {
        if (mi >= 20) return "🟢 GOOD";
        if (mi >= 10) return "🟡 MODERATE";
        return "🔴 LOW";
    }
}

