export class ComponentClassifier {
    mapType(relPath: string): string {
        logger.debug(`Classifying component: ${relPath}`);
        const p = relPath.toLowerCase();

        if (p.endsWith("__init__.py")) return "PACKAGE_MARKER";
        if (p.includes("test")) return "TEST";

        const rules: [((p: string) => boolean), string][] = [
            [this.isDoc, "DOC"],
            [this.isConfig, "CONFIG"],
            [this.isCore, "CORE"],
            [this.isAgent, "AGENT"],
            [this.isUtil, "UTIL"],
            [this.isInterface, "INTERFACE"],
            [this.isData, "DATA"]
        ];

        for (const [condition, result] of rules) {
            if (condition.call(this, p)) return result;
        }
        return "LOGIC";
    }

    private isDoc(p: string): boolean {
        return ["audit", "forensics", "report", "diagnostic", "restore", "temp", "debug", "fix_"].some(x => p.includes(x));
    }

    private isConfig(p: string): boolean {
        return ["settings", "config", "manifest", ".json", ".yaml", ".yml"].some(x => p.includes(x));
    }

    private isCore(p: string): boolean {
        return p.includes("core") || p.includes("domain");
    }

    private isAgent(p: string): boolean {
        return p.includes("agent/") || p.startsWith("agent_") || (p.endsWith(".py") && p.includes("agent") && !p.includes("personas"));
    }

    private isUtil(p: string): boolean {
        return p.includes("util") || p.includes("helper");
    }

    private isInterface(p: string): boolean {
        return ["ui", "screen", "layout", "gui", "view"].some(x => p.includes(x));
    }

    private isData(p: string): boolean {
        return p.includes("data") || p.includes("repository");
    }
}

export class ListRules {
    static ensureBlanks(lines: string[]): string[] {
        const isList = (l: string) => /^\s*([-*]|\d+\.)\s+/.test(l.replace(/^>\s*/, ""));
        return lines.reduce((acc: string[], line, i) => {
            const prefix = line.match(/^>\s*/)?.[0] || "";
            const prev = i > 0 ? lines[i - 1] : "";
            if (isList(line) && prev.replace(/^>\s*/, "").trim() !== "" && !isList(prev) && acc[acc.length - 1]?.trim() !== "") acc.push(prefix.trimEnd());
            acc.push(line);
            const next = lines[i + 1] || "";
            if (isList(line) && !isList(next) && next.replace(/^>\s*/, "").trim() !== "") acc.push(prefix.trimEnd());
            return acc;
        }, []);
    }
}

export class ResourceEngine {
    /**
     * Retorna o perfil estático de recursos baseado na capacidade total de hardware informada.
     */
    public getResourceProfile(cores: number, ramGb: number): { profile: string, parallelism: number, throttle: boolean } {
        if (ramGb >= 64) return { profile: "ELITE_MODE", parallelism: cores * 8, throttle: false };
        if (ramGb >= 32) return { profile: "GOD_MODE", parallelism: cores * 4, throttle: false };
        if (ramGb >= 16) return { profile: "SOVEREIGN", parallelism: cores * 2, throttle: false };
        if (ramGb >= 8) return { profile: "STANDARD", parallelism: cores, throttle: true };
        return { profile: "CONSTRAINED", parallelism: Math.max(1, Math.floor(cores / 2)), throttle: true };
    }

    /**
     * Coleta as métricas reais do Sistema Operacional neste instante.
     */
    public getCurrentLoad(): { freeMemoryGb: number; totalMemoryGb: number; loadAvg: number[]; cpuCores: number } {
        const freeMemoryGb = os.freemem() / (1024 ** 3);
        const totalMemoryGb = os.totalmem() / (1024 ** 3);
        const loadAvg = os.loadavg();
        const cpuCores = os.cpus().length;

        return { freeMemoryGb, totalMemoryGb, loadAvg, cpuCores };
    }

    /**
     * Determina se o sistema do host está em estado crítico (sobrecarga de RAM ou CPU).
     */
    public isSystemOverloaded(): { overloaded: boolean; reason?: string } {
        const metrics = this.getCurrentLoad();
        
        // Regra 1: Menos de 1.5GB de RAM livre
        if (metrics.freeMemoryGb < 1.5) {
            return { overloaded: true, reason: `Critically low memory: ${metrics.freeMemoryGb.toFixed(2)} GB free.` };
        }

        // Regra 2: Carga média da CPU nos últimos 1 minuto supera 90% dos cores disponíveis
        // (Apenas disponível em sistemas Unix-like, no Windows loadavg retorna [0,0,0])
        if (metrics.loadAvg[0] > (metrics.cpuCores * 0.90) && metrics.loadAvg[0] > 0) {
            return { overloaded: true, reason: `High CPU Load average: ${metrics.loadAvg[0].toFixed(2)}.` };
        }

        return { overloaded: false };
    }

    /**
     * Retorna um degrau de concorrência dinâmico. Se o sistema estiver sobrecarregado, recua.
     */
    public getDynamicConcurrency(baseConcurrency: number): number {
        const status = this.isSystemOverloaded();
        if (status.overloaded) {
            // Em estado crítico, cai para o mínimo operacional (1 ou 2 threads).
            return Math.max(1, Math.floor(baseConcurrency * 0.25)); 
        }
        
        // Se a memória livre estiver moderada (ex: entre 1.5GB e 3GB), aplica throttle leve (50%).
        const metrics = this.getCurrentLoad();
        if (metrics.freeMemoryGb < 3.0) {
            return Math.max(1, Math.floor(baseConcurrency * 0.5));
        }

        return baseConcurrency; // Todo gás
    }
}

export class DiscoveryAgent {
    orc: any; parser = new SourceCodeParser();
    constructor(orchestrator: any) { this.orc = orchestrator; }

    async runDiscoveryPhase(): Promise<[any, any[]]> {
        logger.info("🔭 Discovery Phase...");
        const root = this.orc.projectRoot.toString();
        const { results: raw, findings: goFindings } = await GoDiscoveryAdapter.scan(root, root, this.orc.hubManager);
        
        // Filtrar arquivos relevantes para o censo de soberania
        const filtered = raw.filter(f => {
            const p = f.path.replace(/\\/g, "/");
            return p.startsWith(`src_local/agents/`) || p.includes("app/src/main/java/") || p.includes("app/src/main/kotlin/");
        });
        const { agents, findings: enrichFindings } = await this.enrich(filtered, root);
        
        const findings: any[] = [...goFindings, ...enrichFindings];
        this.mapDisparities(this.groupByPersona(agents), findings);

        // Otimização Crítica: Usar os arquivos já encontrados pelo scanner nativo
        const allFiles = raw.map(f => path.join(root, f.path));
        const depth = await DepthIntelligence.calculateDepthAudit(root, allFiles, {});
        
        const ctx = await this.orc.contextEngine.analyzeProject();
        ctx.projectRoot = root; ctx.atomicUnits = agents; ctx.depthAudit = depth;
        findings.push(...await this.orc.runStrategicAudit(ctx, null, false), ...await this.orc.runObfuscationScan());
        return [ctx, findings];
    }

    private async enrich(raw: any[], root: string): Promise<{ agents: any[], findings: any[] }> {
        const findings: any[] = [];
        const agents = await Promise.all(raw.map(async f => {
            try {
                const c = await fs.promises.readFile(path.join(root, f.path), "utf-8");
                const a = await this.parser.analyze_file_logic(c, f.path);
                return a ? { ...f, units: [...(a.classes || []).map((n: any) => ({ name: n, type: "class", line: 1 })), ...(a.functions || []).map((n: any) => ({ name: n, type: "function", line: 1 }))] } : f;
            } catch (e: any) {
                findings.push({
                    file: f.path,
                    line: 1,
                    issue: `Falha ao processar arquivo durante descoberta: ${e.message}`,
                    severity: "HIGH",
                    agent: "discovery_agent",
                    role: "SYSTEM_ARCHITECT",
                    emoji: "🔭",
                    stack: "Infrastructure",
                    evidence: e.message,
                    category: "Discovery",
                    context: "DiscoveryAgent"
                });
                return f;
            }
        }));
        return { agents, findings };
    }

    private groupByPersona(files: any[]) {
        const g: Record<string, any[]> = {};
        files.forEach(f => {
            const b = path.basename(f.path);
            if (IGNORE_LIST.includes(b) || b.startsWith("__")) return;
            const id = b.replace(/\.[^/.]+$/, "").replace(/_?(persona|agent|system|engine)$/, "").toLowerCase();
            (g[id] ||= []).push(f);
        });
        return g;
    }

    private mapDisparities(groups: Record<string, any[]>, findings: any[]) {
        Object.entries(groups).forEach(([id, files]) => {
            if (files.length < 2) return;
            this.processGroupDisparities(id, files, findings);
        });
    }

    private processGroupDisparities(id: string, files: any[], findings: any[]) {
        const norm = (n: string) => n.toLowerCase().replace(/_/g, "").replace(/init/g, "constructor");
        const all = new Set<string>();
        files.forEach(f => (f.units || []).filter((u: any) => u.name.includes("Persona")).forEach((u: any) => all.add(norm(u.name))));

        files.forEach(f => {
            const cur = (f.units || []).map((u: any) => norm(u.name));
            const miss = Array.from(all).filter(u => !cur.includes(u));
            if (miss.length) {
                findings.push({ 
                    file: f.path, 
                    line: 1,
                    issue: `Persona '${id}' missing ${miss.length} units.`,
                    severity: "MEDIUM", 
                    agent: "discovery_agent",
                    role: "CORE_ARCHITECT",
                    emoji: "⚖️",
                    stack: "Parity",
                    evidence: `Missing: ${miss.join(", ")}`,
                    category: "AtomicParity" 
                });
            }
        });
    }

    private _getFiles(root: string) { return this.recursiveReaddir(root, [".ts", ".js", ".py", ".go", ".kt"]); }
    private recursiveReaddir(dir: string, exts: string[]): string[] {
        try {
            return fs.readdirSync(dir, { withFileTypes: true }).reduce((acc: string[], item) => {
                const full = path.join(dir, item.name);
                if (item.isDirectory()) return acc.concat(this.scanSubDir(full, exts));
                if (exts.includes(path.extname(item.name))) acc.push(full);
                return acc;
            }, []);
        } catch { return []; }
    }

    private scanSubDir(full: string, exts: string[]): string[] {
        const forbidden = /[\\/](\.git|node_modules|dist|artifacts|\.gemini)$/;
        return forbidden.test(full) ? [] : this.recursiveReaddir(full, exts);
    }
}

