export class StructuralAuditorSupreme {
    constructor() { }

    /**
     * Valida um arquivo TypeScript em busca de falhas estruturais.
     */
    public auditFile(sourceFile: ts.SourceFile, ctx: { domain: string; isTechnical: boolean }): any[] {
        const issues: any[] = [];

        // 1. Auditoria de Erros Silenciosos (Delegada)
        issues.push(...SilentErrorStrategy.audit(sourceFile));

        // 2. Scan de Nós Recursivo (Veto & Core Logic)
        this.walk(sourceFile, sourceFile, issues, ctx);

        return issues;
    }

    private walk(node: ts.Node, sourceFile: ts.SourceFile, issues: any[], ctx: { domain: string; isTechnical: boolean }): void {
        // Veto Strategy
        if (VetoStrategy.isVetoed(node, sourceFile, ctx)) return;

        // Custom structural checks can be added here

        ts.forEachChild(node, (child) => this.walk(child, sourceFile, issues, ctx));
    }

    /**
     * Interface de compatibilidade para o AuditExpertEngine.
     */
    public isInteractionSafe(content: string, line: number, riskType: string): { isSafe: boolean; reason: string } {
        // Implementação simplificada delegando para SafetyStrategy
        // Nota: A SafetyStrategy atual pode precisar de adaptação para aceitar número de linha
        return SafetyStrategy.isInteractionSafe(content, "temp.ts");
    }
}

export class TestDiscoveryStrategy {
    /**
     * Tenta encontrar o arquivo de teste para um módulo.
     */
    static findTestForModule(moduleName: string, mapData: Record<string, any>): any | null {
        const lowerName = moduleName.toLowerCase();
        for (const [file, info] of Object.entries(mapData)) {
            if (info.component_type === "TEST") {
                // Check if filename contains the module name
                if (file.toLowerCase().includes(lowerName)) {
                    return info;
                }
            }
        }
        return null;
    }
}

export class PyramidAnalyst {
    /**
     * Classifica os testes entre Unit, Integration e E2E.
     */
    async analyze(mapData: Record<string, any>, readFunc: (path: string) => Promise<string | null>): Promise<any> {
        winston.debug("Analysing test pyramid distribution...");
        const pyramid = { unit: 0, integration: 0, e2e: 0, total: 0 };

        for (const file of Object.keys(mapData)) {
            if (!file.includes("tests/")) continue;

            const content = await readFunc(file);
            if (!content) continue;

            pyramid.total += 1;
            if (content.includes("mock") || content.includes("patch")) {
                pyramid.integration += 1;
            } else if (content.includes("selenium") || content.includes("integration_test")) {
                pyramid.e2e += 1;
            } else {
                pyramid.unit += 1;
            }
        }

        return pyramid;
    }
}

export class CoreValidator {
    constructor(private orchestrator: any = null) {}

    /**
     * Valida a integridade do sistema baseado no contexto.
     */
    validateSystemIntegrity(context: any): { score: number; issues: any[] } {
        let score = 100;
        const issues: any[] = [];

        if (context?.map) {
            score -= this.calculateFragilityPenalty(context.map);
        }

        return { score: Math.max(0, score), issues };
    }

    private calculateFragilityPenalty(map: Record<string, any>): number {
        let penalty = 0;
        for (const info of Object.values(map)) {
            if (info.brittle) penalty += 5;
            if (info.silent_error) penalty += 10;
        }
        return penalty;
    }

    /**
     * Executa a bateria de testes internos de integridade.
     */
    async verifyCoreHealth(projectRoot: string, changedFiles: string[] = []): Promise<any> {
        const testsDir = join(projectRoot, "tests");

        if (!existsSync(testsDir)) {
            logger.info("🛡️ [Core] Protocolo de Auto-Exame ignorado: Pasta 'tests' não encontrada.");
            return { success: true, pass_rate: 100, total_run: 0, failed: 0, skipped: true };
        }

        logger.info("🛡️ [Core] Iniciando Protocolo de Auto-Exame Vital...");
        return this.runHealthTests(projectRoot, changedFiles);
    }

    private async runHealthTests(projectRoot: string, changedFiles: string[]): Promise<any> {
        try {
            const runner = new TestRunner();
            const result = (changedFiles.length > 0 && changedFiles.length < 10)
                ? await this.runSelectiveTests(runner, projectRoot, changedFiles)
                : await this.runFullSuite(runner, projectRoot);

            logger.info("📝 [Core] Consolidando resultados do auto-exame...");
            return result;
        } catch (error) {
            logger.error(`🚨 Falha crítica no protocolo de auto-exame: ${error}`);
            return { success: false, pass_rate: 0, total_run: 0, failed: 1, error: String(error) };
        }
    }

    private async runSelectiveTests(runner: TestRunner, root: string, files: string[]) {
        logger.info(`🧪 [Core] Executando Verificação Cirúrgica (Selective) para ${files.length} arquivos.`);
        return await runner.runSelectiveTests(root, files);
    }

    private async runFullSuite(runner: TestRunner, root: string) {
        logger.info(`🧪 [Core] Executando Protocolo de Aceleração (Full Suite) em: ${root}`);
        return await runner.runParallelDiscovery(root);
    }

    /**
     * ⚖️ Verifica Paridade de Plataforma (Legacy Compat).
     */
    private _check_platform_parity(context: any): boolean {
        return true;
    }

    /**
     * 📊 Analisa resultados brutos (Helper).
     */
    private _parse_results(results: any): any {
        if (!results.raw_output || typeof results.raw_output !== 'string') {
            return results;
        }

        const passed = this._extract_count(results.raw_output, /(\d+) pass/);
        const failed = this._extract_count(results.raw_output, /(\d+) fail/);

        return { ...results, passed, failed, total: passed + failed };
    }

    private _extract_count(text: string, regex: RegExp): number {
        const match = text.match(regex);
        return match ? parseInt(match[1] || "0") : 0;
    }
}

export class ScoringEngine {
    public calculateHealth(data: { files: Record<string, any>; alerts: any[]; totalFiles: number; avgComplexity: number; }): HealthScore {
        const { files, alerts, totalFiles, avgComplexity } = data;
        if (totalFiles === 0) return this._emptyScore();

        const s = this._calcStability(files, totalFiles);
        const p = this._calcPurity(avgComplexity);
        const o = this._calcObs(files, totalFiles);
        const sec = this._calcSecurity(alerts);
        const e = this._calcExcellence(files, totalFiles);
        const c = this._calcCompliance(sec.high, sec.med);

        const raw = s + p + o + sec.security + e + c;
        const constrained = this._applyConstraints(raw, sec);

        return this._format(constrained, s, p, o, sec.security, e, c);
    }

    private _emptyScore() {
        return { stability: 0, purity: 0, observability: 0, security: 0, excellence: 0, compliance: 0, total: 0 };
    }

    private _calcStability(f: any, t: number) {
        const tested = Object.values(f).filter((x: any) => x.has_test).length;
        return (tested / t) * 35;
    }

    private _calcPurity(a: number) {
        return Math.max(0, 15 - ((a - 1) * 1.5));
    }

    private _calcObs(f: any, t: number) {
        const observed = Object.values(f).filter((x: any) => x.component_type !== "TEST" && x.telemetry).length;
        return (observed / t) * 10;
    }

    private _calcExcellence(f: any, t: number) {
        const excellent = Object.values(f).filter((x: any) => x.purpose && x.purpose !== "UNKNOWN").length;
        return (excellent / t) * 10;
    }

    private _calcSecurity(a: any[]) {
        const c = { high: 0, med: 0, low: 0, strat: 0 };
        a.forEach(r => this.categorizeAlert(r, c));
        return { security: Math.max(0, 15 - (c.high * 5)), ...c };
    }

    private categorizeAlert(r: any, counts: any) {
        if (typeof r !== "object") {
            counts.strat++;
            return;
        }

        const sev = String(r.severity).toLowerCase();
        if (sev === "critical" || sev === "high") {
            counts.high++;
        } else if (sev === "medium") {
            counts.med++;
        } else {
            counts.low++;
        }
    }

    private _calcCompliance(h: number, m: number) {
        const level = this.getComplianceLevel(h, m);
        return POLICIES[level].vetoThreshold * 15;
    }

    private _applyConstraints(r: number, s: any) {
        const lvl = this.getComplianceLevel(s.high, s.med);
        const ceilings = {
            [ComplianceLevel.CRITICAL]: 20,
            [ComplianceLevel.DEGRADED]: 40,
            [ComplianceLevel.SUBSTANDARD]: 60,
            [ComplianceLevel.STANDARD]: 85,
            [ComplianceLevel.EXCELLENT]: 95,
            [ComplianceLevel.SOVEREIGN]: 100
        };
        const ceiling = (ceilings as any)[lvl] || 100;
        const penalty = ((s.high * 15) + (s.med * 5) + (s.low)) * 0.2;

        return Math.max(0, Math.min(r, ceiling) - penalty);
    }

    private _format(t: number, s: number, p: number, o: number, sec: number, e: number, c: number) {
        return {
            stability: +s.toFixed(2),
            purity: +p.toFixed(2),
            observability: +o.toFixed(2),
            security: +sec.toFixed(2),
            excellence: +e.toFixed(2),
            compliance: +c.toFixed(2),
            total: +t.toFixed(2)
        };
    }

    public getComplianceLevel(h: number, m: number): ComplianceLevel {
        if (h > 5) return ComplianceLevel.CRITICAL;
        if (h > 2) return ComplianceLevel.DEGRADED;
        if (h > 0) return ComplianceLevel.SUBSTANDARD;
        return this.getStandardCompliance(m);
    }

    private getStandardCompliance(m: number): ComplianceLevel {
        if (m > 5) return ComplianceLevel.STANDARD;
        if (m > 0) return ComplianceLevel.EXCELLENT;
        return ComplianceLevel.SOVEREIGN;
    }
}

export class SourceCodeParser {
    private tsParser: TypeScriptParser;
    private pyParser: PythonParser;
    private polyParser: PolyglotParser;

    constructor(private hubManager?: HubManagerGRPC) {
        this.tsParser = new TypeScriptParser(hubManager);
        this.pyParser = new PythonParser(hubManager);
        this.polyParser = new PolyglotParser(hubManager);
    }

    async analyzePy(content: string, filename: string) {
        try { return await this.pyParser.analyze(content, filename); }
        catch (e) { return { functions: [], classes: [], complexity: 1, dependencies: [] }; }
    }

    async analyzePyMetadata(content: string, filename: string) {
        try {
            const d = await this.analyzePy(content, filename);
            return {
                complexity: await this.pyParser.calculateComplexity(filename),
                dependencies: this.pyParser.extractImports(content),
                functions: d.functions,
                classes: d.classes
            };
        } catch (e) {
            return { complexity: 1, dependencies: [], functions: [], classes: [] };
        }
    }

    async analyzeTs(content: string, filename: string) {
        try { return await this.tsParser.analyze(content, filename); }
        catch (e) { return { functions: [], classes: [], complexity: 1, dependencies: [], tree: false }; }
    }

    async calculatePyComplexity(filename: string): Promise<number> { return await this.pyParser.calculateComplexity(filename); }
    extractPyImports(content: string): string[] { return this.pyParser.extractImports(content); }
    async calculateTsComplexity(filename: string): Promise<number> { return await this.tsParser.calculateComplexity(filename); }
    extractTsImports(content: string): string[] { return this.tsParser.extractImports(content); }
    async analyzeKt(content: string) { return this.polyParser.analyzeKt(content); }
    async calculateKtComplexity(filename: string): Promise<number> { return await this.polyParser.calculateKtComplexity(filename); }

    async analyze_file_logic(content: string, fileName: string) {
        const ext = fileName.split(".").pop()?.toLowerCase();
        if (ext === "py") return await this.analyzePy(content, fileName);
        if (ext === "ts" || ext === "js" || ext === "tsx") return await this.analyzeTs(content, fileName);
        if (ext === "kt") return { ...await this.analyzeKt(content), complexity: await this.calculateKtComplexity(fileName) };
        if (ext === "go") return { ...this.polyParser.analyzeGo(content), complexity: await this.polyParser.calculateGoComplexity(fileName) };
        if (ext === "dart") return this.polyParser.analyzeDart(content);
        return null;
    }

    mapComponentType(relPath: string): string {
        return ComponentMappingStrategy.mapType(relPath);
    }
}

