export class MarkdownUtil {
    /**
     * Evita headers duplicados adicionando sufixos de versão.
     */
    static deduplicateHeader(h: string, seen: Record<string, number>): string {
        // MD026: Pontuação proibida no final
        const hClean = h.replace(/[.!?: \t\n\r]+$/, "");

        const count = seen[hClean];
        if (count !== undefined) {
            const nextCount = count + 1;
            seen[hClean] = nextCount;
            return `${hClean} [v${nextCount}]`;
        }
        seen[hClean] = 1;
        return hClean;
    }

    /**
     * Garante espaçamento vertical após cabeçalhos (MD022).
     */
    static applyHeaderPadding(res: string[], raw: string[], idx: number): void {
        const nextLine = raw[idx + 1];
        if (nextLine !== undefined && nextLine.trim() !== "") {
            res.push("");
        }
    }
}

export class GPTLayer {
    static transformerBlock(
        li: number,
        x: Value[],
        stateDict: Record<string, Value[][]>,
        keys: Value[][][],
        values: Value[][][],
        nHead: number,
        headDim: number,
        lastAttentionWeights: number[][][]
    ): Value[] {
        let xResidual = x;
        x = ModelOps.rmsnorm(x);

        const q = ModelOps.linear(x, stateDict[`layer${li}.attn_wq`]!);
        const k = ModelOps.linear(x, stateDict[`layer${li}.attn_wk`]!);
        const v = ModelOps.linear(x, stateDict[`layer${li}.attn_wv`]!);

        keys[li]!.push(k);
        values[li]!.push(v);

        const xAttn = AttentionEngine.multiHead(li, q, keys[li]!, values[li]!, nHead, headDim, lastAttentionWeights);
        x = ModelOps.linear(xAttn, stateDict[`layer${li}.attn_wo`]!).map((a, i) => a.add(xResidual[i]!));

        xResidual = x;
        x = ModelOps.rmsnorm(x);
        x = ModelOps.linear(x, stateDict[`layer${li}.mlp_fc1`]!).map(xi => xi.relu());
        x = ModelOps.linear(x, stateDict[`layer${li}.mlp_fc2`]!).map((a, i) => a.add(xResidual[i]!));
        return x;
    }
}

export class VetoStrategy {
    /**
     * Determina se um nó deve ser ignorado na auditoria.
     */
    static isVetoed(node: ts.Node, sourceFile: ts.SourceFile, ctx: { domain: string; isTechnical: boolean; inDocstring?: boolean }): boolean {
        // 1. Veto de Comentários
        if (this.isComment(node)) return true;

        // 2. Veto de Docstrings (JSDoc)
        if (this.isDocstring(node, ctx)) return true;

        // 3. Veto por Domínio: Se for EXPERIMENTATION, ignorar não-críticos
        if (ctx.domain === "EXPERIMENTATION" && !this.isCriticalRisk(node)) {
            return true;
        }

        // 4. Veto de Definições Técnicas: Ignorar se estiver em contexto de regras
        if (ctx.isTechnical && this.isRuleDefinition(node)) {
            return true;
        }

        return false;
    }

    private static isComment(node: ts.Node): boolean {
        const text = node.getFullText();
        const trimmed = text.trim();
        return trimmed.startsWith("//") || trimmed.startsWith("/*");
    }

    private static isDocstring(node: ts.Node, ctx: { inDocstring?: boolean }): boolean {
        const text = node.getText();
        if (text.startsWith("/**") || text.startsWith("/*")) return true;
        return ctx.inDocstring || false;
    }

    private static isCriticalRisk(node: ts.Node): boolean {
        const text = node.getText().toLowerCase();
        return text.includes("eval(") || text.includes("exec(");
    }

    private static isRuleDefinition(node: ts.Node): boolean {
        const text = node.getText();
        return ["patterns", "rules", "regex", "diretriz"].some(kw => text.includes(kw));
    }
}

export class DeltaEngine {
    static compute(legacy: AtomicFingerprint, current: AtomicFingerprint, agent: string): AgentDelta[] {
        const deltas: AgentDelta[] = [];
        if (legacy.name.toLowerCase() !== current.name.toLowerCase())
            deltas.push({ dimension: "name", legacy: legacy.name, current: current.name, severity: "CRITICAL", context: `Agent identity mismatch for ${agent}` });

        if (legacy.rulesCount !== current.rulesCount)
            deltas.push({ dimension: "rulesCount", legacy: String(legacy.rulesCount), current: String(current.rulesCount), severity: "MEDIUM", context: `Rule count divergence` });

        if (legacy.hasReasoning !== current.hasReasoning)
            deltas.push({ dimension: "reasoning", legacy: String(legacy.hasReasoning), current: String(current.hasReasoning), severity: "CRITICAL", context: "Strategy logic MISSING" });

        const legacyMethods = legacy.methods.filter(m => !m.startsWith("_"));
        const currentMethods = current.methods || [];

        for (const lm of legacyMethods) {
            const camelName = lm.replace(/_([a-z])/g, (_, p1: string) => p1.toUpperCase());
            const match = currentMethods.find(cm => cm === lm || cm === camelName || cm.toLowerCase() === lm.replace(/_/g, "").toLowerCase());

            if (!match) {
                deltas.push({
                    dimension: "Method",
                    legacy: lm,
                    current: "MISSING",
                    severity: "HIGH",
                    context: `Method '${lm}' from legacy not found in current implementation.`
                });
            }
        }
        return deltas;
    }

    static computeScore(deltas: AgentDelta[]): number {
        let score = 100;
        const penalties = { CRITICAL: 50, HIGH: 30, MEDIUM: 15, INFO: 2 };
        for (const d of deltas) {
            score -= penalties[d.severity as keyof typeof penalties] || 0;
        }
        return Math.max(0, score);
    }
}

