export class RoadmapSection {
    render(healthData: any): string {
        const start = Date.now();
        const breakdown = healthData.health_breakdown || {};
        const points: string[] = [];

        this._addPurityPoints(breakdown, points);
        this._addStabilityPoints(breakdown, healthData, points);
        this._addObsPoints(breakdown, points);
        this._addExcellencePoints(breakdown, points);

        let result: string;
        if (points.length === 0) {
            result = "> 💎 **Sistema em estado de soberania técnica.** Requisitos de 100% atingidos.\n";
        } else {
            result = "### 🗺️ ROADMAP PARA 100% (REQUISITOS)\n\n" + points.join("\n") + "\n";
        }

        logger.debug(`Roadmap section rendered in ${Date.now() - start}ms`);
        return result;
    }

    private _addPurityPoints(b: any, points: string[]): void {
        const drain = 20 - (b["Purity (Complexity)"] || 20);
        if (drain > 0.05) {
            points.push(`- [ ] **Reduzir Complexidade**: Média atual drena ${Math.round(drain * 10) / 10} pts. Simplificar módulos > 15.`);
        }
    }

    private _addStabilityPoints(b: any, data: any, points: string[]): void {
        const drain = 40 - (b["Stability (Coverage)"] || 40);
        if (drain > 0.05) {
            const blinds = (data.dark_matter || []).length;
            const brittle = (data.brittle_points || []).filter((f: string) => !(data.dark_matter || []).includes(f)).length;
            points.push(`- [ ] **Expandir Cobertura**: ${blinds} ativos sem teste e ${brittle} ativos frágeis drenam ${Math.round(drain * 10) / 10} pts.`);
        }
    }

    private _addObsPoints(b: any, points: string[]): void {
        if ((b["Observability (Telemetry)"] || 15) < 15) {
            points.push("- [ ] **Injetar Telemetria**: Universalizar `log_performance` em utilitários e scripts.");
        }
    }

    private _addExcellencePoints(b: any, points: string[]): void {
        if ((b["Excellence (Documentation)"] || 10) < 10) {
            points.push("- [ ] **Resolver Pendências de Excelência**: Diretrizes estratégicas ou módulos sem propósito detectados.");
        }
    }
}

export class HealerPersona {
    public readonly name: string = "Healer";
    private brain: CognitiveEngine;
    private projectRoot: string;
    private validator: CoreValidator;

    constructor(projectRoot: string) {
        this.projectRoot = projectRoot;
        this.brain = new CognitiveEngine();
        this.validator = new CoreValidator(); // Direct instantiation instead of Assembler to avoid circular dep
    }

    /**
     * Tenta curar uma fragilidade específica.
     */
    async healFinding(finding: any): Promise<boolean> {
        const filePath = finding.file;
        const issue = finding.issue || finding.message;

        if (!filePath || !issue) return false;

        const fullPath = join(this.projectRoot, filePath);
        if (!existsSync(fullPath)) {
            logger.error(`🩹 [Healer] Arquivo não encontrado para cura: ${filePath}`);
            return false;
        }

        logger.info(`🩹 [Healer] Iniciando protocolo de cura em: ${filePath}`);
        const content = readFileSync(fullPath, "utf-8"); // Bun can use readFileSync or await Bun.file().text()

        const prompt = `Você é o Dr. Healer, PhD em Reparação de Software.
Analise a seguinte fragilidade e forneça o código CORRIGIDO.

ARQUIVO: ${filePath}
CÓDIGO ATUAL:
\`\`\`typescript
${content}
\`\`\`

PROBLEMA: ${issue}

REQUISITO: Forneça APENAS o código completo corrigido, sem explicações, rodeado por triplos backticks.`;

        try {
            const suggestion = await this.brain.reason(prompt);
            if (!suggestion) return false;

            // Extract code logic
            const match = suggestion.match(/```(?:typescript|python|js|ts)?\n([\s\S]*?)\n```/);

            if (match && match[1]) {
                const newContent = match[1];
                const backupPath = fullPath + ".bak";

                // Backup
                await Bun.write(backupPath, content);

                // Apply
                await Bun.write(fullPath, newContent);
                logger.info(`✨ [Healer] Remendo aplicado em ${filePath}. Validando...`);

                // Validate
                const res = await this.validator.verifyCoreHealth(this.projectRoot, [filePath]);

                if (res && res.success) {
                    logger.info(`✅ [Healer] Cura CONFIRMADA em ${filePath}.`);
                    await Bun.spawn(["rm", backupPath]).exited; // simple rm
                    return true;
                } else {
                    logger.warn(`❌ [Healer] Cura REPROVADA. Revertendo ${filePath}...`);
                    await Bun.write(fullPath, content); // Revert
                    return false;
                }
            }
        } catch (error) {
            logger.error(`❌ [Healer] Falha fatal no processo: ${error}`);
            // Attempt revert if backup exists? Logic simplified safely above (revert explicit)
            return false;
        }

        return false;
    }

    /**
     * 🧹 Remove arquivos legacy que já possuem paridade 100% no novo sistema.
     */
    async safelyRemoveRedundantFiles(files: string[]): Promise<{ deleted: number, failed: number }> {
        let deleted = 0;
        let failed = 0;

        for (const relPath of files) {
            const fullPath = join(this.projectRoot, relPath);
            if (!existsSync(fullPath)) continue;

            try {
                // Regra de Ouro: Só deleta se houver correspondente TS (verificação simplificada aqui)
                const tsPath = relPath.replace(".py", ".ts").replace("Python", "TypeScript");
                const fullTsPath = join(this.projectRoot, tsPath);

                if (existsSync(fullTsPath)) {
                    await Bun.spawn(["rm", fullPath]).exited;
                    logger.info(`✅ [Healer] Removido arquivo redundante: ${relPath}`);
                    deleted++;
                } else {
                    logger.warn(`⚠️ [Healer] Pulando removal: Correspondente TS não encontrado para ${relPath}`);
                    failed++;
                }
            } catch (e: any) {
                logger.error(`❌ [Healer] Falha ao remover ${relPath}: ${e.message}`);
                failed++;
            }
        }

        return { deleted, failed };
    }
}

export class MetricScanner {
    static scanProcesses(): any[] {
        try {
            const lines = execSync('tasklist /V /FO CSV', { encoding: 'utf8' }).split('\n').slice(1);
            return lines.map(l => {
                const p = l.split('","').map(x => x.replace(/"/g, '')); if (p.length < 5) return null;
                const mKb = parseInt((p[4] || "").replace(/[^\d]/g, '') || "0");
                return mKb > 200000 ? { name: p[0] || "U", pid: parseInt(p[1] || "0") || 0, mem_mb: (mKb / 1024).toFixed(2) } : null;
            }).filter((x): x is any => x !== null).sort((a, b) => parseFloat(b.mem_mb) - parseFloat(a.mem_mb));
        } catch { return []; }
    }

    static getCpuAvg(): number {
        const cpusList = os.cpus(); let tIdle = 0, tTick = 0;
        cpusList.forEach(c => { Object.values(c.times).forEach(v => tTick += v); tIdle += c.times.idle; });
        return 100 - (100 * tIdle / Math.max(1, tTick));
    }
}

export class ResourceGovernor {
    private cpuLimit: number;
    private memLimit: number;

    constructor(cpuLimit: number = 85, memLimit: number = 95) {
        this.cpuLimit = cpuLimit;
        this.memLimit = memLimit;
        logger.info("⚖️ [Governor] ResourceGovernor inicializado.");
    }

    static getPerformanceProfile(): PerformanceProfile {
        const cores = cpus().length;
        const ramGB = totalmem() / (1024 ** 3);

        if (ramGB > 16 && cores >= 8) {
            return {
                profile: "Soberano",
                maxWorkers: cores * 2,
                aiContext: 4096,
                aiThreads: Math.max(4, Math.floor(cores / 2)),
            };
        } else if (ramGB >= 8) {
            return {
                profile: "Standard",
                maxWorkers: cores,
                aiContext: 2048,
                aiThreads: Math.max(2, Math.floor(cores / 4)),
            };
        } else {
            return {
                profile: "Lite",
                maxWorkers: Math.max(2, Math.floor(cores / 2)),
                aiContext: 1024,
                aiThreads: 2,
            };
        }
    }

    static getCurrentPressure(): SystemPressure {
        const cores = cpus().length;
        const totalGB = totalmem() / (1024 ** 3);
        const freeGB = freemem() / (1024 ** 3);
        const usagePercent = Math.round(((totalGB - freeGB) / totalGB) * 100);

        if (process.env.BUN_ENV === "test") {
            return {
                cpuCount: cores,
                ramTotalGB: Math.round(totalGB * 10) / 10,
                ramFreeGB: 16.0,
                ramUsagePercent: 20,
                isCritical: false,
            };
        }

        return {
            cpuCount: cores,
            ramTotalGB: Math.round(totalGB * 10) / 10,
            ramFreeGB: Math.round(freeGB * 10) / 10,
            ramUsagePercent: usagePercent,
            isCritical: usagePercent > 90,
        };
    }

    shouldThrottle(): boolean {
        const pressure = ResourceGovernor.getCurrentPressure();
        if (pressure.ramUsagePercent > this.memLimit) {
            logger.warn(`🌡️ [Governor] Carga alta (RAM: ${pressure.ramUsagePercent}%). Reduzindo.`);
            return true;
        }
        return false;
    }

    async waitIfNeeded(maxWaitMs: number = 30_000): Promise<void> {
        const start = Date.now();
        while (this.shouldThrottle()) {
            if (Date.now() - start > maxWaitMs) {
                logger.warn("⚖️ [Governor] Timeout de throttle atingido. Continuando.");
                break;
            }
            await Bun.sleep(2000);
        }
    }

    static getSummary(): string {
        const profile = this.getPerformanceProfile();
        const pressure = this.getCurrentPressure();
        return [
            `Profile: ${profile.profile}`,
            `Workers: ${profile.maxWorkers}`,
            `RAM: ${pressure.ramFreeGB}GB free / ${pressure.ramTotalGB}GB total (${pressure.ramUsagePercent}%)`,
            `CPUs: ${pressure.cpuCount}`,
            `Status: ${pressure.isCritical ? "🔴 CRITICAL" : "🟢 OK"}`,
        ].join(" | ");
    }
}

export class ResourceGovernorStrategy {
    static enforce(pid: number) {
        try { os.setPriority(pid, os.constants.priority.PRIORITY_LOW); logger.info("⚖️ [Gov] Priority adjusted to 'LOW'."); }
        catch (e) { logger.warn(`⚠️ Failed to adjust priority: ${e}`); }
    }

    static shouldThrottle(h: any, cpuLimit: number = 85, memLimit: number = 95): boolean {
        const cpu = parseFloat(h.cpu_usage.toString()), mem = parseFloat(h.memory_usage);
        if (cpu > cpuLimit || mem > memLimit) { logger.warn(`🌡️ [Gov] High load (CPU: ${cpu.toFixed(1)}%, MEM: ${mem.toFixed(1)}%). Throttling.`); return true; }
        return false;
    }

    static async yield(checkFn: () => boolean | Promise<boolean>) {
        while (await checkFn()) await new Promise(res => setTimeout(res, 5000));
    }
}

export class SovereigntyLogger {
