export class BattlePlanSectionsEngine {
    formatSeverityGroup(sev: string, items: any[], itemFormatter: (item: any, sev: string) => string): string {
        const startT = Date.now();
        const fileGroups = items.reduce((acc: any, item) => {
            const name = (item?.file) || "Sistêmico";
            (acc[name] ||= []).push(item);
            return acc;
        }, {});

        let res = `## 🚩 NÍVEL: ${sev}\n\n`;
        Object.entries(fileGroups).forEach(([fname, group]: any) => {
            res += `### 📂 Alvo: \`${fname}\` [${sev}]\n\n`;
            group.forEach((item: any) => res += itemFormatter(item, sev));
        });

        logger.debug(`Telemetry: Formatted ${sev} group in ${Date.now() - startT}ms`);
        return res.trim();
    }

    filterActiveResults(auditResults: any[], keyGen: (item: any) => string): any[] {
        const seen = new Set<string>();
        const dedup = auditResults.filter(i => {
            const key = keyGen(i);
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        });

        return dedup.filter(i => (i?.severity !== 'HEALED'));
    }

    /** Parity: format_item_entry — Formats a single audit finding as a markdown entry. */
    format_item_entry(item: any, sev: string): string {
        const icon = sev === "CRITICAL" ? "🔴" : sev === "HIGH" ? "🟠" : sev === "MEDIUM" ? "🟡" : "🟢";
        const file = item?.file || "Global";
        const issue = item?.issue || String(item);
        return `- ${icon} **[${sev}]** \`${file}\`: ${issue}\n`;
    }
}

export class MarkdownSanitizer {
    public async sanitize(content: string): Promise<string> {
        if (!content) return "";
        const startTime = Date.now();

        let internalContent = content.replace(/^\ufeff+/, '').replace(/\r\n/g, "\n").trim();
        let lines = internalContent.split("\n");

        const structureAgent = new MarkdownStructureAgent(lines);
        lines = structureAgent.executeRefinement();

        // Aplicação de políticas via StyleRules
        lines = this.cleanup(lines);
        lines = StyleRules.ensureBlanksAroundHeadings(lines);
        lines = StyleRules.ensureBlanksAroundLists(lines);
        lines = StyleRules.ensureBlanksAroundTables(lines);
        lines = StyleRules.ensureBlockquoteContinuity(lines);
        lines = this.ensureH1(lines);

        const sanitized = lines.join("\n").trim() + "\n";
        logger.info(`📝 Markdown Sanitized em ${Date.now() - startTime}ms`);

        return sanitized;
    }

    private cleanup(lines: string[]): string[] {
        while (lines.length > 0 && lines[0]!.trim().length === 0) lines.shift();
        while (lines.length > 0 && lines[lines.length - 1]!.trim().length === 0) lines.pop();
        return lines;
    }

    private ensureH1(lines: string[]): string[] {
        if (lines.length === 0) return ["# 🏛️ RELATÓRIO SISTÊMICO", ""];
        if (lines[0]!.trim().startsWith("# ")) return lines;

        for (let i = 0; i < lines.length; i++) {
            if (lines[i]!.trim().startsWith("# ")) {
                const [h1] = lines.splice(i, 1);
                return [h1!, "", ...lines];
            }
        }
        return ["# 🏛️ RELATÓRIO SISTÊMICO", "", ...lines];
    }
}

