export class AnalysisPolicy {
    private static IGNORED_DIRS = new Set(['.git', '__pycache__', 'build', 'node_modules', '.venv', '.gemini', '.idea', '.vscode', 'dist', 'out']);

    static shouldIgnore(path: Path): boolean {
        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();

        // Bloqueio cirúrgico para infraestrutura .agent
        if (pathStr.includes("/.agent/") || pathStr.startsWith(".agent/")) {
            // Só permitimos se pertencer à skill autorizada
            if (pathStr.includes("fast-android-build")) return false;
            return true;
        }

        return Array.from(this.IGNORED_DIRS).some(p => pathStr.includes(`/${p}/`) || pathStr.endsWith(`/${p}`));
    }

    static isAnalyable(path: Path): boolean {
        const name = path.name();
        return (name.endsWith('.py') || name.endsWith('.ts') || name.endsWith('.tsx') || name.endsWith('.js') || name.endsWith('.yaml') || name.endsWith('.kt') || name.endsWith('.dart'));
    }
}

export class VetoEngine {
    public shouldVeto(relPath: string): { veto: boolean; reason?: VetoReason; justification?: string } {
        const ignored = ['.git', '__pycache__', 'build', 'node_modules', '.venv', '.agent', '.gemini', 'submodules', 'dist', 'target', 'bin'];
        const parts = relPath.split(/[/\\]/);

        if (parts.some(part => ignored.includes(part))) {
            return { veto: true, reason: VetoReason.INFRASTRUCTURE, justification: "Caminho de infraestrutura ignorado." };
        }

        if (relPath.endsWith(".pyc") || relPath.endsWith(".o") || relPath.endsWith(".exe") || relPath.endsWith(".dll") || relPath.endsWith(".class")) {
            return { veto: true, reason: VetoReason.LEGACY_ARTIFACT, justification: "Binário ou cache legado detectado." };
        }

        if (relPath.includes("/secrets/") || relPath.includes("/internal/keys/")) {
            return { veto: true, reason: VetoReason.SECURITY_RISK, justification: "Acesso a subdiretório de segredos protegido." };
        }

        return { veto: false };
    }

    public isTechnicalMath(lineContent: string, issue: string): boolean {
        if (!issue.includes("Imprecisão Monetária")) return false;

        const techTerms = [
            'alpha', 'progress', 'offset', 'dp', 'sp', 'radius', 'velocity',
            'phase', 'amplitude', 'frequency', 'duration', 'x', 'y', 'width', 'height',
            'sigma', 'delta', 'theta', 'gamma', 'epsilon', 'lambda', 'mu', 'nu',
            'integral', 'derivative', 'matrix', 'tensor', 'scalar', 'vector'
        ];
        const lower = lineContent.toLowerCase();

        const moneyTerms = ['price', 'amount', 'balance', 'cost', 'total', 'euro', 'usd', 'brl', 'payment', 'transaction', 'wallet', 'currency'];
        if (moneyTerms.some(f => lower.includes(f))) {
            return false;
        }

        return techTerms.some(t => new RegExp(`\\b${t}\\b`).test(lower));
    }

    public isRuleDefinition(lineContent: string): boolean {
        const lower = lineContent.toLowerCase();
        const keywords = [
            "rules =", "patterns =", "audit_rules =", "regex =",
            "silent_pattern =", "brittle_pattern =", "heuristic =",
            "veto_criteria =", "security_policy =", "compliance_check =",
            "validation_logic =", "rule_registry ="
        ];
        return keywords.some(kw => lower.includes(kw));
    }
}

export class MetaAnalysisStrategy {
    /**
     * Detecta padrões de Meta-Análise (Introspecção, AST, Eval).
     */
    static audit(node: ts.Node, sourceFile: ts.SourceFile): { isMeta: boolean, reason: string } {
        if (ASTIntelligence.isNodeSafe(node, sourceFile)) return { isMeta: false, reason: "" };

        const text = node.getText();
        // Detectar uso de TS Compiler API fora de agentes autorizados
        if (text.includes("ts.createSourceFile") || text.includes("ts.forEachChild")) {
            return { isMeta: true, reason: "Meta-análise detectada (Uso de TypeScript Compiler API)." };
        }
        // Detectar eval/Function
        if (text.includes("eval(") || text.includes("new Function(")) {
            return { isMeta: true, reason: "Meta-análise detectada (Execução dinâmica de código)." };
        }

        return { isMeta: false, reason: "" };
    }
}

export class MaturityEvaluator {
    structuralAnalyst: any;

    constructor(structuralAnalyst?: any) {
        this.structuralAnalyst = structuralAnalyst;
        logger.debug("🎓 [Maturity] Inicializando avaliador de competência técnica.");
    }

    async evaluatePersona(projectRoot: string, stack: string, name: string): Promise<any> {
        logger.info(`🎓 [Maturity] Analisando DNA da persona: ${name} (${stack})`);

        const personaPath = new Path(projectRoot).join("src_local", "agents", stack);
        const results = await this.scanPersonaDirectory(personaPath, stack);

        const normalizedScore = results.count > 0 ? (results.score / results.count).toFixed(2) : 0;

        return {
            name,
            stack,
            files_analyzed: results.count,
            maturity_index: Number(normalizedScore),
            status: Number(normalizedScore) >= 3 ? "GOLD" : (Number(normalizedScore) >= 2 ? "STABLE" : "FRAGILE"),
            details: results.details
        };
    }

    private async scanPersonaDirectory(path: Path, stack: string): Promise<{ score: number, count: number, details: any }> {
        const results = { score: 0, count: 0, details: {} as any };
        const pathStr = path.toString();

        if (!(await this.dirExists(pathStr))) return results;

        try {
            const entries = await import("fs/promises").then(fs => fs.readdir(pathStr, { withFileTypes: true }));
            for (const entry of entries) {
                await this.processPersonaEntry(path, entry, stack, results);
            }
        } catch (e) {
            logger.warn(`🎓 [Maturity] Erro ao ler diretório da persona: ${e}`);
        }

        return results;
    }

    private async dirExists(pathStr: string): Promise<boolean> {
        return (await Bun.file(pathStr).exists()) || (await import("fs").then(fs => fs.existsSync(pathStr)));
    }

    private async processPersonaEntry(parentPath: Path, entry: any, stack: string, results: any) {
        if (!entry.isFile() || !(entry.name.endsWith(".ts") || entry.name.endsWith(".py"))) return;

        results.count++;
        const content = await Bun.file(parentPath.join(entry.name).toString()).text();
        const fileMaturity = this.calculateMaturity(content, stack);
        results.score += fileMaturity.score;
        results.details[entry.name] = fileMaturity;
    }

    calculateMaturity(content: string, stack: string): any {
        const evidences = {
            has_telemetry: ["startMetrics", "endMetrics", "logPerformance", "winston", "logger"].some(kw => content.includes(kw)),
            has_reasoning: content.includes("reasonAboutObjective") || content.includes("brain.reason"),
            has_pathlib: content.includes("Path(") || content.includes("path_utils") || content.includes("node:path"),
            is_linear_syntax: /rules\s*[=:]|patterns\s*[=:]|mapping\s*[=:]/i.test(content),
            has_self_diagnostic: content.includes("selfDiagnostic")
        };

        const score = Object.values(evidences).filter(Boolean).length;
        logger.debug(`🎓 [Maturity] Score calculado: ${score}/4 para ${stack}`);

        return {
            score,
            level: score >= 3 ? "PROFUNDO" : (score >= 2 ? "ESTÁVEL" : "FRÁGIL"),
            ...evidences
        };
    }
}

export class QualitySection {
    render(breakdown: any): string[] {
        const start = Date.now();
        const lines: string[] = [];

        const metrics = [
            { id: "cc", label: "Complexidade Ciclomática (CC > 20)", limit: "> 20", key: "cc" },
            { id: "cog", label: "Complexidade Cognitiva (> 15)", limit: "> 15", key: "cog" },
            { id: "nest", label: "Aninhamento Profundo (> 3)", limit: "> 3", key: "nest" },
            { id: "cbo", label: "Alto Acoplamento (CBO > 10)", limit: "> 10", key: "cbo" },
            { id: "dit", label: "Herança Profunda (DIT > 5)", limit: "> 5", key: "dit" },
            { id: "miLow", label: "Baixa Manutenibilidade (MI < 10)", limit: "< 10", key: "miLow" },
            { id: "miCrit", label: "Manutenibilidade Crítica (MI < 5)", limit: "< 5", key: "miCrit" },
            { id: "defect", label: "Defect Density (> 1/KLOC)", limit: "> 1", key: "defect" },
            { id: "gateRed", label: "Quality Gate RED", limit: "-", key: "gateRed" },
            { id: "shadow", label: "Shadow Non-Compliant", limit: "-", key: "shadow" }
        ];

        const p = this._extractValues(breakdown, "Quality (", ")");
        const c = this._extractValues(breakdown, "_raw_", "Count");
        const total = breakdown["_raw_totalAnalyzed"] || 0;
        const totalPenalty = Math.round(Object.values(p).reduce((a: any, b: any) => a + b, 0) * 10) / 10;

        if (totalPenalty > 0 || total > 0) {
            lines.push("### 📐 Métricas de Qualidade (NIST/SONARQUBE)", "");
            lines.push("| Métrica | Limite | Violações | Penalidade |", "| :--- | :--- | :---: | ---: |");
            metrics.forEach(m => lines.push(`| ${m.label} | ${m.limit} | ${c[m.id] || 0}/${total} | ${p[m.id] || 0} pts |`));
            lines.push("", `> **Penalidade Total de Qualidade:** \`${totalPenalty} pts\` (cap: 30) | Base: NIST, SonarQube, Microsoft`, "");
        }

        logger.debug(`Quality section rendered in ${Date.now() - start}ms`);
        return lines;
    }

    private _extractValues(breakdown: any, prefix: string, suffix: string): Record<string, number> {
        const map: any = {
            cc: "cc", cog: "cognitive", nest: "nesting", cbo: "cbo",
            dit: "dit", miLow: "miLow", miCrit: "miCritical",
            defect: "defect", gateRed: "gateRed", shadow: "shadow"
        };
        const res: Record<string, number> = {};
        Object.entries(map).forEach(([short, long]) => {
            const key = prefix === "Quality (" ? `${prefix}${this._getQualityKey(short)}${suffix}` : `${prefix}${long}${suffix}`;
            res[short] = breakdown[key] || 0;
        });
        return res;
    }

    private _getQualityKey(short: string): string {
        const keys: any = {
            cc: "CC > 20 - High Risk", cog: "Cognitive > 15", nest: "Nesting > 3",
            cbo: "CBO > 10 - High Coupling", dit: "DIT > 5 - Deep Inheritance",
            miLow: "MI < 10 - Low Maint", miCrit: "MI < 5 - Critical",
            defect: "Defect Density > 1/KLOC", gateRed: "Gate RED", shadow: "Shadow Non-Compliant"
        };
        return keys[short] || short;
    }
}

export class DisparityScanner {
    async scanDir(dir: string, root: string, isLegacy: boolean, ignoreList: string[]): Promise<FileAnalysis[]> {
        const entries = await readdir(dir, { withFileTypes: true });
        const nested = await Promise.all(entries.map(e => this.processEntry(dir, e, root, isLegacy, ignoreList)));
        return nested.flat().filter((x): x is FileAnalysis => x !== null);
    }

    private async processEntry(dir: string, ent: any, root: string, isLegacy: boolean, ignoreList: string[]): Promise<FileAnalysis | FileAnalysis[] | null> {
        const full = join(dir, ent.name);
        if (ent.isDirectory()) return this.handleDir(ent, full, root, isLegacy, ignoreList);
        return this.handleFile(ent, full, root, isLegacy, ignoreList);
    }

    private async handleDir(ent: any, full: string, root: string, isLegacy: boolean, ignoreList: string[]): Promise<FileAnalysis[] | null> {
        if (!this.shouldScanDir(ent.name)) return null;
        return this.scanDir(full, root, isLegacy, ignoreList);
    }

    private async handleFile(ent: any, full: string, root: string, isLegacy: boolean, ignoreList: string[]): Promise<FileAnalysis | null> {
        if (!this.shouldScanFile(ent.name, isLegacy, ignoreList)) return null;
        const rel = relative(root, full).replace(/\\/g, "/");
        const content = await readFile(full, "utf-8");
        return {
            path: rel,
            units: isLegacy ? await PythonParser.parse(content, full) : await TypescriptParser.parse(content, full)
        };
    }

    private shouldScanDir(name: string): boolean {
        return !name.match(/^(__pycache__|node_modules|\.)/);
    }

    private shouldScanFile(name: string, isLegacy: boolean, ignoreList: string[]): boolean {
        const ext = isLegacy ? ".py" : ".ts";
        return name.endsWith(ext) && !ignoreList.includes(name);
    }

    compare(legacy: FileAnalysis[], restore: FileAnalysis[], mappings: Record<string, string>): { missingFiles: number, gaps: number, reportLines: string[] } {
        let mF = 0, mG = 0;

        legacy.forEach(l => {
            const t = this.findMatchingFile(l, restore, mappings);
            if (!t) {
                mF++;
            } else {
                mG += this.countGaps(l, t);
            }
        });

        const report = [`- Legacy Files: ${legacy.length}`, `- Missing: ${mF}`, `- Gaps: ${mG}`];
        return { missingFiles: mF, gaps: mG, reportLines: report };
    }

    private findMatchingFile(l: FileAnalysis, restore: FileAnalysis[], mappings: Record<string, string>): FileAnalysis | undefined {
        const lName = basename(l.path);
        const tPath = mappings[lName] || lName.replace(".py", ".ts").toLowerCase();
        return restore.find(f => f.path.endsWith(tPath));
    }

    private countGaps(l: FileAnalysis, t: FileAnalysis): number {
        const legacyMethods = l.units.filter(u => u.type === "method" && !u.name.startsWith("__"));
        const gaps = legacyMethods.filter(lm => !this.hasMatch(lm, t.units));
        return gaps.length;
    }

    private hasMatch(lm: AtomicUnit, units: AtomicUnit[]): boolean {
        const camelName = lm.name.replace(/_([a-z])/g, (_, g1) => (g1 || "").toUpperCase());
        return units.some(tm => tm.name === lm.name || tm.name === camelName);
    }
}

export class Orchestrator {
    projectRoot: Path;
    lastDetectedChanges: string[] = [];
    metrics: SystemMetrics;
    personas: IAgent[] = [];
    private agentRegistry: Map<string, IAgent> = new Map();

    // Core Engines
    contextEngine!: ContextEngine;
    cacheManager!: CacheManager;
    executor!: TaskExecutor;
    auditEngine!: AuditEngine;
    stabilityLedger!: StabilityLedger;
    historyAgent!: HistoryAgent;
    coreValidator!: CoreValidator;
    synthesizer!: IHealthSynthesizer;
    taskQueue!: TaskQueue;
    memoryEngine!: MemoryEngine;
    reflexEngine!: ReflexEngine;
    updateTransaction!: UpdateTransaction;
    sentinel!: SystemSentinel;
    behaviorAnalyst!: BehaviorAnalyst;
    worker!: TaskWorker;
    predictorEngine!: PredictorEngine;
    hubWatcher!: HubWatcher;
    hubManager!: HubManagerGRPC;
    registryManager!: RegistryManager;
    parityDaemon!: ParityDaemon;
    testEngine!: TestEngine;
    docEngine!: DocEngine;
    private governance: PhdGovernanceSystem;

    public ready: Promise<void>;

    constructor(projectRoot: string) {
        this.projectRoot = new Path(projectRoot);
        this.metrics = {
            files_scanned: 0,
            health_score: 100,
            start_time: Date.now(),
            efficiency: {}
        };
        this.hubManager = HubManagerGRPC.getInstance();
        this.registryManager = new RegistryManager(projectRoot);
        this.governance = PhdGovernanceSystem.getInstance();
        this.docEngine = new DocEngine(this.hubManager);
        this.initializeEngines(projectRoot);
        this._registerAgents();
        this._initEngines();
        this._initTools();
        this._registerEventListeners();
        
        const gov = PhdGovernanceSystem.getInstance();
        const load = gov.getCurrentLoad();
        logger.info(`🌐 [Sovereign Governance] Consciência de Setup iniciada: ${load.cpuCores} Cores | ${load.totalMemoryGb.toFixed(2)}GB RAM Total | Livres: ${load.freeMemoryGb.toFixed(2)}GB.`);

        this.ready = this._initNativeInfrastructure(projectRoot);
    }

    /**
     * Registers event listeners on the global Event Bus.
     * This is the Orchestrator's side of the Mediator pattern.
     */
    private _registerEventListeners(): void {
        eventBus.on("system:halt-experimentation", () => {
            logger.warn("🚨 [Orchestrator] Recebido evento de emergência. Travando experimentações...");
            for (const persona of this.personas) {
                if ('haltExperimentation' in persona && typeof (persona as any).haltExperimentation === 'function') {
                    (persona as any).haltExperimentation();
                }
            }
        });
    }

    private async _initNativeInfrastructure(projectRoot: string): Promise<void> {
        try {
            const { SystemManager } = await import("./system_manager.ts");
            const sm = SystemManager.getInstance();
            
            logger.info("🛠️ [Orchestrator] Inicializando Ciclo de Vida do Sistema...");
            const ready = await sm.ensureInfrastructure(projectRoot);
            
            if (!ready) {
                logger.warn("⚠️ [Orchestrator] Infraestrutura nativa não está 100% pronta. Operando em modo degradado.");
            }

            await this._waitForHub();

            this.hubWatcher = new HubWatcher();
            this.hubWatcher.onChange(async (p) => {
                console.log(`📡 [Orchestrator] Auditando mudança detectada em: ${p}`);
                this.lastDetectedChanges.push(p);
                // Trigger auto-refresh
                await this._updateCache();
                await this.runStagedAudit({ dryRun: false });
            });
            this.hubWatcher.start();

            this.parityDaemon = new ParityDaemon(projectRoot, this.hubWatcher, this.stabilityLedger, this.hubManager);
            this.parityDaemon.start();
        } catch (err: any) {
            console.error(`❌ [Orchestrator] Erro ao carregar infrastructure_assembler: ${err.message}`);
        }
    }

    private async _waitForHub(retries = 5) {
        for (let i = 0; i < retries; i++) {
            if (await this.hubManager.isHealthy()) {
                console.log("✅ [Orchestrator] Native Sovereign Hub (gRPC) conectado.");
                return;
            }
            console.log(`⏳ [Orchestrator] Aguardando Hub gRPC (${i + 1}/${retries})...`);
            await new Promise(r => setTimeout(r, 1000));
        }
    }

    private initializeEngines(root: string) {
        this.cacheManager = new CacheManager(root);
        this.executor = new TaskExecutor();
        this.contextEngine = new ContextEngine(root, this.hubManager);
        this.auditEngine = new AuditEngine(this);
        this.stabilityLedger = new StabilityLedger(root);
        this.historyAgent = new HistoryAgent(root);
        this.taskQueue = new TaskQueue(5, this.hubManager);
        this.memoryEngine = new MemoryEngine(root, this.hubManager);
        this.reflexEngine = new ReflexEngine();
        this.updateTransaction = new UpdateTransaction();
        this.sentinel = new SystemSentinel();
        this.behaviorAnalyst = new BehaviorAnalyst(root);
        this.worker = new TaskWorker(this.taskQueue, this);
        this.predictorEngine = new PredictorEngine(root);
        this.testEngine = new TestEngine(root);
    }

    private _registerAgents() {
        // Agents are now resolved via identity_census.json and dispatched through engines.
    }

    async dispatch(agentId: string, context: ProjectContext = {}): Promise<any> {
