        if (!agent) {
            logger.warn(`⚠️ [Orchestrator] Agent ${agentId} não encontrado.`);
            return null;
        }

        if (agent.initialize) await agent.initialize();
        return await agent.execute(context);
    }

    recordSystemEvent(eventName: string): void {
