    async requestPeerReview(requesterId: string, targetPersonaId: string, filePath: string, context: string, priority: string = "MEDIUM") {
        return this._call(async (meta) => {
            const { response } = await this.client.requestPeerReview({
                requesterId,
                targetPersonaId,
                filePath,
                context,
                priority
            }, { meta });
            return response;
        }, "requestPeerReview");
    }

    /**
     * Terminates the underlying gRPC transport.
     */
    close() {
        // @ts-ignore - plugin-specific transport cleanup if available
        if (this.transport && typeof this.transport.dispose === "function") {
            (this.transport as any).dispose();
        }
        logger.info("🔌 HubManagerGRPC transport closed.");
    }

    /**
     * 🧹 Suporte ao operador 'await using' do TypeScript / Bun (Explicit Resource Management).
     */
    public async [Symbol.asyncDispose](): Promise<void> {
        this.close();
    }
}

export class StructuralAnalyst {
    maturityEvaluator: MaturityEvaluator;
    parser: SourceCodeParser;
    classifier: ComponentClassifier;
    integrityGuardian: IntegrityGuardian;
    logicAuditor: any;
    inspector: any;

    constructor(private hubManager?: HubManagerGRPC) {
        this.maturityEvaluator = new MaturityEvaluator();
        this.parser = new SourceCodeParser(hubManager);
        this.classifier = new ComponentClassifier();
        this.integrityGuardian = new IntegrityGuardian();

        try {
            const { LogicAuditor } = require("./logic_auditor.ts");
            this.logicAuditor = new LogicAuditor();
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to load LogicAuditor: ${error}`);
            this.logicAuditor = null;
        }

        // Placeholder for inspector
        this.inspector = { scanFileLogic: () => [] };
    }

    async analyzePython(content: string, filename: string): Promise<FileAnalysis> {
        const startT = Date.now();
        const res = await this.parser.analyzePyMetadata(content, filename);

        const duration = (Date.now() - startT) / 1000;
        logger.debug(`⏱️ [StructuralAnalyst] Decomposição ${filename} in ${duration.toFixed(4)}s`);
        return {
            ...res,
            telemetry: ["telemetry", "log_performance", "winston", "logger"].some(kw => content.includes(kw))
        };
    }

    mapComponentType(relPath: string): string {
        try {
            return this.classifier.mapType(relPath);
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to map component type for ${relPath}: ${error}`);
            return 'unknown';
        }
    }

    shouldIgnore(path: Path): boolean {
        return AnalysisPolicy.shouldIgnore(path);
    }

    isAnalyable(path: Path): boolean {
        return AnalysisPolicy.isAnalyable(path);
    }

    async readProjectFile(path: string): Promise<string | null> {
        try {
            return await Bun.file(path).text();
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to read file ${path}: ${error}`);
            return null;
        }
    }

    calculateMaturity(content: string, stack: string): any {
        try {
            return this.maturityEvaluator.calculateMaturity(content, stack);
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to calculate maturity: ${error}`);
            return null;
        }
    }

    /**
     * 🧠 Analisa falhas lógicas profundas (Wrapper LogicAuditor via Rust AST).
     */
    async analyze_logic_flaws(content: string, filename: string): Promise<any[]> {
        if (!this.hubManager) return [];

        try {
            const { LogicAuditor } = await import("./logic_auditor.ts");
            const auditor = new LogicAuditor(this.hubManager);
            return await auditor.scanFile(filename, content);
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to analyze logic flaws in ${filename}: ${error}`);
            return [{
                file: filename,
                line: 1,
                issue: `Falha na análise lógica (AST gRPC): ${error}`,
                severity: "high",
                category: "Analysis",
                context: "StructuralAnalyst"
            }];
        }
    }

    /**
     * 🏗️ Mapeia a lógica do arquivo (AST Simplificado via Hub Proxy).
     */
    async analyze_file_logic(content: string, filename: string): Promise<any> {
        try {
            return await this.parser.analyze_file_logic(content, filename);
        } catch (error) {
            logger.error(`❌ [StructuralAnalyst] Failed to analyze file logic in ${filename}: ${error}`);
            return { complexity: 1, dependencies: [] };
        }
    }

    /** Parity: analyze_intent — Classifies the primary intent of a file (logic, metadata, observability). */
    analyze_intent(content: string, filename: string, rustMetadata?: any): string {
        return IntentClassifier.classify(content, filename, rustMetadata);
    }
