export class MatrixBuilder {
    static build(file: string, info: any, mapData: any, skipFn: (f: string, i: any) => boolean, statusFn: (s: string, c: number, a: number) => string, mapFn: (i: any, a: any) => any): any {
        if (skipFn(file, info)) return null;
        const targetName = path.parse(file).name, testInfo = TestDiscoveryStrategy.findTestForModule(targetName, mapData);
        const cc = info.complexity || 1, assertions = testInfo?.test_depth?.assertion_count || 0, structure = StructureClassifier.classify(file, info), advanced = info.advanced_metrics || {};
        return {
            file, assertions, originalComplexity: cc, instability: info.coupling?.instability || 0,
            complexity: (advanced.isShadow && advanced.shadowComplexity) ? advanced.shadowComplexity : cc,
            coverage_ratio: Number(((assertions * 5) / Math.max(1, cc)).toFixed(2)),
            test_status: statusFn(structure, cc, assertions),
            advanced_metrics: mapFn(info, advanced)
        };
    }
}

export class GoDiscoveryAdapter {
    /**
     * Executa o scan atômico em um diretório ou arquivo.
     * Agora utiliza o HubManagerGRPC para comunicação segura e performática.
     */
    static async scan(directory: string, root: string, hubManager?: HubManagerGRPC): Promise<{ results: FileAnalysis[], findings: any[] }> {
        try {
            if (!hubManager) {
                logger.warn("⚠️ HubManager não fornecido ao GoAdapter. Retornando vazio.");
                return { results: [], findings: [] };
            }

            logger.info(`🔍 [GoAdapter] Solicitando análise de projeto via gRPC Hub: ${directory}`);
            const startTime = Date.now();

            const files = await hubManager.scanProject(directory, root);
            
            const results: FileAnalysis[] = (files || []).map((item: any) => ({
                path: item.path || "unknown",
                exists: true,
                units: [],
                total_complexity: item.cyclomaticComplexity || item.total_complexity || 0,
                cognitive_complexity: item.cognitiveComplexity || 0,
                loc: item.loc || 0,
                sloc: item.sloc || 0,
                comments: item.comments || 0
            }));

            const duration = Date.now() - startTime;
            logger.info(`✨ [GoAdapter] Análise gRPC concluída em ${duration}ms. (${results.length} arquivos)`);

            return { results, findings: [] };
        } catch (error: any) {
            const msg = `🚨 Falha na comunicação gRPC com o Hub: ${error.message}`;
            logger.error(msg);
            return {
                results: [],
                findings: [{
                    type: "CRITICAL",
                    severity: "CRITICAL",
                    file: "hub.exe",
                    issue: msg,
                    agent: "GoDiscoveryAdapter",
                    role: "INFRASTRUCTURE_AUDITOR",
                    emoji: "🚨",
                    stack: "GoHub",
                    category: "Infrastructure",
                    context: "GoDiscoveryAdapter"
                }]
            };
        }
    }
}

