export class ASTIntelligence {
    static classifyIntent(node: ts.Node, sourceFile: ts.SourceFile): 'METADATA' | 'OBSERVABILITY' | 'LOGIC' {
        if (this.isMetadataContext(node)) return 'METADATA';
        if (this.isObservabilityContext(node)) return 'OBSERVABILITY';
        return 'LOGIC';
    }

    static logPerformance(label: string, duration: number): void {
        const severity = duration > 5 ? 'warn' : 'debug';
        logger[severity](`[PERF] ${label}: ${duration}ms`);
    }

    static isNodeSafe(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        return ContextValidator.isNodeSafe(node, sourceFile, this.isObservabilityContext.bind(this), this.isMetadataContext.bind(this), this.isMathContext.bind(this));
    }

    private static readonly METADATA_KEYWORDS = /rules|patterns|regex|manifest|metadata|diretriz|heuristics/i;
    private static readonly TECH_KEYWORDS = new Set(['alpha', 'progress', 'offset', 'dp', 'sp', 'x', 'y', 'width', 'height', 'radius', 'velocity', 'phase', 'lerp', 'sin', 'cos', 'tan', 'atan']);
    private static readonly OBSERVABILITY_KEYWORDS = /logger|log|console|telemetry|startMetrics|endMetrics|logPerformance/i;
    private static readonly DANGEROUS_CALLS = new Set(["eval", "exec", "Function", "setTimeout", "setInterval", "Bun.spawn", "Bun.$"]);

    static isMetadataContext(node: ts.Node): boolean {
        return this.getParentChain(node).some(p => (ts.isVariableDeclaration(p) || ts.isPropertyAssignment(p)) && this.METADATA_KEYWORDS.test(p.name.getText()));
    }

    static isMathContext(node: ts.Node): boolean {
        const check = (c: ts.Node) => Array.from(this.TECH_KEYWORDS).some(kw => c.getText().toLowerCase().includes(kw) && new RegExp(`\\b${kw}\\b`, 'i').test(c.getText()));
        return [node, node.parent, node.parent?.parent].filter(Boolean).some(c => check(c!));
    }

    static isObservabilityContext(node: ts.Node): boolean {
        return this.getParentChain(node).some(p => ts.isCallExpression(p) && this.OBSERVABILITY_KEYWORDS.test(p.expression.getText()));
    }

    static isDangerousCall(node: ts.Node): boolean {
        const text = ts.isCallExpression(node) ? node.expression.getText() : "";
        return !!text && (this.DANGEROUS_CALLS.has(text) || Array.from(this.DANGEROUS_CALLS).some(dc => text.includes(dc)));
    }

    static isCallTo(node: ts.Node, keywords: string[]): boolean {
        if (!ts.isCallExpression(node)) return false;
        const expr = node.expression.getText();
        return keywords.some(kw => expr === kw || expr.endsWith("." + kw));
    }

    static getParentChain(node: ts.Node): ts.Node[] {
        const chain: ts.Node[] = [];
        let curr = node.parent;
        while (curr) { chain.push(curr); curr = curr.parent; }
        return chain;
    }

    constructor() { }
    public is_inside_test_context(node: ts.Node): boolean { return false; }
    public _is_inside_test_method(node: ts.Node): boolean { return false; }
    public _is_inside_assertion(node: ts.Node): boolean { return false; }
}

export class TypescriptParser {
    static async parse(content: string, filePath: string): Promise<AtomicUnit[]> {
        try {
            // Using HTTP fetch to Hub server instead of spawning a new process
            const url = `http://localhost:8080/scan?file=${encodeURIComponent(filePath)}&root=${encodeURIComponent(process.cwd())}`;
            const res = await fetch(url);
            if (!res.ok) {
                console.error(`[TypescriptParser] Hub scan request failed for ${filePath}: ${res.statusText}`);
                return [];
            }

            const data = await res.json() as any[];

            if (data && data.length > 0) {
                return data[0].units.map((u: any) => ({
                    type: u.type as "class" | "function" | "method",
                    name: u.name,
                    parent: u.parent,
                    line: u.line
                }));
            }
            return [];
        } catch (err) {
            console.error(`[TypescriptParser] Native HTTP parsing failed for ${filePath}:`, err);
            return [];
        }
    }
}

export class PenaltyEngine {
    constructor(private hubManager?: HubManagerGRPC) { }

    async apply(raw: number, allAlerts: any[], mapData: Record<string, any>, total: number, qaData: any = null, cognitive: any = null): Promise<number> {
        if (this.hubManager) {
            try {
                return await this.applyRust(raw, allAlerts, mapData, qaData, cognitive);
            } catch (err) {
                logger.warn("gRPC penalty calculation failed, falling back to TypeScript", { error: err });
            }
        }

        const adjustments = this.getPilarAdjustments(allAlerts, mapData, qaData, cognitive);
        const totalDrain = Object.entries(adjustments)
            .filter(([key]) => key.startsWith("Quality (") || key.startsWith("Cognitive ("))
            .reduce((sum, [, v]) => sum + v, 0);

        let ceiling = 100;
        const alerts = allAlerts.filter(r => typeof r === 'object' && r !== null);
        const sevs = new Set(alerts.map(r => r.severity?.toLowerCase()));

        if (sevs.has('critical') || sevs.has('high')) ceiling = 70;
        else if (sevs.has('medium')) ceiling = 95;

        const final = Math.max(0, Math.round(Math.min(raw, ceiling) - totalDrain));
        logger.info(`🏆 [HealthCalculus] (TS Fallback) Raw: ${raw.toFixed(3)} | Ceiling: ${ceiling} | Drain: ${totalDrain} | Final: ${final}`);
        return final;
    }

    private async applyRust(raw: number, allAlerts: any[], mapData: Record<string, any>, qaData: any, cognitive: any): Promise<number> {
        const matrix = (qaData?.matrix || []).map((item: any) => {
            const m = item.advanced_metrics || {};
            return {
                file: item.file,
                component_type: mapData[item.file]?.component_type,
                test_status: item.test_status,
                advanced_metrics: {
                    cyclomatic_complexity: m.cyclomaticComplexity,
                    cognitive_complexity: m.cognitiveComplexity,
                    nesting_depth: m.nestingDepth,
                    cbo: m.cbo,
                    dit: m.dit,
                    maintainability_index: m.maintainabilityIndex,
                    defect_density: m.defectDensity,
                    quality_gate: m.qualityGate,
                    is_shadow: m.isShadow,
                    shadow_compliance_compliant: m.shadowCompliance?.compliant
                }
            };
        });

        const request = {
            raw_score: raw,
            alerts: allAlerts.filter(a => typeof a === 'object' && a !== null).map(a => ({ severity: a.severity })),
            matrix,
            cognitive: cognitive ? { status: cognitive.status } : null
        };

        if (!this.hubManager) return raw; // Should not happen given apply() check

        try {
            const response = await this.hubManager.penalty(request);
            if (!response) return raw;
            logger.info(`🏆 [HealthCalculus] (gRPC) Raw: ${raw.toFixed(3)} | Ceiling: ${response.ceiling} | Drain: ${response.total_drain} | Final: ${response.final_score}`);
            return response.final_score;
        } catch (error) {
            logger.error(`❌ [PenaltyEngine] gRPC call failed:`, error);
            return raw;
        }
    }

    getPilarAdjustments(allAlerts: any[], mapData: Record<string, any>, qaData: any = null, cognitive: any = null): Record<string, number> {
        const caps = { cc: 5, cognitive: 4, nesting: 3, cbo: 3, dit: 2, miLow: 4, miCritical: 3, defect: 3, gateRed: 3, shadow: 3 };
        const stats = qaData?.matrix ? AdjustmentCalculator.calculate(qaData.matrix, mapData, caps) : { total: 0, shallow: 0 };
        const prop = (count: number, cap: number) => Math.round(Math.min(cap, (count / Math.max(1, stats.total)) * cap) * 10) / 10;

        const cogPenalty = cognitive?.status === "FAIL" ? 5 : (cognitive?.status === "DEGRADED" ? 2 : 0);

        return {
            "Cognitive (System Sanity)": cogPenalty,
            "Quality (CC > 20 - High Risk)": prop(stats.cc, caps.cc), "Quality (Cognitive > 15)": prop(stats.cog, caps.cognitive), "Quality (Nesting > 3)": prop(stats.nest, caps.nesting),
            "Quality (CBO > 10 - High Coupling)": prop(stats.cbo, caps.cbo), "Quality (DIT > 5 - Deep Inheritance)": prop(stats.dit, caps.dit), "Quality (MI < 10 - Low Maint)": prop(stats.miL, caps.miLow),
            "Quality (MI < 5 - Critical)": prop(stats.miC, caps.miCritical), "Quality (Defect Density > 1/KLOC)": prop(stats.def, caps.defect), "Quality (Gate RED)": prop(stats.red, caps.gateRed),
            "Quality (Shadow Non-Compliant)": prop(stats.shad, caps.shadow), "Stability (Coverage)": (stats.shallow || 0) * 0.01,
            "Security (Vulnerabilities)": allAlerts.filter(r => r.severity === 'critical' || r.severity === 'high').length * 10, "Excellence (Documentation)": allAlerts.filter(r => typeof r === 'string').length * 0.1,
            _raw_ccCount: stats.cc, _raw_cognitiveCount: stats.cog, _raw_nestingCount: stats.nest, _raw_cboCount: stats.cbo, _raw_ditCount: stats.dit, _raw_miLowCount: stats.miL,
            _raw_miCriticalCount: stats.miC, _raw_defectCount: stats.def, _raw_gateRedCount: stats.red, _raw_shadowCount: stats.shad, _raw_totalAnalyzed: stats.total
        };
    }
}

export class ResourceEngine {
    /**
     * Retorna o perfil estático de recursos baseado na capacidade total de hardware informada.
     */
    public getResourceProfile(cores: number, ramGb: number): { profile: string, parallelism: number, throttle: boolean } {
        if (ramGb >= 64) return { profile: "ELITE_MODE", parallelism: cores * 8, throttle: false };
        if (ramGb >= 32) return { profile: "GOD_MODE", parallelism: cores * 4, throttle: false };
        if (ramGb >= 16) return { profile: "SOVEREIGN", parallelism: cores * 2, throttle: false };
        if (ramGb >= 8) return { profile: "STANDARD", parallelism: cores, throttle: true };
        return { profile: "CONSTRAINED", parallelism: Math.max(1, Math.floor(cores / 2)), throttle: true };
    }

    /**
     * Coleta as métricas reais do Sistema Operacional neste instante.
     */
    public getCurrentLoad(): { freeMemoryGb: number; totalMemoryGb: number; loadAvg: number[]; cpuCores: number } {
        const freeMemoryGb = os.freemem() / (1024 ** 3);
        const totalMemoryGb = os.totalmem() / (1024 ** 3);
        const loadAvg = os.loadavg();
        const cpuCores = os.cpus().length;

        return { freeMemoryGb, totalMemoryGb, loadAvg, cpuCores };
    }

    /**
     * Determina se o sistema do host está em estado crítico (sobrecarga de RAM ou CPU).
     */
    public isSystemOverloaded(): { overloaded: boolean; reason?: string } {
        const metrics = this.getCurrentLoad();
        
        // Regra 1: Menos de 1.5GB de RAM livre
        if (metrics.freeMemoryGb < 1.5) {
            return { overloaded: true, reason: `Critically low memory: ${metrics.freeMemoryGb.toFixed(2)} GB free.` };
        }

        // Regra 2: Carga média da CPU nos últimos 1 minuto supera 90% dos cores disponíveis
        // (Apenas disponível em sistemas Unix-like, no Windows loadavg retorna [0,0,0])
        if (metrics.loadAvg[0] > (metrics.cpuCores * 0.90) && metrics.loadAvg[0] > 0) {
            return { overloaded: true, reason: `High CPU Load average: ${metrics.loadAvg[0].toFixed(2)}.` };
        }

        return { overloaded: false };
    }

    /**
     * Retorna um degrau de concorrência dinâmico. Se o sistema estiver sobrecarregado, recua.
     */
    public getDynamicConcurrency(baseConcurrency: number): number {
        const status = this.isSystemOverloaded();
        if (status.overloaded) {
            // Em estado crítico, cai para o mínimo operacional (1 ou 2 threads).
            return Math.max(1, Math.floor(baseConcurrency * 0.25)); 
        }
        
        // Se a memória livre estiver moderada (ex: entre 1.5GB e 3GB), aplica throttle leve (50%).
        const metrics = this.getCurrentLoad();
        if (metrics.freeMemoryGb < 3.0) {
            return Math.max(1, Math.floor(baseConcurrency * 0.5));
        }

        return baseConcurrency; // Todo gás
    }
}

export class GitSyncManager {
    constructor(private git: GitClient, private projectRoot: Path, private agentPath: Path) {}

    async executeGitSync(): Promise<boolean> {
        const remote = await this.git.discoverRemote();
        if (!remote) return false;

        await this.git.rebaseAbort();
        logger.info(`🔄 Sync: ${remote}`);
        await this.git.fetchPrune(remote);

        const target = await this.getTargetRef(remote);
        const commitsBehind = await this.git.getCommitCount(`HEAD..${target}`);

        if (commitsBehind === 0) {
            logger.info("✅ Versão Atualizada.");
            return true;
        }

        return await this.performPull(target, commitsBehind);
    }

    private async getTargetRef(remote: string): Promise<string> {
        const active = await this.git.getCurrentBranch();
        const tracking = await this.git.getTrackingBranch(active);
        return `${remote}/${tracking}`;
    }

    private async performPull(target: string, count: number): Promise<boolean> {
        logger.info(`⬇️ Puxando ${count} commits...`);
        await this.git.stashPush("Auto-sync");
        const rebased = await this.git.rebase(target) === 0;
        const success = rebased || await this.fallbackReset(target);
        return success ? await this.finalizeSync() : false;
    }

    private async fallbackReset(target: string): Promise<boolean> {
        logger.warn(`⚠️ Reset Hard para ${target}`);
        await this.git.rebaseAbort();
        return await this.git.resetHard(target) === 0;
    }

    private async finalizeSync(): Promise<boolean> {
        await this.gitAddSkills();
        await this.git.stashPop();
        logger.info("✨ Sync Sucesso.");
        return true;
    }

    private async gitAddSkills(): Promise<void> {
        const proc = Bun.spawn(["git", "add", ".agent/skills"], { cwd: this.projectRoot.toString() });
        await proc.exited;
    }
}

export class MetaAnalysisStrategy {
    /**
     * Detecta padrões de Meta-Análise (Introspecção, AST, Eval).
     */
    static audit(node: ts.Node, sourceFile: ts.SourceFile): { isMeta: boolean, reason: string } {
        if (ASTIntelligence.isNodeSafe(node, sourceFile)) return { isMeta: false, reason: "" };

        const text = node.getText();
        // Detectar uso de TS Compiler API fora de agentes autorizados
        if (text.includes("ts.createSourceFile") || text.includes("ts.forEachChild")) {
            return { isMeta: true, reason: "Meta-análise detectada (Uso de TypeScript Compiler API)." };
        }
        // Detectar eval/Function
        if (text.includes("eval(") || text.includes("new Function(")) {
            return { isMeta: true, reason: "Meta-análise detectada (Execução dinâmica de código)." };
        }

        return { isMeta: false, reason: "" };
    }
}

export class JudgeHelpers {
    static isRuleDefinition(line: string): boolean {
