    private shouldSkipFile(file: string, info: any): boolean {
        const f = file.toLowerCase().replace(/\\/g, "/");
        if (file.endsWith("__init__.py") || info.component_type?.includes("TEST")) return true;
        if (f.includes("legacy_restore")) return true;
