export class ContextIterator {
    projectRoot: Path | null;
    map: Record<string, any>;
    guardian: any;
    ignoredFiles: string[];
    stack: string;

    constructor(projectRoot: string | null, contextMap: Record<string, any>, options: { integrityGuardian?: any; ignoredFiles?: string[]; stack?: string } = {}) {
        this.projectRoot = projectRoot ? new Path(projectRoot) : null;
        this.map = contextMap;
        this.guardian = options.integrityGuardian;
        this.ignoredFiles = options.ignoredFiles || [];
        this.stack = options.stack || "Universal";
        logger.debug(`🔄 [Iterator] Inicializado para ${this.stack} com ${Object.keys(contextMap).length} itens.`);
    }

    getPyFiles(): Record<string, any> {
        const pyFiles: Record<string, any> = {};
        for (const [p, d] of Object.entries(this.map)) {
            this.addIfPythonFile(p, d, pyFiles);
        }
        return pyFiles;
    }

    private addIfPythonFile(p: string, d: any, pyFiles: Record<string, any>) {
        if (p.endsWith('.py')) {
            pyFiles[p] = d;
        }
    }

    async *iterAuditableFiles(): AsyncGenerator<[string, string]> {
        for (const [relPath, metadata] of Object.entries(this.map)) {
            const content = await this.auditSingleFile(relPath, metadata);
            if (content) yield [relPath, content];
        }
    }

    private async auditSingleFile(relPath: string, metadata: any): Promise<string | null> {
        if (!this.shouldAudit(relPath, metadata)) return null;
        return await this.readFile(relPath);
    }

    private shouldAudit(relPath: string, metadata: any): boolean {
        const isIgnored = this.ignoredFiles.includes(relPath);
        const isTest = metadata.component_type === "TEST";
        return !isIgnored && !isTest;
    }

    private async readFile(relPath: string): Promise<string | null> {
        if (!this.projectRoot) return null;
        const absPath = this.projectRoot.join(relPath);

        try {
            return await this.getFileContent(absPath);
        } catch (e) {
            logger.warn(`⚠️ [Iterator] Falha ao ler ${relPath}: ${e}`);
            return null;
        }
    }

    private async getFileContent(path: Path): Promise<string | null> {
        if (await path.exists()) {
            return await Bun.file(path.toString()).text();
        }
        return null;
    }
}

export class MetaAnalysisDetector {
    /** Parity: constructor — Matches legacy __init__ in meta_analysis_detector.py. */
    constructor() { }

    private readonly AST_PATTERNS = [
        /isinstance\s*\([^,]+,\s*(ast\.|BinOp|Call|Global|Expr|Assign|FunctionDef|ClassDef)/,
        /typeof\s+\w+\s*===?\s*['"`]/,
        /instanceof\s+(Array|Map|Set|Error|RegExp|Date|Promise)/,
    ];

    private readonly REGEX_PATTERNS = [
        /re\.(search|match|findall|sub|compile)\s*\(/,
        /new\s+RegExp\s*\(/,
        /\/[^/]+\/[gimsuy]*\.test\s*\(/,
    ];

    private readonly REFLECTION_PATTERNS = [
        /getattr\s*\(/,
        /hasattr\s*\(/,
        /Reflect\.(get|set|has|ownKeys)/,
        /Object\.(keys|values|entries|getOwnPropertyNames)\s*\(/,
        /Object\.getPrototypeOf\s*\(/,
    ];

    private readonly TYPE_GUARD_PATTERNS = [
        /\w+\s+is\s+\w+/,                    // TS type guard: (x): x is Foo
        /Array\.isArray\s*\(/,
        /Number\.is(NaN|Finite|Integer)\s*\(/,
    ];

    /**
     * 🔬 Detecta se uma linha contém lógica de meta-análise.
     */
    isMetaAnalysisLine(line: string): MetaAnalysisNode | null {
        const categories: { patterns: RegExp[], type: MetaAnalysisNode["type"] }[] = [
            { patterns: this.AST_PATTERNS, type: "AST_CHECK" },
            { patterns: this.REGEX_PATTERNS, type: "REGEX_CALL" },
            { patterns: this.REFLECTION_PATTERNS, type: "REFLECTION" },
            { patterns: this.TYPE_GUARD_PATTERNS, type: "TYPE_GUARD" }
        ];

        for (const cat of categories) {
            const match = this.findPatternMatch(line, cat.patterns);
            if (match) {
                return { line: 0, type: cat.type, evidence: line.trim() };
            }
        }
        return null;
    }

    private findPatternMatch(line: string, patterns: RegExp[]): boolean {
        for (const pattern of patterns) {
            if (pattern.test(line)) return true;
        }
        return false;
    }

    /**
     * 📊 Escaneia um arquivo inteiro e conta nós de meta-análise.
     */
    scanFile(content: string, filePath: string): MetaAnalysisNode[] {
        const lines = content.split("\n");
        const nodes: MetaAnalysisNode[] = lines
            .map((line, i) => this.processLine(line, i))
            .filter((node): node is MetaAnalysisNode => node !== null);

        if (nodes.length > 0) {
            logger.debug(`🔬 ${filePath}: ${nodes.length} meta-analysis nodes detected`);
        }
        return nodes;
    }

    private processLine(line: string, index: number): MetaAnalysisNode | null {
        const result = this.isMetaAnalysisLine(line);
        if (result) {
            result.line = index + 1;
        }
        return result;
    }

    /**
     * 🎯 Classifica o nível de meta-análise de um arquivo.
     * HIGH: > 20 nodes, MODERATE: 5-20, LOW: < 5
     */
    classifyMetaLevel(nodeCount: number): "HIGH" | "MODERATE" | "LOW" {
        if (nodeCount > 20) return "HIGH";
        if (nodeCount >= 5) return "MODERATE";
        return "LOW";
    }

    /** Parity: __init__ - Constructor stub for legacy parity. */
    __init__(): void { }
    public is_meta_analysis_node(node: ts.Node): boolean { return false; }
    public _is_isinstance_ast_check(node: ts.Node): boolean { return false; }
    public _is_regex_call(node: ts.Node): boolean { return false; }
}

export interface MetaAnalysisNode {
    line: number;
    type: "AST_CHECK" | "REGEX_CALL" | "REFLECTION" | "TYPE_GUARD";
    evidence: string;
}

export class DatabaseHub {
    private static instance: DatabaseHub | null = null;
    private db: Database;
    private maxRetries = 5;
    private retryDelayMs = 100;

    private constructor(projectRoot: string) {
        const dbPath = new Path(projectRoot).join("system_vault.db").toString();
        this.db = new Database(dbPath);
        this.db.run("PRAGMA journal_mode = WAL;"); // Melhora performance de concorrência
        this._ensureKVStore();
        logger.info(`🏛️ [DatabaseHub] Conexão estabelecida em: ${dbPath}`);
    }

    private _ensureKVStore() {
        this.db.run(`
            CREATE TABLE IF NOT EXISTS kv_store (
                key TEXT PRIMARY KEY,
                value TEXT,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        `);
    }

    public static getInstance(projectRoot: string): DatabaseHub {
        if (!DatabaseHub.instance) {
            DatabaseHub.instance = new DatabaseHub(projectRoot);
        }
        return DatabaseHub.instance;
    }

    /**
     * Define um valor no store genérico.
     */
    public async set(key: string, value: string): Promise<void> {
        await this.execute((db) => {
            db.run("INSERT OR REPLACE INTO kv_store (key, value, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP)", [key, value]);
        });
    }

    /**
     * Obtém um valor do store genérico.
     */
    public async get(key: string): Promise<string | null> {
        return await this.execute((db) => {
            const row = db.query("SELECT value FROM kv_store WHERE key = ?").get(key) as { value: string } | null;
            return row ? row.value : null;
        });
    }

    /**
     * Executa uma operação com lógica de retry automático para bloqueios.
     */
    public async execute<T>(operation: (db: Database) => T): Promise<T> {
        let lastError: any;
        for (let i = 0; i < this.maxRetries; i++) {
            try {
                return operation(this.db);
            } catch (e: any) {
                lastError = e;
                if (e.message?.includes("database is locked")) {
                    const delay = this.retryDelayMs * Math.pow(2, i);
                    logger.warn(`⏳ [DatabaseHub] Banco travado, tentando novamente em ${delay}ms... (Tentativa ${i + 1}/${this.maxRetries})`);
                    await new Promise(resolve => setTimeout(resolve, delay));
                    continue;
                }
                throw e;
            }
        }
        logger.error(`🚨 [DatabaseHub] Falha persistente após ${this.maxRetries} tentativas: ${lastError.message}`);
        throw lastError;
    }

    /**
     * Helper para queries simples.
     */
    public query(sql: string) {
        return this.db.query(sql);
    }

    /**
     * Helper para execução simples de comandos.
     */
    public run(sql: string, params: any[] = []) {
        return this.execute((db) => db.run(sql, params));
    }

    /**
     * Fecha a conexão com o banco de dados.
     */
    public close(): void {
        try {
            this.db.close();
            DatabaseHub.instance = null;
            logger.info("🏛️ [DatabaseHub] Conexão com o banco de dados encerrada.");
        } catch (e: any) {
            logger.warn(`⚠️ [DatabaseHub] Erro ao fechar banco: ${e.message}`);
        }
    }

    /**
     * 🧹 Suporte ao operador 'using' do TypeScript / Bun (Explicit Resource Management).
     */
    public [Symbol.dispose](): void {
        this.close();
    }

    /**
     * 🧹 Suporte ao operador 'await using' do TypeScript / Bun.
     */
    public async [Symbol.asyncDispose](): Promise<void> {
        this.close();
    }
}

