export class SystemManager {
    private static instance: SystemManager;
    private hubManager: HubManagerGRPC;
    private nativeProcesses: ChildProcess[] = [];
    private shutdownInProgress = false;

    private constructor() {
        this.hubManager = HubManagerGRPC.getInstance();
        this.setupShutdownHandlers();
    }

    public static getInstance(): SystemManager {
        if (!SystemManager.instance) {
            SystemManager.instance = new SystemManager();
        }
        return SystemManager.instance;
    }

    /**
     * Tenta garantir que a infraestrutura nativa está pronta, iniciando-a se necessário.
     */
    public async ensureInfrastructure(projectRoot: string): Promise<boolean> {
        if (await this.hubManager.isHealthy()) {
            logger.info("✅ Native Hub já está saudável e operando.");
            return true;
        }

        logger.info("🚀 Iniciando infraestrutura nativa (Hub + Sidecar) pelo SystemManager...");
        
        const absRoot = path.resolve(projectRoot);
        // Determina o root do Personas_Agentes (onde os binários vivem)
        const myDir = path.dirname(decodeURIComponent(new URL(import.meta.url).pathname)).replace(/^\/([a-zA-Z]:)/, '$1');
        const personasRoot = path.resolve(myDir, "../../"); 
        
        const hubExe = path.join(personasRoot, "src_native/hub/hub.exe");
        const analyzerExe = path.join(personasRoot, "src_native/analyzer/target/release/analyzer.exe");

        if (!fs.existsSync(hubExe)) {
            logger.error(`❌ Não encontrado: ${hubExe}`);
            return false;
        }
        if (!fs.existsSync(analyzerExe)) {
            logger.error(`❌ Não encontrado: ${analyzerExe}`);
            return false;
        }

        const logStream = fs.createWriteStream(path.join(absRoot, "diagnostic.log"), { flags: 'a' });

        const sidecarProcess = spawn(analyzerExe, ["serve"], { cwd: absRoot, stdio: 'pipe' });
        const hubProcess = spawn(hubExe, [], { cwd: path.dirname(hubExe), stdio: 'pipe' });

        sidecarProcess.stdout?.pipe(logStream);
        sidecarProcess.stderr?.pipe(logStream);
        hubProcess.stdout?.pipe(logStream);
        hubProcess.stderr?.pipe(logStream);

        this.nativeProcesses.push(sidecarProcess, hubProcess);

        // Aguarda estabilização (Pooling de health check)
        logger.info("⏳ Aguardando serviços nativos estabilizarem...");
        for (let i = 0; i < 15; i++) {
            await new Promise(r => setTimeout(r, 1000));
            if (await this.hubManager.isHealthy()) {
                logger.info("✅ Infraestrutura nativa operacional.");
                return true;
            }
        }

        logger.error("❌ Falha ao estabilizar infraestrutura nativa após 15s.");
        return false;
    }

    private setupShutdownHandlers() {
        const handleSignal = async () => {
            await this.shutdown();
        };

        process.on("SIGINT", handleSignal);
        process.on("SIGTERM", handleSignal);
    }

    public async shutdown() {
        if (this.shutdownInProgress) return;
        this.shutdownInProgress = true;
        logger.info("🛑 Encerrando infrastructure_assembler. Limpando processos nativos...");
        
        for (const proc of this.nativeProcesses) {
            try {
                proc.kill();
            } catch (e) {
                // Ignore
            }
        }
        
        logger.info("✨ Cleanup concluído.");
        console.log("✨ Native processes terminated.");
    }

    public registerNativeProcess(proc: ChildProcess) {
        if (!this.nativeProcesses.includes(proc)) {
            this.nativeProcesses.push(proc);
        }
    }
}

export class BehaviorAnalyst {
    private dbHub: DatabaseHub;
    private lastApp: string | null = null;
    private startTime: number = Date.now();
    private windowCache: { data: { app: string, title: string }, timestamp: number } | null = null;
    private readonly CACHE_TTL = 30000;

    constructor(projectRoot: string) {
        this.dbHub = DatabaseHub.getInstance(projectRoot);
    }

    /**
     * Obtém a janela em foco usando PowerShell com cache.
     */
    async getActiveWindow(): Promise<{ app: string, title: string }> {
        if (this.isCacheValid()) return this.windowCache!.data;

        try {
            if (process.platform !== "win32") return { app: "System (Headless)", title: "N/A" };

            const data = await this.runWin32PowerShellAsync();
            this.windowCache = { data, timestamp: Date.now() };
            return data;
        } catch (e: any) {
            logger.debug(`⚠️ Failed to detect active window: ${e.message}`);
            return { app: "System", title: "N/A" };
        }
    }

    private isCacheValid(): boolean {
        return !!(this.windowCache && Date.now() - this.windowCache.timestamp < this.CACHE_TTL);
    }

    private async runWin32PowerShellAsync(): Promise<{ app: string, title: string }> {
        const cmd = `
            Add-Type @"
            using System;
            using System.Runtime.InteropServices;
            using System.Text;
            public class Win32 {
                [DllImport("user32.dll")]
                public static extern IntPtr GetForegroundWindow();
                [DllImport("user32.dll")]
                public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int count);
                [DllImport("user32.dll")]
                public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
            }
"@
            $hwnd = [Win32]::GetForegroundWindow()
            $sb = New-Object System.Text.StringBuilder 256
            [Win32]::GetWindowText($hwnd, $sb, $sb.Capacity)
            $pid = 0
            [Win32]::GetWindowThreadProcessId($hwnd, [ref]$pid)
            $proc = Get-Process -Id $pid
            "$($proc.ProcessName)|$($sb.ToString())"
        `;

        const { stdout } = await execAsync(`powershell -Command "${cmd.replace(/\n/g, '')}"`, { encoding: 'utf8' });
        const output = (stdout || "").trim();
        const [app, title] = output.split('|');
        return { app: app || "Unknown", title: title || "" };
    }

    classifyActivity(app: string, title: string): string {
        return ActivityClassifier.classify(app, title);
    }

    /**
     * Registra a atividade atual e retorna a categoria.
     */
    async logActivity(): Promise<string> {
        const { app, title } = await this.getActiveWindow();
        const category = this.classifyActivity(app, title);

        if (this.lastApp !== app) {
            this.finalizeLastActivity(category);
            this.lastApp = app;
            this.startTime = Date.now();
            logger.info(`👀 [Behavior] Foco: ${app} (${category})`);
        }

        return category;
    }

    private finalizeLastActivity(category: string) {
        if (!this.lastApp) return;
        const duration = Math.floor((Date.now() - this.startTime) / 1000);
        this.saveActivity(this.lastApp, category, duration);
    }

    private saveActivity(app: string, category: string, duration: number) {
        if (duration < 5) return;
        try {
            this.dbHub.run(
                "INSERT INTO user_activity (app_name, category, duration_seconds) VALUES (?, ?, ?)",
                [app, category, duration]
            );
        } catch (e: any) {
            if (e.message?.includes("no such table")) {
                logger.debug("👀 [Behavior] Skiping save: user_activity table not initialized.");
            } else {
                logger.warn(`❌ [Behavior] Database error: ${e.message}`);
            }
        }
    }
}

export class MasterOrchestratorService {
    private brain: CognitiveEngine;

    constructor() {
        this.brain = new CognitiveEngine();
    }

    /**
     * Gera uma docstring de cabeçalho soberana para um arquivo.
     */
    async generateDocstring(fileName: string, content: string): Promise<string> {
        logger.info(`✍️ [MasterOrchestrator] Gerando propósito para ${fileName}...`);
        const partialContent = content.slice(0, 1500);

        const prompt = `Analise o código abaixo e gere uma documentação de cabeçalho concisa em PORTUGUÊS.
Arquivo: ${fileName}
Amostra de Código:
${partialContent}

Requisitos:
1. Explique o PROPÓSITO principal do arquivo.
2. Liste as principais responsabilidades.
3. Use o formato JSDoc (/** ... */) para TypeScript ou Docstring (""" ... """) para Python.
4. Responda APENAS com o bloco de comentário.`;

        try {
            const answer = await this.brain.reason(prompt);
            return answer ?? "/** Falha na geração automática de documentação (Resposta Nula). */";
        } catch (error) {
            logger.error(`❌ [MasterOrchestrator] Falha na geração de documentação: ${error}`);
            return "/** Falha na geração automática de documentação. */";
        }
    }

    /**
     * Gera o grafo Mermaid da topologia do sistema.
     */
    generateMermaidGraph(map: Record<string, any>): string {
        logger.info("🕸️ [MasterOrchestrator] Mapeando grafo de topologia...");
        const lines = ["graph TD"], nodes = new Set<string>();
        const valid = ['.ts', '.py', '.tsx', '.js', '.zig'];
        const entries = Object.entries(map).filter(([f]) => valid.some(e => f.endsWith(e)) && !/[\\/](node_modules|dist)$/.test(f)).sort(([a], [b]) => this._score(b) - this._score(a));

        let count = 0;
        for (const [f, d] of entries) {
            if (count >= 150) break;
            const nid = this._id(f), lbl = new Path(f).name();
            if (!nodes.has(nid)) { nodes.add(nid); this._style(nid, f, lines); }
            (d.dependencies || []).forEach((dep: any) => {
                if (count < 150 && !(count > 100 && /(utils|types)/.test(dep))) {
                    lines.push(`    ${nid}["${lbl}"] --> ${this._id(dep.toString())}`);
                    count++;
                }
            });
        }
        lines.push("    classDef core fill:#ff9999,stroke:#333;");
        lines.push("    classDef agent fill:#99ccff,stroke:#333;");
        return lines.join("\n");
    }

    private _score(f: string) { return (f.includes("/core/") ? 10 : 0) + (f.includes("/engines/") ? 5 : 0); }
    private _id(s: string) { return s.replace(/[\.\/\-@]/g, "_"); }
    private _style(id: string, f: string, l: string[]) {
        if (f.includes("/core/")) l.push(`    class ${id} core;`);
        else if (f.includes("/engines/")) l.push(`    class ${id} agent;`);
    }
}

export class StatsAggregator {
