export class VetoEngine {
    public shouldVeto(relPath: string): { veto: boolean; reason?: VetoReason; justification?: string } {
        const ignored = ['.git', '__pycache__', 'build', 'node_modules', '.venv', '.agent', '.gemini', 'submodules', 'dist', 'target', 'bin'];
        const parts = relPath.split(/[/\\]/);

        if (parts.some(part => ignored.includes(part))) {
            return { veto: true, reason: VetoReason.INFRASTRUCTURE, justification: "Caminho de infraestrutura ignorado." };
        }

        if (relPath.endsWith(".pyc") || relPath.endsWith(".o") || relPath.endsWith(".exe") || relPath.endsWith(".dll") || relPath.endsWith(".class")) {
            return { veto: true, reason: VetoReason.LEGACY_ARTIFACT, justification: "Binário ou cache legado detectado." };
        }

        if (relPath.includes("/secrets/") || relPath.includes("/internal/keys/")) {
            return { veto: true, reason: VetoReason.SECURITY_RISK, justification: "Acesso a subdiretório de segredos protegido." };
        }

        return { veto: false };
    }

    public isTechnicalMath(lineContent: string, issue: string): boolean {
        if (!issue.includes("Imprecisão Monetária")) return false;

        const techTerms = [
            'alpha', 'progress', 'offset', 'dp', 'sp', 'radius', 'velocity',
            'phase', 'amplitude', 'frequency', 'duration', 'x', 'y', 'width', 'height',
            'sigma', 'delta', 'theta', 'gamma', 'epsilon', 'lambda', 'mu', 'nu',
            'integral', 'derivative', 'matrix', 'tensor', 'scalar', 'vector'
        ];
        const lower = lineContent.toLowerCase();

        const moneyTerms = ['price', 'amount', 'balance', 'cost', 'total', 'euro', 'usd', 'brl', 'payment', 'transaction', 'wallet', 'currency'];
        if (moneyTerms.some(f => lower.includes(f))) {
            return false;
        }

        return techTerms.some(t => new RegExp(`\\b${t}\\b`).test(lower));
    }

    public isRuleDefinition(lineContent: string): boolean {
        const lower = lineContent.toLowerCase();
        const keywords = [
            "rules =", "patterns =", "audit_rules =", "regex =",
            "silent_pattern =", "brittle_pattern =", "heuristic =",
            "veto_criteria =", "security_policy =", "compliance_check =",
            "validation_logic =", "rule_registry ="
        ];
        return keywords.some(kw => lower.includes(kw));
    }
}

export class MarkdownSanitizer {
    public async sanitize(content: string): Promise<string> {
        if (!content) return "";
        const startTime = Date.now();

        let internalContent = content.replace(/^\ufeff+/, '').replace(/\r\n/g, "\n").trim();
        let lines = internalContent.split("\n");

        const structureAgent = new MarkdownStructureAgent(lines);
        lines = structureAgent.executeRefinement();

        // Aplicação de políticas via StyleRules
        lines = this.cleanup(lines);
        lines = StyleRules.ensureBlanksAroundHeadings(lines);
        lines = StyleRules.ensureBlanksAroundLists(lines);
        lines = StyleRules.ensureBlanksAroundTables(lines);
        lines = StyleRules.ensureBlockquoteContinuity(lines);
        lines = this.ensureH1(lines);

        const sanitized = lines.join("\n").trim() + "\n";
        logger.info(`📝 Markdown Sanitized em ${Date.now() - startTime}ms`);

        return sanitized;
    }

    private cleanup(lines: string[]): string[] {
        while (lines.length > 0 && lines[0]!.trim().length === 0) lines.shift();
        while (lines.length > 0 && lines[lines.length - 1]!.trim().length === 0) lines.pop();
        return lines;
    }

    private ensureH1(lines: string[]): string[] {
        if (lines.length === 0) return ["# 🏛️ RELATÓRIO SISTÊMICO", ""];
        if (lines[0]!.trim().startsWith("# ")) return lines;

        for (let i = 0; i < lines.length; i++) {
            if (lines[i]!.trim().startsWith("# ")) {
                const [h1] = lines.splice(i, 1);
                return [h1!, "", ...lines];
            }
        }
        return ["# 🏛️ RELATÓRIO SISTÊMICO", "", ...lines];
    }
}

export class ParityAnalyst {
    private tsRoot: string;
    constructor(tsRoot = "src_local/agents", _metrics: DepthMetric[] = []) { this.tsRoot = tsRoot; }

    async analyzeStackGaps(_personas: any[]): Promise<ParityReport> { return await this.analyzeAtomicParity(); }

    public async analyzeAtomicParity(): Promise<ParityReport> {
        const groups = await InstanceGrouper.group(this.tsRoot);
        const results = Array.from(groups.entries()).flatMap(([name, insts]) => this.compareInstances(name, insts));

        const byStack = this.aggregateBy(results, "stack");
        const byCategory = this.aggregateBy(results, "category");

        return {
            timestamp: new Date().toISOString(), totalAgents: groups.size, totalInstances: results.length,
            symmetricCount: results.filter(r => r.status === "IDENTICAL").length, divergentCount: results.filter(r => r.status === "DIVERGENT").length,
            overallParity: this.avgScore(results), byStack, byCategory, results,
            criticalDeltas: results.flatMap(r => r.deltas.filter(d => d.severity === "CRITICAL")),
            coverage: Array.from(groups.entries()).map(([agent, insts]) => ({ agent, stacks: insts.map(i => i.stack) }))
        };
    }

    private aggregateBy(results: AgentParityResult[], key: "stack" | "category"): Record<string, { total: number; symmetric: number; parity: number }> {
        const agg: Record<string, { total: number; symmetric: number; parity: number }> = {};
        results.forEach(r => {
            const st = agg[r[key]] ||= { total: 0, symmetric: 0, parity: 0 };
            st.total++;
            if (r.status === "IDENTICAL") st.symmetric++;
        });
        Object.keys(agg).forEach(k => {
            const st = agg[k];
            if (st) st.parity = this.avgScore(results.filter(r => r[key] === k));
        });
        return agg;
    }

    private compareInstances(name: string, instances: AgentInstance[]): AgentParityResult[] {
        const ref = instances.find(i => i.stack === "TypeScript") || instances.find(i => i.stack === "Bun") || instances[0]!;
        return instances.map(inst => {
            const deltas = computeDeltas(ref.fp, inst.fp, name);
            return {
                agent: name, stack: inst.stack, category: inst.cat, score: computeScore(deltas), deltas, legacy: ref.fp, current: inst.fp,
                status: (inst === ref || !deltas.some(d => /CRITICAL|HIGH|MEDIUM/.test((d.severity || "").toUpperCase()))) ? "IDENTICAL" : "DIVERGENT"
            };
        });
    }

    private avgScore(res: any[]) { return res.length ? Math.round(res.reduce((s, r) => s + r.score, 0) / res.length) : 0; }

    formatMarkdownReport(report: ParityReport): string {
        return ParityReporter.formatMarkdown(report);
    }

    getVitalStatus(report: ParityReport): string { return `${report.overallParity}% ${report.overallParity >= 95 ? "Atômica" : (report.overallParity >= 80 ? "Parcial" : "Crítica")}`; }
}

