export class SecuritySentinelAgent {
    private heuristic: VulnerabilityHeuristic;

    constructor(private hubManager?: HubManagerGRPC) {
        this.heuristic = new VulnerabilityHeuristic(this.hubManager);
        if (this.hubManager) logger.info("🛡️ [Security] Hub gRPC integrado ao Sentinel.");
    }

    /**
     * Realiza um scan preventivo de segurança em arquivos específicos.
     */
    async runSecurityScan(files: string[], context: ProjectContext): Promise<AuditFinding[]> {
        if (!context.map) return [];
        logger.info(`🛡️ [Security] Iniciando scan profundo em ${files.length} arquivos...`);
        let findings: AuditFinding[] = [];

        for (const file of files) {
            const entry = context.map[file];
            const content = entry?.content || "";
            if (!content) continue;

            try {
                const result = await this.heuristic.analyze(file, content);
                findings = findings.concat(result.rulesHit.map(rule => ({
                    file,
                    issue: rule.issue,
                    severity: rule.severity.toUpperCase() as any,
                    type: "SECURITY",
                    evidence: rule.regex as string,
                    agent: "SecuritySentinel"
                })));
            } catch (e) {
                logger.error(`❌ [Security] Erro ao analisar ${file}: ${e}`);
            }
        }

        return findings;
    }

    /**
     * Scans the entire project for security vulnerabilities using the deep engine.
     */
    async scanProject(context: ProjectContext): Promise<AuditFinding[]> {
        const files = Object.keys(context.map || {});
        return this.runSecurityScan(files, context);
    }
}

export class FingerprintExtractor {
    constructor(private hubManager?: HubManagerGRPC) { }

    /**
     * Batch extract all fingerprints using the Go Hub proxy.
     */
    async batchExtract(agentsRoot: string): Promise<Map<string, AtomicFingerprint>> {
        const result = new Map<string, AtomicFingerprint>();

        if (!this.hubManager) {
            logger.warn("⚠️ HubManager not provided to FingerprintExtractor. Returning empty map.");
            return result;
        }

        try {
            logger.info(`🧬 [Fingerprint] Batch extracting from: ${agentsRoot}`);
            const report = await this.hubManager.fingerprint(agentsRoot);

            if (report && report.entries) {
                for (const entry of report.entries) {
                    if (entry.agent === "__init__") continue;
                    const key = `${entry.category}/${entry.agent}/${entry.stack}`;
                    result.set(key, this.mapRustToAtomic(entry.fingerprint));
                }
            }
        } catch (err: unknown) {
            logger.error(`[FingerprintExtractor] gRPC batch extraction failed:`, err instanceof Error ? err.message : String(err));
        }

        return result;
    }

    private mapRustToAtomic(f: any): AtomicFingerprint {
        return {
            name: f.name,
            emoji: f.emoji,
            role: f.role,
            stack: f.stack,
            rulesCount: f.rules_count,
            rulePatterns: f.rule_issues ? f.rule_issues.map((_: any, i: number) => `P${i}`) : [],
            ruleIssues: f.rule_issues || [],
            ruleSeverities: f.rule_severities || [],
            fileExtensions: f.file_extensions || [],
            hasReasoning: f.has_reasoning,
            reasoningTrigger: "",
            systemPrompt: f.system_prompt,
            hasExtraMethods: f.extra_methods,
            methods: f.methods || [],
            halsteadVolume: f.halstead_volume || 0,
            halsteadDifficulty: f.halstead_difficulty || 0,
            halsteadEffort: f.halstead_effort || 0
        };
    }

    async extractTS(content: string, name: string): Promise<AtomicFingerprint> {
        if (!this.hubManager) {
            logger.warn(`⚠️ [Fingerprint] Hub offline. Using local regex extraction for ${name}.`);
            return this.extractLocally(content, name);
        }

        try {
            logger.debug(`🧬 [Fingerprint] Ad-hoc gRPC extraction for ${name}.`);
            const fingerprint = await this.hubManager.fingerprint(name);
            if (fingerprint && fingerprint.entries && fingerprint.entries[0]) {
                return this.mapRustToAtomic(fingerprint.entries[0].fingerprint);
            }
            return this.extractLocally(content, name);
        } catch (err: unknown) {
            const msg = err instanceof Error ? err.message : String(err);
            logger.warn(`⚠️ [Fingerprint] gRPC extraction failed for ${name}: ${msg}. Falling back to local.`);
            return this.extractLocally(content, name);
        }
    }

    private extractLocally(content: string, name: string): AtomicFingerprint {
        const { ParserHelpers } = require("./ParserHelpers.ts");
        const parts = ParserHelpers.getParts(content);
        return {
            name: name,
            emoji: "🛡️",
            role: "Local Fallback Agent",
            stack: "Local",
            rulesCount: 0,
            rulePatterns: [],
            ruleIssues: [],
            ruleSeverities: [],
            fileExtensions: [],
            hasReasoning: false,
            reasoningTrigger: "",
            systemPrompt: "",
            hasExtraMethods: [],
            methods: [...new Set([...parts.functions, ...parts.arrows, ...parts.methods])],
            halsteadVolume: 0,
            halsteadDifficulty: 0,
            halsteadEffort: 0
        };
    }

    async extractPython(content: string, name: string): Promise<AtomicFingerprint> {
        return await this.extractTS(content, name);
    }

    async matchTSRules(content: string): Promise<string[]> {
        const fingerprint = await this.extractTS(content, "probe");
        return fingerprint.ruleIssues;
    }
}

export class ConnectivityMapper {
    constructor(private hubManager?: HubManagerGRPC) { }

    /**
     * Calcula acoplamento de TODOS os arquivos em uma única passada via Hub Proxy.
     */
    async calculateBulk(allMap: Record<string, any>): Promise<Record<string, { in: number, out: number, instability: number }>> {
        if (!this.hubManager) {
            logger.warn("HubManager missing, bulk connectivity analysis skipped");
            return {};
        }

        try {
            const sanitizedMap: Record<string, any> = {};
            for (const [file, data] of Object.entries(allMap)) {
                sanitizedMap[file] = {
                    dependencies: data.dependencies || [],
                    advanced_metrics: data.advanced_metrics ? {
                        cyclomatic_complexity: data.advanced_metrics.cyclomaticComplexity || 1,
                        cognitive_complexity: data.advanced_metrics.cognitiveComplexity || 0,
                        maintainability_index: data.advanced_metrics.maintainabilityIndex || 100,
                        quality_gate: data.advanced_metrics.qualityGate || "GREEN",
                        nesting_depth: data.advanced_metrics.nestingDepth || 0,
                        cbo: data.advanced_metrics.cbo || 0,
                        dit: data.advanced_metrics.dit || 0,
                        defect_density: data.advanced_metrics.defectDensity || 0
                    } : {
                        cyclomatic_complexity: 1,
                        cognitive_complexity: 0,
                        maintainability_index: 100,
                        quality_gate: "GREEN",
                        nesting_depth: 0,
                        cbo: 0,
                        dit: 0,
                        defect_density: 0
                    }
                };
            }
            const results = await this.hubManager.getConnectivity(sanitizedMap);
            const mapping: Record<string, any> = {};

            if (results && Array.isArray(results)) {
                results.forEach((r: any) => {
                    mapping[r.file] = { in: r.afferent, out: r.eferent, instability: r.instability };
                });
            }

            return mapping;
        } catch (err) {
            logger.error("gRPC connectivity analysis failed:", err);
            return {};
        }
    }

    calculateMetrics(filePath: string, data: any, allMap: Record<string, any>): any {
        const startTime = Date.now();
        const eferent = (data.dependencies || []).length;
        let afferent = 0;
        const fileStem = new Path(filePath).stem();

        for (const [otherFile, otherData] of Object.entries(allMap)) {
            if (otherFile === filePath) continue;
            const deps = otherData.dependencies || [];
            if (deps.some((imp: string) => imp.includes(fileStem))) {
                afferent += 1;
            }
        }

        const instability = (afferent + eferent) > 0 ? eferent / (afferent + eferent) : 0;
        const duration = (Date.now() - startTime) / 1000;
        logger.debug(`⏱️ [Connectivity] Single analysis for ${filePath} in ${duration.toFixed(4)}s`);

        return { in: afferent, out: eferent, instability: instability };
    }
}

export class ResourceGovernor {
    static enforce(pid: number) {
        try { os.setPriority(pid, os.constants.priority.PRIORITY_LOW); logger.info("⚖️ [Gov] Priority adjusted to 'LOW'."); }
        catch (e) { logger.warn(`⚠️ Failed to adjust priority: ${e}`); }
    }

    static shouldThrottle(h: any, cpuLimit: number = 85, memLimit: number = 95): boolean {
        const cpu = parseFloat(h.cpu_usage.toString()), mem = parseFloat(h.memory_usage);
        if (cpu > cpuLimit || mem > memLimit) { logger.warn(`🌡️ [Gov] High load (CPU: ${cpu.toFixed(1)}%, MEM: ${mem.toFixed(1)}%). Throttling.`); return true; }
        return false;
    }

    static async yield(checkFn: () => boolean | Promise<boolean>) {
        while (await checkFn()) await new Promise(res => setTimeout(res, 5000));
    }
}

export class StabilityLedger {
    projectRoot: Path;
    persistence: MemoryPersistence;
    ledger: Record<string, any>;

    constructor(projectRoot: string) {
        this.projectRoot = new Path(projectRoot);
        const storagePath = this.projectRoot.join(".gemini", "stability_ledger.json");

        this.persistence = new MemoryPersistence(storagePath);
        this.ledger = this.persistence.loadLedger();
    }

    async sync() {
        logger.info("💾 [Ledger] Sincronizando livro de estabilidade...");
        this.persistence.saveLedger(this.ledger);
    }

    update(auditResults: any[], contextMap: Record<string, any> = {}): Record<string, any> {
        try {
            this.performMaintenance();
            const currentErrorFiles = this.processAuditResults(auditResults, contextMap);
            this.detectHealedFiles(currentErrorFiles);

            this.persistence.saveLedger(this.ledger);
            return this.ledger;
        } catch (e: any) {
            logger.error(`🚨 Falha ao atualizar livro de estabilidade: ${e.message}`);
            return this.ledger;
        }
    }

    private performMaintenance() {
        const isInternal = this.projectRoot.toString().includes("Personas_Agentes");
        if (!isInternal && this.ledger[".agent/skills"]) {
            delete this.ledger[".agent/skills"];
        }
    }

    private processAuditResults(results: any[], contextMap: any): Set<string> {
        const currentErrorFiles = new Set<string>();
        results.forEach(issue => {
            const file = this.extractFileName(issue);
            currentErrorFiles.add(file);
            this.updateFileStatus(file, contextMap);
        });
        return currentErrorFiles;
    }

    private extractFileName(issue: any): string {
        if (typeof issue === 'object' && issue !== null && issue.file) {
            return String(issue.file).replace(/\\/g, "/");
        }
        return "Strategic/DNA";
    }

    private updateFileStatus(file: string, contextMap: Record<string, any>) {
        if (this.tryMarkReference(file, contextMap)) return;

        const entry = this.ledger[file] || { occurrences: 0, history: [], status: "UNSTABLE" };
        entry.occurrences += 1;
        entry.history.push(new Date().toISOString());

        // Only set status to UNSTABLE if it's not a REFERENCE
        if (entry.status !== "REFERENCE") {
            entry.status = "UNSTABLE";
        }

        this.ledger[file] = entry;
    }

    private tryMarkReference(file: string, contextMap: Record<string, any>): boolean {
        if (contextMap[file]?.is_gold_standard) {
            this.ledger[file] ||= { status: "REFERENCE", history: ["Identificado como Gold Standard"] };
            return true;
        }
        return false;
    }

    private detectHealedFiles(currentErrors: Set<string>) {
        Object.keys(this.ledger).forEach(file => {
            if (this.isHealable(file, currentErrors)) {
                this.markAsHealed(file);
            }
        });
    }

    private markAsHealed(file: string) {
        logger.info(`✨ [Memória] Cura confirmada: ${file}`);
        this.ledger[file].status = "HEALED";
        this.ledger[file].occurrences = 0;
    }

    private isHealable(file: string, currentErrors: Set<string>): boolean {
        const entry = this.ledger[file];
        if (file === "Strategic/DNA" || entry.status === "REFERENCE") return false;
        return !currentErrors.has(file) && entry.status !== "HEALED";
    }

    clear() {
        this.ledger = this.filterLedgerByStatus("REFERENCE");
        this.persistence.saveLedger(this.ledger);
        logger.info("🧹 [StabilityLedger] Memória de instabilidade resetada.");
    }

    private filterLedgerByStatus(status: string): Record<string, any> {
        return Object.fromEntries(
            Object.entries(this.ledger).filter(([_, v]) => v.status === status)
        );
    }

    getFileData(filePath: string): any {
        return this.persistence.getFileMetadata(this.ledger, filePath);
    }

    registerDisparity(disparity: { source: string, target: string, discrepancies: string[], severity: string }) {
        const file = disparity.source.replace(/\\/g, "/");
        const entry = this.ledger[file] || { occurrences: 0, history: [], status: "UNSTABLE" };
        
        entry.status = "DISPARITY";
        entry.occurrences += 1;
        entry.history.push(`[PARITY ERROR] Disparidade com ${disparity.target}: ${disparity.discrepancies.join("; ")}`);
        entry.meta = { ...entry.meta, lastSiblingDisparity: disparity.target, severity: disparity.severity };

        this.ledger[file] = entry;
        this.persistence.saveLedger(this.ledger);
        logger.warn(`⚖️ [Ledger] Disparidade registrada para ${file}`);
    }
}

export class HeadingRules implements LintRule {
    check(lines: string[], i: number, stripped: string, file: string, context: { hMap: Map<string, number>, errs: any[] }): void {
        if (!stripped.startsWith("#")) return;

        if (!/^#+\s/.test(stripped)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD001: Heading levels should be followed by a space", 
                severity: "medium", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: stripped,
                context: "MarkdownAuditor" 
            });
        }

        if (i > 0 && (lines[i - 1]?.trim() || "") !== "") {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD022: Headings should be surrounded by blank lines (above)", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: lines[i-1] || "",
                context: "MarkdownAuditor" 
            });
        }

        const nextLine = lines[i + 1]?.trim() || "";
        if (i < lines.length - 1 && nextLine !== "" && !nextLine.startsWith("#")) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD022: Headings should be surrounded by blank lines (below)", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: nextLine,
                context: "MarkdownAuditor" 
            });
        }

        const text = stripped.replace(/^#+\s+/, "");
        if (context.hMap.has(text)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: `MD024: Duplicate heading: '${text}'`, 
                severity: "medium", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: text,
                context: "MarkdownAuditor" 
            });
        }
        context.hMap.set(text, i);

        if (/[.,;:!?]$/.test(text)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD026: Trailing punctuation in heading", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: text,
                context: "MarkdownAuditor" 
            });
        }
    }
}

export class ReflexEngine {
    constructor() {
        this.registerListeners();
    }

    private registerListeners(): void {
        eventBus.on("system:health-check", ({ score, findings }: { score: number, findings: GenericFinding[] }) => {
            this.triggerReflexes({ health_score: score }, findings);
        });
    }

    triggerReflexes(snapshot: { health_score: number }, findings: GenericFinding[]) {
        const score = snapshot.health_score || 0;

        logger.info(`🧠 [Reflex] Analisando saúde sistêmica: ${score}%`);

        if (score < 40) {
            this.activateEmergencyMode();
        }

        this.checkDependencyReflex(findings);
    }

    /**
     * Entra em modo de emergência: emite evento para travar experimentações.
     */
    private activateEmergencyMode() {
        logger.warn("🚨 [Reflex] MODO DE EMERGÊNCIA ATIVADO (Saúde < 40%)");
        eventBus.emit("system:halt-experimentation");
    }

    /**
     * Verifica se há falhas em submodulos/dependências que exigem resync.
     */
    private checkDependencyReflex(findings: GenericFinding[]) {
        const hasDepIssue = findings.some(f => 
            f.context === 'DependencyAuditor' || 
            (f.issue && (f.issue.toLowerCase().includes('submodule') || f.issue.toLowerCase().includes('dependency')))
        );

        if (hasDepIssue) {
            logger.info("📦 [Reflex] Detectada falha de dependência. Agendando resync de submodulos...");
            // Emite evento para que o Orchestrator ou Hub nativo processe o resync
            eventBus.emit("cache:updated"); // Placeholder para forçar atualização de contexto
        }
    }
}

export class PredictorEngine {
    private predictor: MicroPredictor;
    private currentSequence: string[] = [];
    private projectRoot: string;

    // The history of previous healthy runs used to train the system dynamically.
    // In a full production scenario this would load from a JSON file.
    private trainingHistory: string[][] = [];

    // All possible expected events that happen during diagnostics/audits.
    public readonly VOCABULARY = [
        "PIPELINE_START",
        "DISCOVERY_PHASE_START",
        "DISCOVERY_FINDINGS",
        "CENSUS_VALIDATION",
        "COGNITIVE_AUDIT",
        "AUTO_HEAL_ATTEMPT",
        "AUTO_HEAL_SUCCESS",
        "VALIDATION_PHASE",
        "METRICS_GENERATED",
        "PIPELINE_FINISHED",
        // Anomalous/Error states we might see naturally
        "PIPELINE_ABORTED",
        "FATAL_ERROR",
        "TIMEOUT",
        // Hardware & System Integrity Events (New in Phase 5)
        "CPU_STRESS",
        "MEMORY_HIGH",
        "HEAL_THROTTLED",
        "CONCURRENCY_CAP_REACHED"
    ];

    constructor(projectRoot: string) {
        this.projectRoot = projectRoot;
        this.predictor = new MicroPredictor(this.VOCABULARY);
        const loaded = this.loadModel();
        if (!loaded) {
            this.loadOrSeedTrainingData();
        }
    }

    /**
     * Records an event in the current pipeline execution window.
     */
    public recordEvent(eventName: string): void {
        if (!this.VOCABULARY.includes(eventName)) {
            logger.debug(`[Predictor] Ignoing unknown event: ${eventName}`);
            return;
        }
        this.currentSequence.push(eventName);
        logger.debug(`[Predictor] Event recorded: ${eventName} (Window: ${this.currentSequence.length})`);
    }

    /**
     * Clears the current sequence window (e.g. when a new pipeline starts).
     */
    public clearCurrentSequence(): void {
        this.currentSequence = [];
    }

    /**
     * Commits the current successful sequence to the training history to continuously learn.
     */
    public learnCurrentSequence(): void {
        if (this.currentSequence.length > 2) {
            this.trainingHistory.push([...this.currentSequence]);
            // Keep only the last 50 healthy sequences so it adapts over time without exploding memory
            if (this.trainingHistory.length > 50) this.trainingHistory.shift();

            // Re-train slightly on the new reality
            this.predictor.train(this.trainingHistory, 50, 0.01);
            logger.info(`🔮 [Predictor] Learned new successful pattern. (History size: ${this.trainingHistory.length})`);
        }
    }

    /**
     * Mathematically evaluates how "weird" the current sequence of events is.
     * @returns Anomaly Score (Perplexity / Loss). Higher is worse.
     */
    public evaluateCurrentFlow(): number {
        if (this.currentSequence.length === 0) return 0;
        const loss = this.predictor.calculateAnomalyScore(this.currentSequence);
        return loss;
    }

    /**
     * Saves the current model weights to disk.
     */
    public saveModel(): void {
        try {
            const weights = this.predictor.exportWeights();
            const configPath = `${this.projectRoot}/.gemini/microgpt_weights.json`;
            fs.writeFileSync(configPath, JSON.stringify(weights, null, 2));
            logger.info(`🔮 [Predictor] Model weights saved to ${configPath}`);
        } catch (err) {
            logger.error(`🚨 [Predictor] Failed to save weights: ${err}`);
        }
    }

    /**
     * Loads the model weights from disk.
     */
    public loadModel(): boolean {
        try {
            const configPath = `${this.projectRoot}/.gemini/microgpt_weights.json`;
            if (fs.existsSync(configPath)) {
                const data = JSON.parse(fs.readFileSync(configPath, "utf-8"));
                this.predictor.importWeights(data);
                logger.info(`🔮 [Predictor] Model weights loaded from ${configPath}`);
                return true;
            }
        } catch (err) {
            logger.warn(`⚠️ [Predictor] Failed to load weights: ${err}`);
        }
        return false;
    }

    /**
     * Initializes the Predictor with a "Healthy Baseline" so it knows what normal looks like.
     */
    private loadOrSeedTrainingData(): void {
        // Here we seed a perfectly healthy, standard diagnostic run.
        const baselineHealthyRun = [
            "PIPELINE_START",
            "DISCOVERY_PHASE_START",
            "DISCOVERY_FINDINGS",
            "CENSUS_VALIDATION",
            "COGNITIVE_AUDIT",
            "VALIDATION_PHASE",
            "METRICS_GENERATED",
            "PIPELINE_FINISHED"
        ];

        const baselineWithHeal = [
            "PIPELINE_START",
            "DISCOVERY_PHASE_START",
            "DISCOVERY_FINDINGS",
            "CENSUS_VALIDATION",
            "COGNITIVE_AUDIT",
            "AUTO_HEAL_ATTEMPT",
            "AUTO_HEAL_SUCCESS",
            "VALIDATION_PHASE",
            "METRICS_GENERATED",
            "PIPELINE_FINISHED"
        ];

        // Seed with multiple copies to form a strong prior distribution
        for (let i = 0; i < 5; i++) {
            this.trainingHistory.push([...baselineHealthyRun]);
        }
        for (let i = 0; i < 3; i++) {
            this.trainingHistory.push([...baselineWithHeal]);
        }

        logger.info("🔮 [Predictor] Initializing MicroGPT Anomaly Neural Engine...");
        this.predictor.train(this.trainingHistory, 150, 0.05);
        logger.info("🔮 [Predictor] Neural baseline established.");
    }

    /**
     * Returns sanity metrics for reporting.
     */
    public getSanityMetrics(): { score: number, status: string, label: string } {
        const score = this.evaluateCurrentFlow();
        let status = "Healthy";
        let label = "✅ Sanidade Neural Nominal";

        if (score > 1.5) {
            status = "Suspicious";
            label = "⚠️ Fluxo Não-Convencional Detectado";
        }
        if (score > 3.0) {
            status = "Anomaly";
            label = "🚨 Anomalia Sequencial Crítica";
        }

        return { score, status, label };
    }
}

export class TelemetryIntentJudge {
    judgeIntent(codeLine: string, surroundingContext: string): TelemetryJudgment {
        if (JudgeHelpers.isRuleDefinition(codeLine)) return { isSafe: true, severity: "STRATEGIC", reason: "Definição técnica." };
        if (JudgeHelpers.isInsideCriticalReport(surroundingContext)) return { isSafe: false, severity: "HIGH", reason: "Telemetria manual em fluxo de erro." };
        if (JudgeHelpers.isInsideLogCall(surroundingContext)) return { isSafe: false, severity: "STRATEGIC", reason: "Telemetria manual em Log." };
        if (JudgeHelpers.isSimpleTimeSubtraction(codeLine)) return { isSafe: false, severity: "STRATEGIC", reason: "Subtração simples detectada." };
        if (JudgeHelpers.isTelemetryName(codeLine)) return { isSafe: false, severity: "STRATEGIC", reason: "Cálculo de duração manual." };
        return { isSafe: false, severity: "MEDIUM", reason: "Telemetria manual em Lógica." };
    }

    scanFile(content: string, filePath: string): Array<{ line: number; judgment: TelemetryJudgment }> {
        const lines = content.split("\n"), findings: any[] = [];
        for (let i = 0; i < lines.length; i++) {
            const line = lines[i]!;
            if (!JudgeHelpers.hasTelemetrySignal(line) || CORE_PERFORMANCE_FUNCS.some(fn => line.includes(fn))) continue;
            const judgment = this.judgeIntent(line, lines.slice(Math.max(0, i - 1), Math.min(lines.length, i + 1)).join("\n"));
            if (!judgment.isSafe) findings.push({ line: i + 1, judgment });
        }
        logger.debug(`⚖️ ${filePath}: ${findings.length} telemetry findings`);
        return findings;
    }
}

export interface TelemetryJudgment {
    isSafe: boolean;
    severity: TelemetrySeverity;
    reason: string;
}

export class FileSystemScanner {
    root: Path;
    analyst: any;

    constructor(root: string, analyst: any) {
        this.root = new Path(root);
        this.analyst = analyst;
        logger.debug(`FileSystemScanner initialized for root: ${this.root.toString()}`);
    }

    async scanAllFilenames(): Promise<string[]> {
        const files: string[] = [];
        await this.walkFiles(this.root.toString(), files);
        return files;
    }

    private async walkFiles(dir: string, files: string[]) {
        if (ForbiddenPolicy.isForbiddenDir(dir)) return;

        const entries = await readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
            await this.processEntry(dir, entry, files);
        }
    }

    private async processEntry(dir: string, entry: any, files: string[]) {
        const res = join(dir, entry.name);
        if (entry.isDirectory()) {
            await this.walkFiles(res, files);
        } else {
            files.push(entry.name.toLowerCase());
        }
    }

    async *getAnalyzableFiles(): AsyncGenerator<Path> {
        const seen = new Set<string>();
        const generator = this._walkAndYield(this.root.toString());

        for await (const pathStr of generator) {
            const path = new Path(pathStr);
            if (!seen.has(pathStr) && !(await this.shouldSkip(path))) {
                seen.add(pathStr);
                yield path;
            }
        }
    }

    private async * _walkAndYield(dir: string): AsyncGenerator<string> {
        if (ForbiddenPolicy.isForbiddenDir(dir)) return;

        const entries = await readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
            yield* this._processYieldEntry(dir, entry);
        }
    }

    private async * _processYieldEntry(dir: string, entry: any): AsyncGenerator<string> {
        const res = join(dir, entry.name);
        if (entry.isDirectory()) {
            yield* this._walkAndYield(res);
        } else {
            yield res;
        }
    }

    async shouldSkip(path: Path): Promise<boolean> {
        if (!(await path.isFile())) return true;

        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();
        return this.isPathForbiddenOrIgnored(path, pathStr);
    }

    private isPathForbiddenOrIgnored(path: Path, pathStr: string): boolean {
        if (ForbiddenPolicy.isForbiddenDir(dirname(pathStr))) return true;
        if (this.isAgentRelated(pathStr)) return true;
        if (this.isIgnoredByAnalyst(path)) return true;
        return !this.analyst.isAnalyable(path);
    }

    private isAgentRelated(pathStr: string): boolean {
        return pathStr.includes("/.agent/") && !pathStr.includes("fast-android-build");
    }

    private isIgnoredByAnalyst(path: Path): boolean {
        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();
        return !pathStr.includes("src_local") && this.analyst.shouldIgnore(path);
    }
}

export class HistoryAgent {
    private db: Database;

    constructor(projectRoot: string) {
        const dbPath = new Path(projectRoot).join("system_vault.db").toString();
        this.db = new Database(dbPath);
        this.initDb();
    }

    private initDb() {
        this.db.run(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT UNIQUE, name TEXT, last_diagnostic DATETIME, health_score FLOAT DEFAULT 0)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS health_history (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, score FLOAT, alerts INTEGER, entropy_avg FLOAT, breakdown_json TEXT)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS ai_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, task_type TEXT, target_file TEXT, status TEXT DEFAULT 'PENDING', result TEXT)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS ai_insights (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, mode TEXT, insight TEXT, tokens_used INTEGER, impact_level TEXT)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS user_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, app_name TEXT, category TEXT, duration_seconds INTEGER)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS memory_baseline (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, ram_percent FLOAT, is_idle BOOLEAN)`);
        this.db.run(`CREATE TABLE IF NOT EXISTS system_settings (key TEXT PRIMARY KEY, value TEXT)`);
    }

    getSetting(key: string, defaultValue: string = "false"): string {
        const query = this.db.query("SELECT value FROM system_settings WHERE key = ?");
        const row = query.get(key) as { value: string } | null;
        return row ? row.value : defaultValue;
    }

    setSetting(key: string, value: any) {
        try {
            this.db.run("INSERT OR REPLACE INTO system_settings (key, value) VALUES (?, ?)", [key, String(value)]);
        } catch (e) {
            logger.error(`❌ Erro ao salvar config ${key}: ${e}`);
        }
    }

    recordInsight(mode: string, insight: string, tokens: number = 0, impact: string = "LOW") {
        try {
            this.db.run("INSERT INTO ai_insights (mode, insight, tokens_used, impact_level) VALUES (?, ?, ?, ?)", [mode, insight, tokens, impact]);
            logger.info(`🧠 [History] Insight de ${mode} registrado.`);
        } catch (e) {
            logger.error(`❌ Erro ao salvar insight: ${e}`);
        }
    }

    recordSnapshot(score: number, alerts: number, entropy: number, breakdown: any = null) {
        try {
            const bJson = breakdown ? JSON.stringify(breakdown) : null;
            this.db.run("INSERT INTO health_history (score, alerts, entropy_avg, breakdown_json) VALUES (?, ?, ?, ?)", [score, alerts, entropy, bJson]);
            this.checkEntropyTrend(entropy);
            logger.info(`📊 [History] Snapshot salvo: Score ${score}%`);
        } catch (e) {
            logger.error(`❌ Erro ao salvar histórico: ${e}`);
        }
    }

    private checkEntropyTrend(currentEntropy: number) {
        const query = this.db.query("SELECT entropy_avg FROM health_history ORDER BY timestamp DESC LIMIT 1 OFFSET 1");
        const row = query.get() as { entropy_avg: number } | null;
        if (row && row.entropy_avg > 0) {
            const growth = (currentEntropy - row.entropy_avg) / row.entropy_avg;
            if (growth > 0.10) {
                logger.warn(`🌡️ [Heatmap] Alerta: A entropia sistêmica cresceu ${(growth * 100).toFixed(1)}%! Refatoração recomendada.`);
            }
        }
    }

    generateTrendData(): number[] {
        const query = this.db.query("SELECT score FROM health_history ORDER BY timestamp DESC LIMIT 30");
        const rows = query.all() as { score: number }[];
        return rows.map(r => r.score).reverse();
    }
}

export class MemoryEngine {
    private dbHub: DatabaseHub;
    private thinkingDepth: number = 7;

    constructor(projectRoot: string, private hubManager?: HubManagerGRPC) {
        this.dbHub = DatabaseHub.getInstance(projectRoot);
    }

    setDepth(level: number) {
        this.thinkingDepth = level;
        logger.info(`🧪 [Memory] Profundidade de pensamento ajustada para: ${level}`);
    }

    rememberFinding(finding: any) {
        try {
            const file = finding.file || "unknown";
            const message = finding.issue || finding.message;
            const severity = finding.severity || "INFO";

            this.dbHub.run(
                "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
                ["MEMORY", `Finding in ${file}: ${message}`, severity]
            );
            logger.debug(`🧠 [Memory] Memorizado: ${file} (${finding.type || "GENERIC"})`);
        } catch (e) {
            logger.error(`❌ Erro ao memorizar achado: ${e}`);
        }
    }

    public async syncProjectMemory(contextMap: Record<string, { content: string, component_type: string }>): Promise<void> {
        logger.info("🧠 [Memory] Sincronizando memória estrutural...");

        const tasks: Promise<void>[] = [];
        for (const [relPath, data] of Object.entries(contextMap)) {
            tasks.push(this.syncFileMemory(relPath, data.content));
        }
        await Promise.all(tasks);
    }

    private async syncFileMemory(relPath: string, content: string): Promise<void> {
        if (!content) return;

        const hash = Bun.hash(content).toString();
        if (this.isMemoryUpToDate(relPath, hash)) return;

        await this.updateFileMemory(relPath, content, hash);
    }

    private isMemoryUpToDate(relPath: string, hash: string): boolean {
        const query = "SELECT insight FROM ai_insights WHERE mode = 'HASH' AND insight LIKE ?";
        const existing = this.dbHub.query(query).get(`${relPath}:%`);
        return !!existing && (existing as any).insight === `${relPath}:${hash}`;
    }

    private async updateFileMemory(relPath: string, content: string, hash: string): Promise<void> {
        let anchors: string[] = [];

        if (this.hubManager) {
            try {
                const analysis = await this.hubManager.analyzeFile(relPath, content);
                if (analysis && analysis.symbols) {
                    anchors = analysis.symbols.map((s: any) => `${s.kind}:${s.name}`);
                }
            } catch (e) {
                logger.error(`❌ [Memory] Erro ao extrair âncoras via Hub para ${relPath}: ${e}`);
            }
        }

        if (anchors.length === 0) {
            logger.debug(`⚠️ [Memory] Sem âncoras extraídas para ${relPath}.`);
        }

        this.dbHub.run("DELETE FROM ai_insights WHERE mode = 'HASH' AND insight LIKE ?", [`${relPath}:%`]);
        this.dbHub.run(
            "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
            ["HASH", `${relPath}:${hash}`, "SYSTEM"]
        );

        if (anchors.length > 0) {
            this.dbHub.run(
                "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
                ["RAG", `Anchors for ${relPath}: ${anchors.join(", ")}`, "STRATEGIC"]
            );
        }
    }

    searchSimilar(query: string): any[] {
        try {
            const sql = "SELECT * FROM ai_insights WHERE mode IN ('MEMORY', 'RAG') AND insight LIKE ? ORDER BY timestamp DESC LIMIT 5";
            return this.dbHub.query(sql).all(`%${query}%`);
        } catch (e) {
            logger.error(`❌ Erro na busca de memória: ${e}`);
            return [];
        }
    }

    prune() {
        try {
            this.dbHub.run("DELETE FROM ai_insights WHERE mode != 'HASH' AND timestamp < datetime('now', '-30 days')");
        } catch (e) {
            logger.error(`❌ Erro ao podar memória: ${e}`);
        }
    }
}

export class NativeFFIBridge {
    private static instance: NativeFFIBridge | null = null;
    private lib: any = null;
    private isAvailable: boolean = false;

    private constructor(projectRoot: string = process.cwd()) {
        this.initLibrary(projectRoot);
    }

    public static getInstance(projectRoot?: string): NativeFFIBridge {
        if (!NativeFFIBridge.instance) {
            NativeFFIBridge.instance = new NativeFFIBridge(projectRoot);
        }
        return NativeFFIBridge.instance;
    }

    private initLibrary(projectRoot: string) {
        try {
            const libName = `analyzer_lib.${suffix}`;
            const searchPaths = [
                path.join(projectRoot, "src_native", "analyzer", "target", "release", libName),
                path.join(projectRoot, "src_native", "analyzer", "target", "debug", libName),
                path.join(projectRoot, "bin", libName)
            ];

            const libPath = searchPaths.find(p => fs.existsSync(p));

            if (!libPath) {
                logger.info("ℹ️ [Bun:FFI] Biblioteca nativa não encontrada em disco. Usando fallback estático TS.");
                return;
            }

            this.lib = dlopen(libPath, {
                calculate_complexity: {
                    args: [FFIType.cstring],
                    returns: FFIType.i32
                },
                fast_hash: {
                    args: [FFIType.cstring],
                    returns: FFIType.u64
                }
            });

            this.isAvailable = true;
            logger.info(`⚡ [Bun:FFI] Biblioteca nativa carregada com sucesso: ${libPath}`);
        } catch (err: any) {
            logger.warn(`⚠️ [Bun:FFI] Não foi possível inicializar FFI nativo: ${err.message}. Ativando modo fallback.`);
            this.isAvailable = false;
        }
    }

    public isNativeAvailable(): boolean {
        return this.isAvailable;
    }

    public calculateComplexityNative(codeContent: string): number {
        if (!this.isAvailable || !this.lib) {
            const keywords = ["if ", "if(", "for ", "for(", "while ", "while(", "catch ", "catch(", "case "];
            let count = 1;
            for (const kw of keywords) {
                let idx = -1;
                while ((idx = codeContent.indexOf(kw, idx + 1)) !== -1) count++;
            }
            return count;
        }
        try {
            const buffer = Buffer.from(codeContent + "\0", "utf-8");
            return this.lib.symbols.calculate_complexity(buffer);
        } catch (e: any) {
            logger.error(`❌ [Bun:FFI] Erro na execução FFI (complexity): ${e.message}`);
            return 1;
        }
    }

    public fastHashNative(codeContent: string): bigint {
        if (!this.isAvailable || !this.lib) {
            let hasher = 0xcbf29ce484222325n;
            const encoder = new TextEncoder();
            const bytes = encoder.encode(codeContent);
            for (const b of bytes) {
                hasher ^= BigInt(b);
                hasher = (hasher * 0x100000001b3n) & 0xFFFFFFFFFFFFFFFFn;
            }
            return hasher;
        }
        try {
            const buffer = Buffer.from(codeContent + "\0", "utf-8");
            return this.lib.symbols.fast_hash(buffer);
        } catch (e: any) {
            logger.error(`❌ [Bun:FFI] Erro na execução FFI (hash): ${e.message}`);
            return 0n;
        }
    }

    public close() {
        if (this.lib && typeof this.lib.close === "function") {
            this.lib.close();
            this.lib = null;
            this.isAvailable = false;
            logger.info("🔌 [Bun:FFI] Biblioteca nativa descarregada da memória.");
        }
    }

    public [Symbol.dispose](): void {
        this.close();
    }

    public async [Symbol.asyncDispose](): Promise<void> {
        this.close();
    }
}

