export class HubWatcher {
    private manager: HubManagerGRPC;
    private onChangeCallbacks: ((path: string) => void)[] = [];
    private host: string;

    constructor(host?: string, manager?: HubManagerGRPC) {
        this.host = host || "localhost:50051";
        this.manager = manager || HubManagerGRPC.getInstance(host);
    }

    start() {
        logger.info(`📡 [HubWatcher] Conectando ao gRPC Hub...`);
        this.listen();
    }

    private listen() {
        try {
            this.manager.watchEvents((event) => {
                if (event.type === "FILE_EVENT") {
                    this.notify(event.path);
                }
            });

            this.manager.watchHealth((update) => {
                // Emite para o sistema se necessário, ou loga
                if (update.cpuUsage > 80 || update.memoryUsage > 80) {
                    logger.warn(`⚠️ [HubWatcher] ALERTA DE SAÚDE: CPU ${update.cpuUsage}%, MEM ${update.memoryUsage}%`);
                }
            });
        } catch (err) {
            logger.warn(`⚠️ [HubWatcher] Falha ao iniciar streams gRPC: ${err}`);
        }
    }

    stop() {
        this.manager.close();
        logger.info(`📡 [HubWatcher] Conexão encerrada.`);
    }


    onChange(callback: (path: string) => void) {
        this.onChangeCallbacks.push(callback);
    }

    private notify(path: string) {
        // Debounce or filter internal files if needed
        if (path.includes(".git") || path.includes("node_modules")) return;

        logger.info(`✨ [HubWatcher] Mudança detectada: ${path}`);
        this.onChangeCallbacks.forEach(cb => cb(path));
    }
}

export class MemoryEngine {
    private dbHub: DatabaseHub;
    private thinkingDepth: number = 7;

    constructor(projectRoot: string, private hubManager?: HubManagerGRPC) {
        this.dbHub = DatabaseHub.getInstance(projectRoot);
    }

    setDepth(level: number) {
        this.thinkingDepth = level;
        logger.info(`🧪 [Memory] Profundidade de pensamento ajustada para: ${level}`);
    }

    rememberFinding(finding: any) {
        try {
            const file = finding.file || "unknown";
            const message = finding.issue || finding.message;
            const severity = finding.severity || "INFO";

            this.dbHub.run(
                "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
                ["MEMORY", `Finding in ${file}: ${message}`, severity]
            );
            logger.debug(`🧠 [Memory] Memorizado: ${file} (${finding.type || "GENERIC"})`);
        } catch (e) {
            logger.error(`❌ Erro ao memorizar achado: ${e}`);
        }
    }

    public async syncProjectMemory(contextMap: Record<string, { content: string, component_type: string }>): Promise<void> {
        logger.info("🧠 [Memory] Sincronizando memória estrutural...");

        const tasks: Promise<void>[] = [];
        for (const [relPath, data] of Object.entries(contextMap)) {
            tasks.push(this.syncFileMemory(relPath, data.content));
        }
        await Promise.all(tasks);
    }

    private async syncFileMemory(relPath: string, content: string): Promise<void> {
        if (!content) return;

        const hash = Bun.hash(content).toString();
        if (this.isMemoryUpToDate(relPath, hash)) return;

        await this.updateFileMemory(relPath, content, hash);
    }

    private isMemoryUpToDate(relPath: string, hash: string): boolean {
        const query = "SELECT insight FROM ai_insights WHERE mode = 'HASH' AND insight LIKE ?";
        const existing = this.dbHub.query(query).get(`${relPath}:%`);
        return !!existing && (existing as any).insight === `${relPath}:${hash}`;
    }

    private async updateFileMemory(relPath: string, content: string, hash: string): Promise<void> {
        let anchors: string[] = [];
        
        if (this.hubManager) {
            try {
                const analysis = await this.hubManager.analyzeFile(relPath, content);
                if (analysis && analysis.symbols) {
                    anchors = analysis.symbols.map((s: any) => `${s.kind}:${s.name}`);
                }
            } catch (e) {
                logger.error(`❌ [Memory] Erro ao extrair âncoras via Hub para ${relPath}: ${e}`);
            }
        }

        // Se o Hub falhar ou não estiver disponível, não usamos fallback de Regex (Soberania de Qualidade)
        if (anchors.length === 0) {
            logger.debug(`⚠️ [Memory] Sem âncoras extraídas para ${relPath}.`);
        }

        this.dbHub.run("DELETE FROM ai_insights WHERE mode = 'HASH' AND insight LIKE ?", [`${relPath}:%`]);
        this.dbHub.run(
            "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
            ["HASH", `${relPath}:${hash}`, "SYSTEM"]
        );

        if (anchors.length > 0) {
            this.dbHub.run(
                "INSERT INTO ai_insights (mode, insight, impact_level) VALUES (?, ?, ?)",
                ["RAG", `Anchors for ${relPath}: ${anchors.join(", ")}`, "STRATEGIC"]
            );
        }
    }

    searchSimilar(query: string): any[] {
        try {
            const sql = "SELECT * FROM ai_insights WHERE mode IN ('MEMORY', 'RAG') AND insight LIKE ? ORDER BY timestamp DESC LIMIT 5";
            return this.dbHub.query(sql).all(`%${query}%`);
        } catch (e) {
            logger.error(`❌ Erro na busca de memória: ${e}`);
            return [];
        }
    }

    prune() {
        try {
            this.dbHub.run("DELETE FROM ai_insights WHERE mode != 'HASH' AND timestamp < datetime('now', '-30 days')");
        } catch (e) {
            logger.error(`❌ Erro ao podar memória: ${e}`);
        }
    }
}

export class MarkdownStructureProcessor {
    private raw: string[];
    private res: string[] = [];
    private state = { seen: {} as Record<string, number>, inCb: false };

    constructor(rawLines: string[]) {
        this.raw = rawLines;
    }

    /**
     * Processa a estrutura do documento.
     */
    process(): string[] {
        logger.debug(`📝 [MarkdownProcessor] Iniciando processamento de ${this.raw.length} linhas.`);

        for (let i = 0; i < this.raw.length; i++) {
            const line = this.raw[i];
            if (line === undefined) continue;
            const stripped = line.trimEnd();

            // Gerenciamento de blocos de código
            if (this.handleBlock(stripped, line)) continue;

            // Processamento de Cabeçalhos
            if (stripped.trim().startsWith('#')) {
                this.handleHeader(stripped.trim(), i);
            } else if (this.shouldAppend(stripped)) {
                // Conteúdo regular ou espaçamento horizontal
                this.res.push(stripped);
            }
        }

        // MD041: Garante que não comece com linhas vazias (será tratado no sanitizer se necessário)
        return this.res;
    }

    private handleBlock(stripped: string, original: string): boolean {
        if (stripped.trim().startsWith('```')) {
            this.state.inCb = !this.state.inCb;
            this.res.push(original);
            return true;
        }
        if (this.state.inCb) {
            this.res.push(original);
            return true;
        }
        return false;
    }

    private handleHeader(line: string, idx: number): void {
        // MD022: Espaçamento acima
        if (this.res.length > 0 && this.res[this.res.length - 1] !== "") {
            this.res.push("");
        }

        const h = MarkdownUtil.deduplicateHeader(line, this.state.seen);
        this.res.push(h);

        // MD022: Espaçamento abaixo
        MarkdownUtil.applyHeaderPadding(this.res, this.raw, idx);
    }

    private shouldAppend(stripped: string): boolean {
        // Evita linhas em branco consecutivas (MD012)
        return stripped.trim() !== "" || (this.res.length > 0 && this.res[this.res.length - 1] !== "");
    }
}

export class PolyglotParser {
    constructor(private hubManager?: HubManagerGRPC) { }

    analyzeKt(content: string) {
        const lines = content.split('\n');
        return {
            imports: lines.filter(l => l.startsWith('import ')).map(l => l.split(/\s+/)[1] || ''),
            functions: [...content.matchAll(/fun\s+(\w+)/g)].map(m => m[1] || ''),
            classes: [...content.matchAll(/class\s+(\w+)/g)].map(m => m[1] || '')
        };
    }

    async calculateKtComplexity(filename: string): Promise<number> {
        return this.callHubScanner(filename);
    }

    analyzeGo(content: string) {
        const functions = [...content.matchAll(/func\s+(?:\([^)]+\)\s+)?(\w+)\s*\(/g)].map(m => m[1] || '');
        const structs = [...content.matchAll(/type\s+(\w+)\s+struct/g)].map(m => m[1] || '');
        return { functions, classes: structs };
    }

    async calculateGoComplexity(filename: string): Promise<number> {
        return this.callHubScanner(filename);
    }

    private async callHubScanner(filename: string): Promise<number> {
        if (!this.hubManager) return 1;

        try {
            const result = await this.hubManager.analyzeFile(filename);
            return result?.total_complexity || 1;
        } catch (err) {
            console.error(`[PolyglotParser] gRPC proxy calculation failed for ${filename}:`, err);
            return 1;
        }
    }

    analyzeDart(content: string) {
        const classes = [...content.matchAll(/class\s+(\w+)/g)].map(m => m[1] || '');
        const functions = [...content.matchAll(/(\w+)\s+\w+\s*\(.*?\)\s*{/g)]
            .map(this.extractDartFunctionName)
            .filter(this.isValidDartFunctionName);
        return { functions, classes };
    }

    private extractDartFunctionName(m: RegExpMatchArray): string {
        const parts = m[0].split(/\s+/);
        return (parts[1] || "").replace('(', '');
    }

    private isValidDartFunctionName(f: string): boolean {
        return f !== "" && f !== 'if' && f !== 'for';
    }
}

export class ActivityClassifier {
    static classify(app: string, title: string): string {
        const app_l = app.toLowerCase();
        const title_l = title.toLowerCase();

        if (this.isDev(app_l)) return "DEV";
        if (this.isGaming(app_l)) return "GAMING";
        if (this.isBrowsing(app_l)) return this.isMedia(title_l) ? "MEDIA" : "BROWSING";

        return "GENERAL";
    }

    private static isDev(app: string): boolean {
        return ["code", "powershell", "cmd", "wt", "pycharm", "cursor"].includes(app);
    }

    private static isGaming(app: string): boolean {
        return ["steam", "valorant", "cs2", "minecraft"].includes(app);
    }

    private static isBrowsing(app: string): boolean {
        return ["chrome", "msedge", "firefox", "brave"].includes(app);
    }

    private static isMedia(title: string): boolean {
        return title.includes("youtube") || title.includes("netflix");
    }
}

export class PurityScorer {
    static calculate(mapData: Record<string, any>, total: number): [number, number] {
        let totalCC = 0;
        let countWithAdvanced = 0;

        for (const [file, info] of Object.entries(mapData)) {
            const advanced = info.advanced_metrics;
            if (advanced?.cyclomaticComplexity) {
                totalCC += advanced.cyclomaticComplexity;
                countWithAdvanced++;
            }
        }

        let avg: number;
        if (countWithAdvanced > 0) {
            const avgCC = totalCC / countWithAdvanced;
            const simpleAvg = Object.values(mapData).reduce((sum, i) => sum + (i.complexity || 1), 0) / total;
            avg = (avgCC + simpleAvg) / 2;
        } else {
            avg = Object.values(mapData).reduce((sum, i) => sum + (i.complexity || 1), 0) / total;
        }

        // 🔬 PhD Calibration: Média <= 7.0 representa Excelência Técnica em escala.
        const score = Math.max(0, 20 - (Math.max(0, avg - 7.0) * 2));
        return [score, avg];
    }
}

