export class RiskPolicy {
    static determineRiskLevel(cyclomatic: number, cognitive: number, mi: number): "LOW" | "MODERATE" | "HIGH" | "CRITICAL" {
        if (cyclomatic > 50 || mi < 9) return "CRITICAL";
        if (cyclomatic > 20 || mi < 10) return "HIGH";
        if (cyclomatic > 10 || mi < 20) return "MODERATE";
        return "LOW";
    }

    static determineQualityGate(mi: number, cc: number, defectDensity: number, sloc: number = 0): "GREEN" | "YELLOW" | "RED" {
        // 🔬 Technical Sovereignty: Componentes abaixo do nível de hotspot (>20) e sem defeitos são GREEN.
        if (cc <= 20 && defectDensity === 0) return "GREEN";
        if (mi >= 15 && cc <= 20 && defectDensity <= 0.5) return "GREEN";
        if (mi >= 8 && cc <= 40 && defectDensity <= 2) return "YELLOW";
        return "RED";
    }
}

export class MaintenanceEnginePhd {
    /**
     * Limpeza recursiva de submódulos.
     */
    static async cleanSubmodules(root: string, git: GitClient): Promise<void> {
        const displayPaths = await git.run(["submodule", "foreach", "--quiet", "echo $displaypath"]);

        if (displayPaths && displayPaths.exitCode === 0 && displayPaths.stdout) {
            const submodules = displayPaths.stdout.split("\n").filter(s => s.trim() !== "");
            for (const sub of submodules) {
                await this.cleanSingleSubmodule(root, sub.trim());
            }
        }
    }

    private static async cleanSingleSubmodule(root: string, sub: string): Promise<void> {
        const subPath = join(root, sub);
        if (existsSync(subPath)) {
            logger.info(`🧹 [Maintenance] Limpando submódulo: ${sub}`);
            await Bun.spawn(["git", "clean", "-fd"], { cwd: subPath }).exited;
        }
    }

    /**
     * Merge inteligente do índice de skills (JSON), preservando IDs protegidos.
     */
    static async mergeSkillsIndex(root: string, filePath: string, git: GitClient, protectedIds: string[]): Promise<boolean> {
        try {
            const ours = await this.getGitVersion(root, filePath, 2);
            const theirs = await this.getGitVersion(root, filePath, 3);

            const mergedMap = this.performSkillsMerge(ours, theirs, protectedIds);
            const result = Array.from(mergedMap.values()).sort((a, b) => (a.id || "").localeCompare(b.id || ""));

            await Bun.write(join(root, filePath), JSON.stringify(result, null, 2));
            return true;
        } catch (error) {
            logger.error(`❌ [Maintenance] Falha no merge de skills: ${error}`);
            return false;
        }
    }

    private static async getGitVersion(root: string, filePath: string, stage: number): Promise<any[]> {
        try {
            const res = await Bun.spawn(["git", "show", `:${stage}:${filePath}`], { cwd: root, stdout: "pipe" });
            const text = await new Response(res.stdout).text();
            return JSON.parse(text);
        } catch {
            logger.debug(`⚠️ Maintenance: Failed to parse stage ${stage} version of ${filePath}.`);
            return [];
        }
    }

    private static performSkillsMerge(ours: any[], theirs: any[], protectedIds: string[]): Map<string, any> {
        const mergedMap = new Map<string, any>();

        for (const item of theirs) {
            this.setIfHasId(mergedMap, item);
        }

        for (const item of ours) {
            this.setIfProtected(mergedMap, item, protectedIds);
        }

        return mergedMap;
    }

    private static setIfHasId(map: Map<string, any>, item: any) {
        if (item.id) map.set(item.id, item);
    }

    private static setIfProtected(map: Map<string, any>, item: any, protectedIds: string[]) {
        if (item.id && protectedIds.includes(item.id)) {
            map.set(item.id, item);
        }
    }
}

export class AuditRiskEngine {
    private readonly RISK_MAP: Array<{ pattern: RegExp; type: RiskType; baseSeverity: string }> = [
        { pattern: /eval\s*\(/, type: "eval", baseSeverity: "CRITICAL" },
        { pattern: /exec\s*\(/, type: "eval", baseSeverity: "CRITICAL" },
        { pattern: /shell\s*[:=]\s*true/i, type: "shell", baseSeverity: "CRITICAL" },
        { pattern: /subprocess|child_process/, type: "shell", baseSeverity: "HIGH" },
        { pattern: /global\s+(var|let|const)/, type: "global", baseSeverity: "MEDIUM" },
        { pattern: /debugger\s*;/, type: "debug", baseSeverity: "MEDIUM" },
        { pattern: /console\.debug/, type: "debug", baseSeverity: "LOW" },
        { pattern: /except\s*:\s*pass/, type: "except", baseSeverity: "HIGH" },
        { pattern: /catch\s*\([^)]*\)\s*\{\s*\}/, type: "except", baseSeverity: "HIGH" },
        { pattern: /crypto\.(create|random)/, type: "crypto", baseSeverity: "MEDIUM" },
        { pattern: /fetch\s*\(|https?:\/\//, type: "network", baseSeverity: "MEDIUM" },
    ];

    /**
     * 🔍 Mapeia o tipo de risco a partir de um padrão regex.
     */
    mapRiskType(regex: string): RiskType {
        const reg = regex.toLowerCase();

        const typeMap: Record<string, RiskType> = {
            "eval": "eval", "shell": "shell", "global": "global", "debug": "debug",
            "except": "except", "catch": "except", "crypto": "crypto",
            "fetch": "network", "http": "network"
        };

        for (const [key, type] of Object.entries(typeMap)) {
            if (reg.includes(key)) return type;
        }
        return "print";
    }

    /**
     * 🏗️ Cria uma entrada de risco estruturada.
     */
    createEntry(file: string, lineIndex: number, issue: string, lines: string[], severityOverride?: string): RiskEntry {
        const start = Math.max(0, lineIndex - 2);
        const end = Math.min(lines.length, lineIndex + 3);
        const riskType = this.mapRiskType(issue);
        const severity = (severityOverride || this._inferSeverity(riskType)).toUpperCase();

        return {
            file, line: lineIndex + 1, issue, severity,
            context: "AuditRiskEngine", snippet: lines.slice(start, end).join("\n"), riskType,
        };
    }

    /**
     * 📊 Escaneia um arquivo inteiro em busca de riscos.
     */
    scanFile(content: string, filePath: string): RiskEntry[] {
        const lines = content.split("\n");
        const entries: RiskEntry[] = [];

        for (let i = 0; i < lines.length; i++) {
            this.scanLine(lines, i, filePath, entries);
        }

        logger.debug(`🎯 ${filePath}: ${entries.length} riscos detectados`);
        return entries;
    }

    private scanLine(lines: string[], i: number, filePath: string, entries: RiskEntry[]) {
        for (const rule of this.RISK_MAP) {
            if (rule.pattern.test(lines[i]!)) {
                entries.push(this.createRuleEntry(filePath, i, rule, lines));
            }
        }
    }

    private createRuleEntry(file: string, i: number, rule: any, lines: string[]): RiskEntry {
        return {
            file,
            line: i + 1,
            issue: `Padrão de risco detectado: ${rule.type}`,
            severity: rule.baseSeverity,
            context: "AuditRiskEngine",
            snippet: lines.slice(Math.max(0, i - 1), Math.min(lines.length, i + 2)).join("\n"),
            riskType: rule.type,
        };
    }

    private _inferSeverity(riskType: RiskType): string {
        const severityMap: Record<RiskType, string> = {
            eval: "CRITICAL", shell: "CRITICAL", global: "MEDIUM",
            debug: "LOW", except: "HIGH", print: "LOW",
            crypto: "MEDIUM", network: "MEDIUM",
        };
        return severityMap[riskType] || "MEDIUM";
    }
}

