        new HeadingRules()
    ];

    lint(lines: string[], i: number, stripped: string, file: string, context: { hMap: Map<string, number>, errs: any[] }): void {
        for (const rule of this.rules) {
            rule.check(lines, i, stripped, file, context);
        }
    }
}

