export class PyramidAnalyst {
    /**
     * Classifica os testes entre Unit, Integration e E2E.
     */
    async analyze(mapData: Record<string, any>, readFunc: (path: string) => Promise<string | null>): Promise<any> {
        winston.debug("Analysing test pyramid distribution...");
        const pyramid = { unit: 0, integration: 0, e2e: 0, total: 0 };

        for (const file of Object.keys(mapData)) {
            if (!file.includes("tests/")) continue;

            const content = await readFunc(file);
            if (!content) continue;

            pyramid.total += 1;
            if (content.includes("mock") || content.includes("patch")) {
                pyramid.integration += 1;
            } else if (content.includes("selenium") || content.includes("integration_test")) {
                pyramid.e2e += 1;
            } else {
                pyramid.unit += 1;
            }
        }

        return pyramid;
    }
}

export class CognitiveValidator {
    private engine: CognitiveEngine;

    constructor() {
        this.engine = new CognitiveEngine();
    }

    async runFullCheck(): Promise<CognitiveHealthReport> {
        logger.info("🧠 Iniciando auditoria de sanidade cognitiva...");
        const report: CognitiveHealthReport = {
            status: "HEALTHY",
            lazyLoading: false,
            reasoningSpeedMs: 0,
            memoryReleased: false,
            response: ""
        };

        try {
            // 1. Teste de Lazy Loading
            report.lazyLoading = (this.engine as any).model === undefined || (this.engine as any).model === null;

            // 2. Teste de Raciocínio
            const start = Date.now();
            const response = await this.engine.reason("Responda apenas com a palavra 'CONSCIENTE'.");
            report.reasoningSpeedMs = Date.now() - start;
            report.response = response || "";

            if (!response || !response.includes("CONSCIENTE")) {
                report.status = "DEGRADED";
            }

            // 3. Teste de Liberação
            await this.engine.release();
            report.memoryReleased = (this.engine as any).model === null;

            if (!report.memoryReleased) {
                report.status = "FAIL";
            }

        } catch (e: any) {
            logger.error(`🚨 Falha crítica no motor cognitivo: ${e.message}`);
            report.status = "FAIL";
            report.error = e.message;
        }

        return report;
    }
}

