export class MetricScanner {
    static scanProcesses(): any[] {
        try {
            const lines = execSync('tasklist /V /FO CSV', { encoding: 'utf8' }).split('\n').slice(1);
            return lines.map(l => {
                const p = l.split('","').map(x => x.replace(/"/g, '')); if (p.length < 5) return null;
                const mKb = parseInt((p[4] || "").replace(/[^\d]/g, '') || "0");
                return mKb > 200000 ? { name: p[0] || "U", pid: parseInt(p[1] || "0") || 0, mem_mb: (mKb / 1024).toFixed(2) } : null;
            }).filter((x): x is any => x !== null).sort((a, b) => parseFloat(b.mem_mb) - parseFloat(a.mem_mb));
        } catch { return []; }
    }

    static getCpuAvg(): number {
        const cpus = os.cpus(); let tIdle = 0, tTick = 0;
        cpus.forEach(c => { Object.values(c.times).forEach(v => tTick += v); tIdle += c.times.idle; });
        return 100 - (100 * tIdle / Math.max(1, tTick));
    }
}

export class MarkdownAuditor {
    public auditFile(filePath: string): LintError[] {
        if (!fs.existsSync(filePath)) return [{ rule: "FILE_NOT_FOUND", line: 0, message: "Target file missing" }];
        return MarkdownAuditor.auditMarkdown(filePath, fs.readFileSync(filePath, "utf-8"));
    }

    public static auditMarkdown(filePath: string, content: string): any[] {
        const lines = content.split("\n"), errors: any[] = [], headings = new Map<string, number>();
        let inCodeBlock = false;
        lines.forEach((line, i) => {
            if (line === undefined) return;
            const stripped = line.trim();
            if (stripped.startsWith("```")) { inCodeBlock = !inCodeBlock; return; }
            if (inCodeBlock) return;
            LintRules.run(lines, i, stripped, filePath, headings, errors);
        });
        return errors;
    }


    public formatErrors(errors: LintError[]): string {
        if (errors.length === 0) return "✅ Relatório em conformidade PhD.";
        let md = `### 🚨 Violações de Conformidade MD (${errors.length})\n\n| Regra | Linha | Mensagem |\n| :--- | :---: | :--- |\n`;
        errors.forEach(err => md += `| \`${err.rule}\` | ${err.line} | ${err.message} |\n`);
        return md;
    }
}

export class WeightManager {
    static export(stateDict: Record<string, Value[][]>): Record<string, number[][]> {
        const weights: Record<string, number[][]> = {};
        for (const [key, mat] of Object.entries(stateDict)) {
            weights[key] = mat.map(row => row.map(v => v.data));
        }
        return weights;
    }

    static import(stateDict: Record<string, Value[][]>, weights: Record<string, number[][]>): void {
        for (const [key, matData] of Object.entries(weights)) {
            const target = stateDict[key];
            if (target) {
                this.updateMatrix(target, matData);
            }
        }
    }

    private static updateMatrix(target: Value[][], data: number[][]) {
        data.forEach((rowData, i) => {
            rowData.forEach((val, j) => {
                if (target[i]?.[j]) {
                    target[i]![j]!.data = val;
                    target[i]![j]!.grad = 0;
                }
            });
        });
    }
}

