export class AttentionEngine {
    static multiHead(li: number, q: Value[], keys: Value[][], values: Value[][], nHead: number, headDim: number, lastWeights: number[][][]): Value[] {
        const xAttn: Value[] = [];
        for (let h = 0; h < nHead; h++) {
            const hs = h * headDim;
            const qH = q.slice(hs, hs + headDim);
            const kH = keys.map((ki) => ki.slice(hs, hs + headDim));
            const vH = values.map((vi) => vi.slice(hs, hs + headDim));

            const logits = kH.map((kHt) => Value.matmul(qH, [kHt])[0]!.mul(1 / headDim ** 0.5));
            const weights = ModelOps.softmax(logits);

            this.capture(li, h, weights, lastWeights);

            for (let j = 0; j < headDim; j++) {
                xAttn.push(weights.reduce((acc, wt, t) => acc.add(wt.mul(vH[t]![j]!)), new Value(0)));
            }
        }
        return xAttn;
    }

    private static capture(li: number, h: number, weights: Value[], lastWeights: number[][][]) {
        if (!lastWeights[li]) lastWeights[li] = [];
        if (!lastWeights[li]![h]) lastWeights[li]![h] = [];
        lastWeights[li]![h]!.push(...weights.map(v => v.data));
    }
}

export class SizeAnalyst {
    /**
     * LOC - Lines of Code
     */
    static countLOC(content: string): number {
        return content.split('\n').length;
    }

    /**
     * LOC Executável (não comentário, não vazio)
     */
    static countExecutableLOC(content: string): number {
        const lines = content.split('\n');
        return lines.filter(line => {
            const trimmed = line.trim();
            return trimmed.length > 0 && !trimmed.startsWith('//') && !trimmed.startsWith('/*') && !trimmed.startsWith('*');
        }).length;
    }

    /**
     * LOC de Comentários
     */
    static countCommentLOC(content: string): number {
        const lines = content.split('\n');
        return lines.filter(line => {
            const trimmed = line.trim();
            return trimmed.startsWith('//') || trimmed.startsWith('/*') || trimmed.startsWith('*');
        }).length;
    }

    /**
     * Profundidade de Aninhamento (AST based)
     */
    static calculateNestingDepth(content: string): number {
        const sourceFile = ts.createSourceFile("temp.ts", content, ts.ScriptTarget.Latest, true);
        let maxDepth = 0;

        const nestableKinds = new Set([
            ts.SyntaxKind.IfStatement,
            ts.SyntaxKind.WhileStatement,
            ts.SyntaxKind.DoStatement,
            ts.SyntaxKind.ForStatement,
            ts.SyntaxKind.ForInStatement,
            ts.SyntaxKind.ForOfStatement,
            ts.SyntaxKind.CatchClause,
            ts.SyntaxKind.SwitchStatement,
            ts.SyntaxKind.FunctionDeclaration,
            ts.SyntaxKind.MethodDeclaration,
            ts.SyntaxKind.ArrowFunction,
            ts.SyntaxKind.ClassDeclaration
        ]);

        const analyze = (node: ts.Node, depth: number) => {
            let nextDepth = depth;
            if (nestableKinds.has(node.kind)) {
                nextDepth++;
                maxDepth = Math.max(maxDepth, nextDepth);
            }
            ts.forEachChild(node, (child) => analyze(child, nextDepth));
        };

        ts.forEachChild(sourceFile, (node) => analyze(node, 0));
        return maxDepth;
    }
}

