export class PythonParser {
    constructor(private hubManager?: HubManagerGRPC) { }

    async analyze(content: string, filename: string): Promise<PythonAnalysis> {
        const functions = [...content.matchAll(/def\s+(\w+)\s*\(/g)].map(m => m[1] || '');
        const classes = [...content.matchAll(/class\s+(\w+)\s*[:\(]/g)].map(m => m[1] || '');
        return { functions, classes, tree: true };
    }

    async calculateComplexity(filename: string): Promise<number> {
        if (!this.hubManager) return 1;

        try {
            const result = await this.hubManager.analyzeFile(filename);
            return result?.total_complexity || 1;
        } catch (err) {
            console.error(`[PythonParser] gRPC complexity calculation failed:`, err);
            return 1;
        }
    }

    extractImports(content: string): string[] {
        const imports: string[] = [];
        const lines = content.split('\n');
        for (const line of lines) {
            const t = line.trim();
            if (!t || t.startsWith('#')) continue;
            if (t.startsWith('import ')) {
                t.substring(7).split(',').forEach(s => {
                    const mod = s.trim().split('.')[0];
                    if (mod) imports.push(mod);
                });
            }
            if (t.startsWith('from ')) {
                const match = t.match(/^from\s+([\w.]+)\s+import/);
                const mod = match?.[1]?.split('.')[0];
                if (mod) imports.push(mod);
            }
        }
        return [...new Set(imports)];
    }
}

export interface PythonAnalysis {
    functions: string[];
    classes: string[];
    tree: boolean | null;
}

export class HalsteadAnalyst {
    static calculate(content: string): { volume: number; difficulty: number; effort: number } {
        const operators = content.match(/[+\-*/%=<>!&|^~?:]+|&&|\|\||\.\.\.|\?\./g) || [];
        const uniqueOperators = new Set(operators);

        const operands = content.match(/\b[a-zA-Z_]\w*\b/g) || [];
        const uniqueOperands = new Set(operands);

        const n1 = uniqueOperators.size;
        const n2 = uniqueOperands.size;
        const N1 = operators.length;
        const N2 = operands.length;

        const totalUnique = n1 + n2;
        const volume = totalUnique > 0 ? totalUnique * Math.log2(totalUnique) : 0;
        const difficulty = n1 > 0 ? (n1 / 2) * (N2 / Math.max(1, n2)) : 0;
        const effort = volume * difficulty;

        return { volume, difficulty, effort };
    }
}

export class AnalysisPolicy {
    private static IGNORED_DIRS = new Set(['.git', '__pycache__', 'build', 'node_modules', '.venv', '.gemini', '.idea', '.vscode', 'dist', 'out']);

    static shouldIgnore(path: Path): boolean {
        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();

        // Bloqueio cirúrgico para infraestrutura .agent
        if (pathStr.includes("/.agent/") || pathStr.startsWith(".agent/")) {
            // Só permitimos se pertencer à skill autorizada
            if (pathStr.includes("fast-android-build")) return false;
            return true;
        }

        return Array.from(this.IGNORED_DIRS).some(p => pathStr.includes(`/${p}/`) || pathStr.endsWith(`/${p}`));
    }

    static isAnalyable(path: Path): boolean {
        const name = path.name();
        return (name.endsWith('.py') || name.endsWith('.ts') || name.endsWith('.tsx') || name.endsWith('.js') || name.endsWith('.yaml') || name.endsWith('.kt') || name.endsWith('.dart'));
    }
}

export class SecuritySentinelAgent {
    private heuristic: VulnerabilityHeuristic;

    constructor(private hubManager?: HubManagerGRPC) {
        this.heuristic = new VulnerabilityHeuristic(this.hubManager);
        if (this.hubManager) logger.info("🛡️ [Security] Hub gRPC integrado ao Sentinel.");
    }

    /**
     * Realiza um scan preventivo de segurança em arquivos específicos.
     */
    async runSecurityScan(files: string[], context: ProjectContext): Promise<AuditFinding[]> {
        if (!context.map) return [];
        logger.info(`🛡️ [Security] Iniciando scan profundo em ${files.length} arquivos...`);
        let findings: AuditFinding[] = [];

        for (const file of files) {
            const entry = context.map[file];
            const content = entry?.content || "";
            if (!content) continue;

            try {
                const result = await this.heuristic.analyze(file, content);
                findings = findings.concat(result.rulesHit.map(rule => ({
                    file,
                    issue: rule.issue,
                    severity: rule.severity.toUpperCase() as any,
                    type: "SECURITY",
                    evidence: rule.regex as string,
                    agent: "SecuritySentinel"
                })));
            } catch (e) {
                logger.error(`❌ [Security] Erro ao analisar ${file}: ${e}`);
            }
        }

        return findings;
    }

    /**
     * Scans the entire project for security vulnerabilities using the deep engine.
     */
    async scanProject(context: ProjectContext): Promise<AuditFinding[]> {
        const files = Object.keys(context.map || {});
        return this.runSecurityScan(files, context);
    }
}

export class UpdateTransaction {
    private backups: Map<string, string> = new Map();
    private active: boolean = false;

    /** Parity: constructor - Matches legacy __init__. */
    constructor() { }

    /**
     * Inicia uma transação, criando cópia de segurança dos arquivos alvo.
     */
    async begin(files: string[]) {
        if (this.active) throw new Error("Transação já em curso.");
        this.active = true;
        this.backups.clear();

        for (const file of files) {
            try {
                if (await fs.stat(file).catch(() => null)) {
                    const content = await fs.readFile(file, "utf-8");
                    this.backups.set(file, content);
                }
            } catch (e) {
                logger.error(`❌ Falha ao criar backup de ${file}: ${e}`);
            }
        }
        logger.info(`🛡️ [Transaction] Iniciada para ${files.length} arquivos.`);
    }

    /**
     * Confirma as alterações, limpando os backups.
     */
    commit() {
        this.backups.clear();
        this.active = false;
        logger.info("✅ [Transaction] Alterações confirmadas com sucesso.");
    }

    /**
     * Reverte todas as alterações realizadas nesta transação.
     */
    async rollback() {
        logger.warn(`⏪ [Transaction] Revertendo ${this.backups.size} alterações...`);
        for (const [file, content] of this.backups.entries()) {
            try {
                await fs.writeFile(file, content, "utf-8");
            } catch (e) {
                logger.error(`🚨 Falha crítica no rollback de ${file}: ${e}`);
            }
        }
        this.backups.clear();
        this.active = false;
    }


}

