export class IntentClassifier {
    static classify(content: string, filename: string, rustMetadata?: any): string {
        if (rustMetadata && rustMetadata.semantic_blocks) {
            let metadata = 0, observability = 0, logic = 0;
            const blocks = rustMetadata.semantic_blocks;
            for (const key in blocks) {
                const intent = blocks[key];
                if (intent === "METADATA") metadata++;
                else if (intent === "OBSERVABILITY") observability++;
                else logic++;
            }
            if (metadata > logic && metadata > observability) return "METADATA";
            if (observability > logic) return "OBSERVABILITY";
            return "LOGIC";
        }

        if (/export\s+(type|interface|enum)\s+/.test(content)) return "METADATA";
        if (/logger\.(info|warn|error|debug)/.test(content)) return "OBSERVABILITY";
        return "LOGIC";
    }
}

export class PurityScorer {
    static calculate(mapData: Record<string, any>, total: number): [number, number] {
        let totalCC = 0;
        let countWithAdvanced = 0;

        for (const [file, info] of Object.entries(mapData)) {
            const advanced = info.advanced_metrics;
            if (advanced?.cyclomaticComplexity) {
                totalCC += advanced.cyclomaticComplexity;
                countWithAdvanced++;
            }
        }

        let avg: number;
        if (countWithAdvanced > 0) {
            const avgCC = totalCC / countWithAdvanced;
            const simpleAvg = Object.values(mapData).reduce((sum, i) => sum + (i.complexity || 1), 0) / total;
            avg = (avgCC + simpleAvg) / 2;
        } else {
            avg = Object.values(mapData).reduce((sum, i) => sum + (i.complexity || 1), 0) / total;
        }

        // 🔬 PhD Calibration: Média <= 7.0 representa Excelência Técnica em escala.
        const score = Math.max(0, 20 - (Math.max(0, avg - 7.0) * 2));
        return [score, avg];
    }
}

export class StabilityScorer {
    static calculate(mapData: Record<string, any>): [number, number, number] {
        const entries = Object.entries(mapData);
        const relevant = this.filterRelevant(entries);
        const markers = this.filterMarkers(entries);

        const total = relevant.length + markers.length;
        const covered = relevant.reduce((sum, [_, i]) => sum + this.getItemStability(i), 0);

        const finalCovered = Math.min(total, covered + markers.length);
        const score = (finalCovered / Math.max(1, total)) * 40;

        return [score, Math.floor(finalCovered), total];
    }

    private static filterRelevant(entries: [string, any][]) {
        const coreTypes = ["AGENT", "CORE", "LOGIC", "UTIL", "UNKNOWN"];
        return entries.filter(([f, i]) =>
            (coreTypes.includes(i.component_type) || i.complexity >= 1) &&
            !["DOC", "TEST"].includes(i.component_type) &&
            !f.includes("/test/") && !f.includes("__init__.py")
        );
    }

    private static filterMarkers(entries: [string, any][]) {
        return entries.filter(([_, i]) => ["PACKAGE_MARKER", "CONFIG"].includes(i.component_type));
    }

    private static getItemStability(i: any): number {
        const adv = i.advanced_metrics;
        if (i.has_test || adv?.qualityGate === "GREEN") return 1;
        return adv?.qualityGate === "YELLOW" ? 0.5 : 0;
    }

    static getVitals(mapData: Record<string, any>): { dark_matter: string[], brittle_points: string[] } {
        const dark_matter: string[] = [];
        const brittle_points: string[] = [];

        for (const [file, info] of Object.entries(mapData)) {
            this.processVitalsEntry(file, info, dark_matter, brittle_points);
        }
        return { dark_matter, brittle_points };
    }

    private static processVitalsEntry(file: string, info: any, dark: string[], brittle: string[]) {
        if (!this.isUncoveredCode(file, info)) return;

        dark.push(file);
        if (info.complexity > 20) {
            brittle.push(file);
        }
    }

    private static isUncoveredCode(file: string, info: any): boolean {
        const adv = info.advanced_metrics;
        const isCode = !["DOC", "TEST"].includes(info.component_type) && !file.includes("/test/");
        return isCode && !(info.has_test || adv?.qualityGate === "GREEN");
    }
}

export class AuditEngine {
    orc: any; root: Path; taskOrc: TaskOrchestrator;
    constructor(orchestrator: any) {
        this.orc = orchestrator;
        this.root = new Path(orchestrator.projectRoot.toString());
        this.taskOrc = new TaskOrchestrator(orchestrator);
    }

    async runStrategicAudit(context: any, objective: string | null = null, dryRun: boolean = false): Promise<[any[], number]> {
        const startT = Date.now();
        const obj = objective || this._getDefaultObjective(context);
        const active = this.taskOrc.selectActivePhds(obj, this._getStacks(context), this.orc.personas);
        const changed = await this.detectChanges(Object.keys(context.map || {}));
        const findings = await this.taskOrc.runAuditCycle(active, obj, changed, context);

        await this.enrichAuditFindings(findings, Object.keys(changed), context);
        this._handleAuditPersistence(findings, changed, context, dryRun);
        return [findings, startT];
    }

    private _getStacks(ctx: any): Set<string> {
        return ctx.identity?.stacks || new Set(["Python"]);
    }

    private _getDefaultObjective(ctx: any): string {
        return `Validar integridade ${Array.from(this._getStacks(ctx)).join(', ')}`;
    }

    private _handleAuditPersistence(findings: any[], changed: Record<string, string>, ctx: any, dryRun: boolean): void {
        if (!dryRun) this.persistAuditState(findings, changed, ctx);
        else logger.info("🛡️ [AuditEngine] Dry-Run active.");
    }

    private async enrichAuditFindings(findings: any[], changedFiles: string[], context: any): Promise<void> {
        await this._enrichChangedFiles(changedFiles, findings);
        await this._addSecurityFindings(findings, context);
        await this._addDependencyFindings(findings);
    }

    private async _enrichChangedFiles(files: string[], findings: any[]): Promise<void> {
        for (const f of files) {
            await this._enrichSingleFile(f, findings);
        }
    }

    private async _addSecurityFindings(findings: any[], context: any): Promise<void> {
        const security = await (new (await import("../engines/security/security_sentinel_agent.ts")).SecuritySentinelAgent(this.orc.hubManager)).scanProject(context.map);
        findings.push(...security);
    }

    private async _addDependencyFindings(findings: any[]): Promise<void> {
        const dep = await (new (await import("../engines/diagnostics/audit_code_guardian_service.ts")).DependencyAuditor(this.root.toString())).checkSubmoduleStatus();
        findings.push(...dep);
    }

    private async _enrichSingleFile(f: string, findings: any[]): Promise<void> {
        await AuditHelpers.enrichSingleFile(f, findings, this.root, this.orc);
    }

    private persistAuditState(findings: any[], changed: Record<string, string>, context: any): void {
        Object.entries(changed).forEach(([p, h]) => this.orc.cacheManager.update(p, h));
        this.orc.cacheManager.save();
        this.orc.stabilityLedger.update(findings, context.map);
    }

    private async detectChanges(mapFiles: string[]): Promise<Record<string, string>> {
        const results = await this.orc.executor.runParallel(async (p: string) => {
            const h = await this.orc.cacheManager.getFileHash(this.root.join(p));
            return this.orc.cacheManager.isChanged(p, h) ? { path: p, hash: h } : null;
        }, mapFiles);
        return results.reduce((acc: Record<string, string>, r: any) => { if (r) acc[r.path] = r.hash; return acc; }, {});
    }

    async runObfuscationScan(contextMap: any = null): Promise<any[]> {
        const startT = Date.now();
        const hunter = new (await import("../engines/security/obfuscation_hunter.ts")).ObfuscationHunter(this.orc.hubManager);
        const tMap = contextMap || this.orc.contextEngine.map;

        const findings = await this._performObfuscationAudit(tMap, hunter);
        this._logObfuscationTime(startT);
        return findings;
    }

    private async _performObfuscationAudit(tMap: Record<string, any>, hunter: any): Promise<any[]> {
        let findings: any[] = [];
        for (const f of Object.keys(tMap)) {
            findings = findings.concat(await this._scanFileObfuscation(f, hunter));
        }
        return findings;
    }

    private _logObfuscationTime(startT: number): void {
        logger.info(`🕵️ [AuditEngine] Obfuscation scan concluído em ${((Date.now() - startT) / 1000).toFixed(4)}s.`);
    }

    private async _scanFileObfuscation(f: string, hunter: any): Promise<any[]> {
        return AuditHelpers.scanFileObfuscation(f, hunter, this.root);
    }

    async runStagedAudit(context: any, dryRun: boolean = true): Promise<[any[], number]> {
        const startT = Date.now();
        const staged = await this._getStagedFiles();
        if (staged.length === 0) return [[], startT];

        const changed = this._mapStagedToHashes(staged);
        const obj = "Staged Audit";
        const active = this.taskOrc.selectActivePhds(obj, context.identity?.stacks || new Set(["TS", "PY"]), this.orc.personas);
        const findings = await this.taskOrc.runAuditCycle(active, obj, changed, context);

        await this.enrichAuditFindings(findings, staged, context);
        return [findings, startT];
    }

    private async _getStagedFiles(): Promise<string[]> {
        const raw = await this.orc.executor.runCommand("git diff --cached --name-only");
        return raw.stdout.split("\n").filter((f: string) => f.trim() !== "");
    }

    private _mapStagedToHashes(staged: string[]): Record<string, string> {
        return staged.reduce((acc: any, f: string) => { acc[f] = "staged"; return acc; }, {});
    }

    async scan_content(content: string, f: string): Promise<any[]> {
        if (f.match(/\.ts$|\.tsx$/)) return AuditHelpers.scanTs(content, f, this.orc.hubManager);
        if (f.endsWith(".md")) return AuditHelpers.scanMd(content, f);
        return [];
    }

    private async _scanTs(content: string, f: string): Promise<any[]> {
        const { LogicAuditor } = await import("../engines/analysis/logic_auditor.ts");
        const auditor = new LogicAuditor(this.orc.hubManager);
        return await auditor.scanFile(f, content);
    }

    private async _scanMd(content: string, f: string): Promise<any[]> {
        const { MarkdownAuditor } = await import("../engines/reporting/markdown_auditor.ts");
        return MarkdownAuditor.auditMarkdown(f, content);
    }

    async scan_multiple_files(files: string[]): Promise<any[]> {
        const findings: any[] = [];
        for (const f of files) {
            findings.push(...await this._scanOptionalFile(f));
        }
        return findings;
    }

    private async _scanOptionalFile(f: string): Promise<any[]> {
        if (!(await Bun.file(this.root.join(f).toString()).exists())) return [];
        const content = await Bun.file(this.root.join(f).toString()).text();
        return this.scan_content(content, f);
    }

    public async _scan_single_file(f: string, _ctx: any): Promise<any[]> { 
        return this.scan_content(await Bun.file(this.root.join(f).toString()).text(), f); 
    }
}

export class TaskOrchestrator {
    orc: any;

    constructor(orchestrator: any) {
        this.orc = orchestrator;
    }

    async runAuditCycle(activePhds: any[], obj: string, changedFiles: Record<string, string>, context: any): Promise<any[]> {
        /** Executa o ciclo paralelo de auditoria para os PhDs selecionados. */
        const auditTask = async (agent: any) => {
            if (typeof agent.setContext === 'function') {
                agent.setContext({ identity: context.identity, map: context.map, hub: this.orc.hubManager });
            }
            const res: any[] = [];
            if (Object.keys(changedFiles).length > 0 && typeof agent.performAudit === 'function') {
                res.push(...await agent.performAudit());
            }
            if (typeof agent.performStrategicAudit === 'function') {
                res.push(...await agent.performStrategicAudit(obj));
            }
            return res;
        };

        const nestedResults = await this.orc.executor.runParallel(auditTask, activePhds);
        return nestedResults.flat();
    }

    async runTargetedVerification(auditMap: Record<string, string[]>): Promise<any[]> {
        /** Surgically verifies specific files using the assigned agents. */
        const verifiedFindings: any[] = [];
        for (const [file, agents] of Object.entries(auditMap)) {
            const findings = await this.verifyFile(file, agents);
            verifiedFindings.push(...findings);
        }
        return verifiedFindings;
    }

    private async verifyFile(file: string, agentNames: string[]): Promise<any[]> {
        const fullPath = this.orc.projectRoot.join(file);
        if (!(await fullPath.exists())) return [];

        const content = await this.orc.contextEngine.analyst.readProjectFile(fullPath.toString());
        if (!content) return [];

        const findings: any[] = [];
        for (const name of agentNames) {
            const agent = this.orc.personas.find((p: any) => p.name === name);
            if (agent?.performStrategicAudit) {
                findings.push(...await agent.performStrategicAudit({ fileTarget: file, contentTarget: content }));
            }
        }
        return findings;
    }

    selectActivePhds(_objective: string, stacks: Set<string>, personas: any[]): any[] {
        /** Filtra PhDs aptos para a missão baseado no objetivo e stack. */
        const isEligible = (p: any) => {
            if (p.stack && !stacks.has(p.stack) && p.stack !== "Universal") return false;
            return true;
        };

        return personas.filter(isEligible);
    }
}

export class ValidationAgent {
    orc: any;

    constructor(orchestrator: any) {
        this.orc = orchestrator;
    }

    async runValidationPhase(findings: any[], skipTests: boolean): Promise<any> {
        if (skipTests) return this.fastFallback();

        logger.info("🧪 Iniciando fase de validação...");

        // Inline strategist logic (previously DiagnosticStrategist.planTargetedVerification)
        const plan: Record<string, Set<string>> = {};
        for (const f of findings) {
            if (!f || typeof f !== 'object') continue;
            const file = f.file;
            const context = f.context || f.agent;
            if (file && context) {
                if (!plan[file]) plan[file] = new Set();
                plan[file].add(context);
            }
        }
        if (findings.length > 0) {
            const verificationFindings = await this.orc.runTargetedVerification(plan);
            findings.push(...verificationFindings);
        }

        const targetFiles = this.orc.lastDetectedChanges || [];
        // Fallback for target files if none detected
        const filesFromFindings = targetFiles.length > 0 ? targetFiles :
            findings.filter(f => typeof f === 'object' && f.file).map(f => f.file);

        return await this.orc.coreValidator.verifyCoreHealth(this.orc.projectRoot.toString(), filesFromFindings);
    }

    private fastFallback() {
        return {
            success: true,
            pass_rate: 100,
            total_run: 0,
            failed: 0,
            pyramid: {},
            execution: { success: true }
        };
    }
}

