export class ParityDaemon {
    private registryManager: RegistryManager;
    private backlog: string[] = [];
    private isProcessing = false;

    constructor(
        private projectRoot: string, 
        private watcher: HubWatcher, 
        private ledger: StabilityLedger,
        private hubManager: HubManagerGRPC
    ) {
        this.registryManager = new RegistryManager(projectRoot);
    }

    public start() {
        logger.info("🚀 [ParityDaemon] Iniciando monitoramento profundo de paridade...");
        this.watcher.onChange(async (filePath) => {
            if (this.isAgentFile(filePath)) {
                this.backlog.push(filePath);
                this.processBacklog();
            }
        });
    }

    private isAgentFile(filePath: string): boolean {
        const norm = filePath.replace(/\\/g, '/');
        return norm.includes("src_local/agents") && (norm.endsWith(".ts") || norm.endsWith(".py") || norm.endsWith(".go"));
    }

    private async processBacklog() {
        if (this.isProcessing || this.backlog.length === 0) return;
        this.isProcessing = true;

        const filePath = this.backlog.shift()!;
        try {
            logger.info(`⚖️ [Parity] Validando paridade semântica: ${path.basename(filePath)}`);
            const content = fs.readFileSync(filePath, 'utf-8');
            
            // 1. Obter "irmãos" de implementação do registro
            const siblings = this.registryManager.getAgentSiblings(filePath);
            
            if (siblings.length > 0) {
                for (const sibling of siblings) {
                    await this.checkParity(filePath, content, sibling);
                }
            }
        } catch (err) {
            logger.error(`❌ [Parity] Erro ao processar ${filePath}: ${err}`);
        } finally {
            this.isProcessing = false;
            if (this.backlog.length > 0) {
                setTimeout(() => this.processBacklog(), 2000);
            }
        }
    }

    private async checkParity(sourcePath: string, sourceContent: string, targetPath: string) {
        if (!fs.existsSync(targetPath)) return;
        const targetContent = fs.readFileSync(targetPath, 'utf-8');

        const prompt = `Perform a high-fidelity semantic parity comparison between these two agent implementations:
        Source (${path.extname(sourcePath)}): ${sourceContent.substring(0, 2000)}...
        Target (${path.extname(targetPath)}): ${targetContent.substring(0, 2000)}...
        
        Are they functionally equivalent? Identify discrepancies in logic, thresholds, or data handling.
        Return a JSON with { "equivalent": boolean, "discrepancies": string[], "severity": "LOW"|"MEDIUM"|"HIGH" }`;

        try {
            const response = await this.hubManager.reason(prompt);
            const result = JSON.parse(response || '{"equivalent":true, "discrepancies":[]}');

            if (!result.equivalent) {
                logger.warn(`⚖️ [Parity] Disparidade detectada entre ${path.basename(sourcePath)} e ${path.basename(targetPath)}`);
                this.ledger.registerDisparity({
                    source: sourcePath,
                    target: targetPath,
                    discrepancies: result.discrepancies,
                    severity: result.severity || "MEDIUM"
                });
            }
        } catch (e) {
            logger.debug(`[Parity] Falha na comparação semântica: ${e}`);
        }
    }
}

export class StructureClassifier {
    /**
     * 🧠 Classifica a natureza estrutural de um arquivo.
     */
    static classify(file: string, info: any): "STRUCTURAL" | "FACADE" | "LOGIC" {
        const compType = info.component_type || "";
        const complexity = info.complexity || 0;

        // Tier 1: STRUCTURAL — Arquivos sem lógica testável
        if (["PACKAGE_MARKER", "CONFIG", "INTERFACE"].includes(compType)) {
            return "STRUCTURAL";
        }

        // Tier 1b: Low complexity files are considered structural
        if (complexity <= 5) {
            return "STRUCTURAL";
        }

        // Tier 2: FACADE — Complexidade baixa, apenas delegação
        if (complexity <= 15) {
            return "FACADE";
        }

        // Tier 3: LOGIC — Tudo o resto precisa de cobertura profunda
        return "LOGIC";
    }
}

export class SemanticContextAnalyst {
    /** Parity: __init__ */
    constructor() {
        // Patterns are initialized as class fields.
    }

    private readonly METADATA_PATTERNS = [
        /^\s*(export\s+)?(const|let|var)\s+[A-Z_]+\s*=/,      // Constantes UPPER_CASE
        /^\s*(export\s+)?(type|interface|enum)\s+/,             // Definições de tipo
        /^\s*\/\*\*[\s\S]*?\*\//,                               // JSDoc/docstrings
        /^\s*(import|from)\s+/,                                 // Imports
        /^\s*@(deprecated|override|abstract)/,                  // Decorators
        /patterns\s*[:=]\s*[\[\{]/,                             // Definições de padrões
        /rules\s*[:=]\s*[\[\{]/,                                // Definições de regras
    ];

    private readonly OBSERVABILITY_PATTERNS = [
        /logger\.(info|warn|warning|error|debug|verbose)/,
        /console\.(log|warn|error|debug|info|trace)/,
        /log_performance/,
        /\.emit\s*\(/,
        /telemetry/i,
        /metrics?\.(increment|gauge|histogram)/,
    ];

    /**
     * 🔍 Classifica a intenção de um bloco de código.
     */
    classifyIntent(codeBlock: string): IntentType {
        if (this._isMetadataContext(codeBlock)) return "METADATA";
        if (this._isObservabilityContext(codeBlock)) return "OBSERVABILITY";
        return "LOGIC";
    }

    /**
     * 📂 Classifica o tipo do componente baseado no caminho.
     */
    mapComponentType(relPath: string): ComponentType {
        const normalized = relPath.replace(/\\/g, "/");
        if (normalized.includes("tests/") || normalized.includes("test_") || normalized.includes(".test.")) {
            return "TEST";
        }
        return "PRODUCTION";
    }

    /**
     * 📊 Analisa um arquivo completo e retorna estatísticas de intenção.
     */
    analyzeFile(content: string, filePath: string, rustMetadata?: any): { metadata: number; observability: number; logic: number; total: number } {
        if (rustMetadata && rustMetadata.semantic_blocks) {
            let metadata = 0, observability = 0, logic = 0;
            const blocks = rustMetadata.semantic_blocks;
            for (const key in blocks) {
                const intent = blocks[key];
                if (intent === "METADATA") metadata++;
                else if (intent === "OBSERVABILITY") observability++;
                else logic++;
            }
            const total = metadata + observability + logic;
            logger.debug(`📊 [Rust-Powered] ${filePath}: META=${metadata} OBS=${observability} LOGIC=${logic}`);
            return { metadata, observability, logic, total };
        }

        const lines = content.split("\n");
        let metadata = 0, observability = 0, logic = 0;

        // Analisa em blocos de 5 linhas para contexto
        for (let i = 0; i < lines.length; i += 5) {
            const block = lines.slice(i, Math.min(i + 5, lines.length)).join("\n");
            const intent = this.classifyIntent(block);
            if (intent === "METADATA") metadata++;
            else if (intent === "OBSERVABILITY") observability++;
            else logic++;
        }

        const total = metadata + observability + logic;
        logger.debug(`📊 [TS-Fallback] ${filePath}: META=${metadata} OBS=${observability} LOGIC=${logic}`);
        return { metadata, observability, logic, total };
    }

    private _isMetadataContext(block: string): boolean {
        return this.METADATA_PATTERNS.some(p => p.test(block));
    }

    private _isObservabilityContext(block: string): boolean {
        return this.OBSERVABILITY_PATTERNS.some(p => p.test(block));
    }
}

