export class FileSystemScanner {
    root: Path;
    analyst: any;

    constructor(root: string, analyst: any) {
        this.root = new Path(root);
        this.analyst = analyst;
        logger.debug(`FileSystemScanner initialized for root: ${this.root.toString()}`);
    }

    async scanAllFilenames(): Promise<string[]> {
        const files: string[] = [];
        await this.walkFiles(this.root.toString(), files);
        return files;
    }

    private async walkFiles(dir: string, files: string[]) {
        if (ForbiddenPolicy.isForbiddenDir(dir)) return;

        const entries = await readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
            await this.processEntry(dir, entry, files);
        }
    }

    private async processEntry(dir: string, entry: any, files: string[]) {
        const res = join(dir, entry.name);
        if (entry.isDirectory()) {
            await this.walkFiles(res, files);
        } else {
            files.push(entry.name.toLowerCase());
        }
    }

    async *getAnalyzableFiles(): AsyncGenerator<Path> {
        const seen = new Set<string>();
        const generator = this._walkAndYield(this.root.toString());

        for await (const pathStr of generator) {
            const path = new Path(pathStr);
            if (!seen.has(pathStr) && !(await this.shouldSkip(path))) {
                seen.add(pathStr);
                yield path;
            }
        }
    }

    private async * _walkAndYield(dir: string): AsyncGenerator<string> {
        if (ForbiddenPolicy.isForbiddenDir(dir)) return;

        const entries = await readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
            yield* this._processYieldEntry(dir, entry);
        }
    }

    private async * _processYieldEntry(dir: string, entry: any): AsyncGenerator<string> {
        const res = join(dir, entry.name);
        if (entry.isDirectory()) {
            yield* this._walkAndYield(res);
        } else {
            yield res;
        }
    }

    async shouldSkip(path: Path): Promise<boolean> {
        if (!(await path.isFile())) return true;

        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();
        return this.isPathForbiddenOrIgnored(path, pathStr);
    }

    private isPathForbiddenOrIgnored(path: Path, pathStr: string): boolean {
        if (ForbiddenPolicy.isForbiddenDir(dirname(pathStr))) return true;
        if (this.isAgentRelated(pathStr)) return true;
        if (this.isIgnoredByAnalyst(path)) return true;
        return !this.analyst.isAnalyable(path);
    }

    private isAgentRelated(pathStr: string): boolean {
        return pathStr.includes("/.agent/") && !pathStr.includes("fast-android-build");
    }

    private isIgnoredByAnalyst(path: Path): boolean {
        const pathStr = path.toString().replace(/\\/g, "/").toLowerCase();
        return !pathStr.includes("src_local") && this.analyst.shouldIgnore(path);
    }
}

export class ModelInitializer {
    static mulberry32(seed: number): () => number {
        let s = seed | 0;
        return () => {
            s = (s + 0x6d2b79f5) | 0;
            let t = Math.imul(s ^ (s >>> 15), 1 | s);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }

    static gauss(rng: () => number, mean: number, std: number): number {
        const u1 = rng();
        const u2 = rng();
        return mean + std * Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    }

    static createMatrix(nout: number, nin: number, rng: () => number, std = 0.08): Value[][] {
        return Array.from(
            { length: nout },
            () => Array.from({ length: nin }, () => new Value(this.gauss(rng, 0, std))),
        );
    }

    static initDict(vocabSize: number, blockSize: number, nLayer: number, nEmbd: number): Record<string, Value[][]> {
        const rng = this.mulberry32(42);
        const dict: Record<string, Value[][]> = {
            wte: this.createMatrix(vocabSize, nEmbd, rng),
            wpe: this.createMatrix(blockSize, nEmbd, rng),
            lm_head: this.createMatrix(vocabSize, nEmbd, rng),
        };

        for (let i = 0; i < nLayer; i++) {
            dict[`layer${i}.attn_wq`] = this.createMatrix(nEmbd, nEmbd, rng);
            dict[`layer${i}.attn_wk`] = this.createMatrix(nEmbd, nEmbd, rng);
            dict[`layer${i}.attn_wv`] = this.createMatrix(nEmbd, nEmbd, rng);
            dict[`layer${i}.attn_wo`] = this.createMatrix(nEmbd, nEmbd, rng);
            dict[`layer${i}.mlp_fc1`] = this.createMatrix(4 * nEmbd, nEmbd, rng);
            dict[`layer${i}.mlp_fc2`] = this.createMatrix(nEmbd, 4 * nEmbd, rng);
        }
        return dict;
    }
}

export class SafetySupremeJudge {
    private ast: ASTIntelligence;

    constructor() {
        this.ast = new ASTIntelligence();
    }

    /**
     * Julga se um nó da AST está em um contexto seguro.
     */
    public isNodeSafe(node: ts.Node, sourceFile: ts.SourceFile, ignoreTest = false): boolean {
        const checks = [
            () => !ignoreTest && this.isInsideTest(node, sourceFile),
            () => this.isInsideLogCall(node, sourceFile),
            () => this.isInsideRuleDefinition(node, sourceFile),
            () => this.isInsideSafeExceptionHandler(node, sourceFile)
        ];

        return checks.some(check => check());
    }

    public isDangerousExecution(node: ts.Node): boolean {
        return ASTIntelligence.isCallTo(node, ["eval", "exec", "system", "spawnSync", "execSync"]);
    }

    private isInsideTest(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        return ASTIntelligence.getParentChain(node).some(p => ASTIntelligence.isCallTo(p, ["describe", "test", "it", "expect", "beforeEach", "afterEach"]));
    }

    private isInsideLogCall(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        return ASTIntelligence.getParentChain(node).some(p => ASTIntelligence.isCallTo(p, SAFE_LOG_METHODS));
    }

    private isInsideRuleDefinition(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        const chain = ASTIntelligence.getParentChain(node);
        return this._isAnalyzerContext(chain) || this._isMetadataAssignment(chain);
    }

    private _isAnalyzerContext(chain: ts.Node[]): boolean {
        return chain.some(parent => {
            const name = this.getNodeName(parent);
            return CORE_PERFORMANCE_FUNCS.includes(name) || ANALYZER_METHODS.includes(name) || ANALYZER_CLASSES.includes(name);
        });
    }

    private getNodeName(node: ts.Node): string {
        if (ts.isMethodDeclaration(node) || ts.isFunctionDeclaration(node) || ts.isClassDeclaration(node)) {
            return (node as any).name?.getText() || "";
        }
        return "";
    }

    private _isMetadataAssignment(chain: ts.Node[]): boolean {
        return chain.some(parent => {
            const isBin = ts.isBinaryExpression(parent) && parent.operatorToken.kind === ts.SyntaxKind.EqualsToken && SAFE_METADATA_VARS.some(v => parent.left.getText().includes(v));
            const isProp = ts.isPropertyAssignment(parent) && SAFE_METADATA_VARS.includes(parent.name.getText());
            return isBin || isProp;
        });
    }

    private isInsideSafeExceptionHandler(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        const catchClause = ASTIntelligence.getParentChain(node).find(ts.isCatchClause);
        if (!catchClause) return false;

        const catchText = catchClause.block.getText().toLowerCase();
        return SAFE_LOG_METHODS.some(m => catchText.includes(m.toLowerCase()));
    }

    public is_dangerous_call(node: ts.Node): boolean {
        return this.isDangerousExecution(node);
    }

    public is_meta_analysis_node(node: ts.Node, sourceFile: ts.SourceFile): boolean {
        const t = node.getText();
        return ["ts.createSourceFile", "ts.forEachChild", "eval(", "new Function("].some(v => t.includes(v));
    }
}

export class JudgeHelpers {
    static isRuleDefinition(line: string): boolean {
        return /^\s*(export\s+)?(const|let|var)\s+[A-Z_]/.test(line);
    }

    static isInsideCriticalReport(ctx: string): boolean {
        return CRITICAL_LOG_METHODS.some(m => ctx.includes(`.${m}(`));
    }

    static isInsideLogCall(ctx: string): boolean {
        return /logger\.(info|warn|debug|verbose)/.test(ctx) || /console\.(log|info|debug)/.test(ctx);
    }

    static hasTelemetrySignal(line: string): boolean {
        return /time\.time|Date\.now|performance\.now|process\.hrtime|Bun\.nanoseconds/.test(line)
            || TELEMETRY_KEYWORDS.some(k => line.toLowerCase().includes(k));
    }

    static isSimpleTimeSubtraction(line: string): boolean {
        return /Date\.now\s*\(\)\s*-\s*\w+/.test(line) || /\w+\s*-\s*Date\.now\s*\(\)/.test(line)
            || /performance\.now\s*\(\)\s*-\s*\w+/.test(line);
    }

    static isTelemetryName(line: string): boolean {
        return TELEMETRY_KEYWORDS.some(k => line.toLowerCase().includes(k));
    }
}

export class QualityEvaluator {
    static calculateMaintainabilityIndex(volume: number, cyclomaticComplexity: number, sloc: number): number {
        if (sloc <= 0) return 100;
        const logVolume = Math.log(Math.max(1, volume));
        const logLOC = Math.log(sloc);
        let mi = 171 - 5.2 * logVolume - 0.23 * cyclomaticComplexity - 16.2 * logLOC;
        mi = mi * 100 / 171;
        return Math.max(0, Math.min(100, mi));
    }

    static determineRiskLevel(cyclomatic: number, cognitive: number, mi: number): "LOW" | "MODERATE" | "HIGH" | "CRITICAL" {
        return RiskPolicy.determineRiskLevel(cyclomatic, cognitive, mi);
    }

    static determineQualityGate(mi: number, cc: number, defectDensity: number, sloc: number = 0): "GREEN" | "YELLOW" | "RED" {
        return RiskPolicy.determineQualityGate(mi, cc, defectDensity, sloc);
    }

    static validateShadowCompliance(metrics: any): { compliant: boolean; reason: string } {
        if (!metrics.isShadow) return { compliant: true, reason: "Não é um shadow" };
        if (metrics.shadowComplexity > 15) return { compliant: false, reason: `Complexidade shadow (${metrics.shadowComplexity}) > 15` };
        if (metrics.maintainabilityIndex < 20) return { compliant: false, reason: `MI (${metrics.maintainabilityIndex.toFixed(1)}) < 20` };
        if (metrics.nestingDepth > 3) return { compliant: false, reason: `Aninhamento (${metrics.nestingDepth}) > 3` };
        return { compliant: true, reason: "Shadow complacente" };
    }

    static getMIStatus(mi: number): string {
        if (mi >= 20) return "🟢 GOOD";
        if (mi >= 10) return "🟡 MODERATE";
        return "🔴 LOW";
    }
}

export class HeadingRules {
    static ensureBlanks(lines: string[]): string[] {
        return lines.reduce((acc: string[], line, i) => {
            const isHeading = line.replace(/^>\s*/, "").trim().startsWith("#");
            const prefix = line.match(/^>\s*/)?.[0] || "";
            if (isHeading && acc.length > 0 && acc[acc.length - 1].replace(/^>\s*/, "").trim() !== "") acc.push(prefix.trimEnd());
            acc.push(line);
            if (isHeading && i + 1 < lines.length && lines[i + 1].replace(/^>\s*/, "").trim() !== "") acc.push(prefix.trimEnd());
            return acc;
        }, []);
    }
}

export class SystemSentinel {
    private isAdmin: boolean = false;
    private healthCache: { data: any, timestamp: number } | null = null;
    private readonly CACHE_TTL = 3000; // Hub is fast, reduce TTL

    constructor() { this.isAdmin = this.checkAdmin(); }

    private checkAdmin(): boolean {
        // Simple check remains local
        return false; // Net session check omitted for simplicity in this refactor
    }

    async getSystemHealth() {
        if (this.healthCache && Date.now() - this.healthCache.timestamp < this.CACHE_TTL) return this.healthCache.data;

        try {
            const response = await fetch(HUB_STATUS_URL);
            if (response.ok) {
                const h = (await response.json()).metrics;
                this.healthCache = { data: h, timestamp: Date.now() };
                return h;
            }
        } catch (e) {
            logger.warn("⚠️ Hub Sentinel unavailable. Using local fallback.");
        }

        const h = HealthCollector.collect(this.isAdmin);
        this.healthCache = { data: h, timestamp: Date.now() };
        return h;
    }

    async getHeavyProcesses(): Promise<any[]> {
        const health = await this.getSystemHealth();
        return health.heavy_processes || [];
    }

    async suggestOptimizations(): Promise<string[]> {
        const h = await this.getSystemHealth(), suggestions: string[] = [];
        if (parseFloat(h.memory_usage) > 85) suggestions.push("⚠️ RAM crítica (>85%).");
        if (h.cpu_usage > 70) suggestions.push("⚠️ Alta carga de CPU.");
        if (!this.isAdmin) suggestions.push("🛡️ Executar como ADMIN permitiria otimizações.");
        return suggestions;
    }

    enforceGovernance() { ResourceGovernor.enforce(process.pid); }

    async shouldThrottle(cpuLimit: number = 85, memLimit: number = 95): Promise<boolean> {
        return ResourceGovernor.shouldThrottle(await this.getSystemHealth(), cpuLimit, memLimit);
    }

    async yieldIfHighLoad(cpuL: number = 85, memL: number = 95) {
        await ResourceGovernor.yield(async () => await this.shouldThrottle(cpuL, memL));
    }

    async analyze_and_kill_bloatware(): Promise<{ process: string, mem_mb: string, action: string }[]> {
