export class ObservabilityScorer {
    static calculate(mapData: Record<string, any>): [number, number, number] {
        const excluded = ["TEST", "PACKAGE_MARKER", "CONFIG"];
        const relevant = Object.entries(mapData).filter(([f, i]) =>
            !excluded.includes(i.component_type) || i.complexity > 1
        ).map(([f, i]) => i);

        const tel = relevant.filter(i => {
            return i.telemetry ||
                i.has_telemetry ||
                i.advanced_metrics?.telemetry ||
                JSON.stringify(i).includes("logger") ||
                JSON.stringify(i).includes("telemetry");
        });
        const score = (tel.length / Math.max(1, relevant.length)) * 15;
        return [score, tel.length, relevant.length];
    }
}

export class SecurityScorer {
    static calculate(alerts: any[]): [number, number] {
        const high = alerts.filter(r => typeof r === 'object' && ["critical", "high"].includes(r.severity));
        return [Math.max(0, 15 - (high.length * 5)), high.length];
    }
}

export async function analyzeSecurity(file: string, content: string, hubManager?: HubManagerGRPC): Promise<AuditRule[]> {
    return (await new HeuristicEvaluator(hubManager).analyze(file, content)).rulesHit;
}

export class HeuristicEvaluator {
    constructor(private hubManager?: HubManagerGRPC) {}

    public async analyze(file: string, content: string): Promise<SecurityAuditResult> {
        if (!this.hubManager) {
            return {
                vector: SecurityVector.LOGIC_BOMB,
                rulesHit: [],
                threatLevel: "LOW",
                remediation: "Aguardando conexão com Hub gRPC para auditoria profunda."
            };
        }

        try {
            const analysis = await this.hubManager.analyzeFile(file, content);
            const hits: AuditRule[] = (analysis?.findings || [])
                .filter((f: any) => ["SECURITY", "OBFUSCATION"].includes(f.category))
                .map((f: any) => ({
                    regex: "", 
                    issue: f.message,
                    severity: f.severity.toLowerCase() as any
                }));

            const threatLevel = this.calculateThreatLevel(hits);
            const vector = this.determineVector(hits);

            return {
                vector,
                rulesHit: hits,
                threatLevel,
                remediation: this.getRemediation(vector)
            };
        } catch (e) {
            logger.error(`❌ [Vulnerability] Falha na análise gRPC: ${e}`);
            return {
                vector: SecurityVector.LOGIC_BOMB,
                rulesHit: [],
                threatLevel: "LOW",
                remediation: "Falha técnica na auditoria profunda."
            };
        }
    }

    private calculateThreatLevel(hits: AuditRule[]): "CRITICAL" | "HIGH" | "MEDIUM" | "LOW" {
        if (hits.some(h => h.severity === "critical")) return "CRITICAL";
        if (hits.some(h => h.severity === "high")) return "HIGH";
        if (hits.some(h => h.severity === "medium")) return "MEDIUM";
        return "LOW";
    }

    private determineVector(hits: AuditRule[]): SecurityVector {
        if (this.hasIssue(hits, "Ofuscação", "OBFUSCATION")) return SecurityVector.OBFUSCATION;
        if (this.hasIssue(hits, "Injeção", "Parsing", "INJECTION")) return SecurityVector.INJECTION;
        if (this.hasIssue(hits, "Vazamento", "Sensível", "LEAK")) return SecurityVector.LEAK;
        if (this.hasIssue(hits, "Shell", "Arquivo", "INFRASTRUCTURE")) return SecurityVector.INFRASTRUCTURE;
        return SecurityVector.LOGIC_BOMB;
    }

    private hasIssue(hits: AuditRule[], ...keywords: string[]): boolean {
        return hits.some(h => keywords.some(kw => h.issue.includes(kw) || String(h.regex).includes(kw)));
    }

    private getRemediation(vector: SecurityVector): string {
        const remediations: Record<SecurityVector, string> = {
            [SecurityVector.OBFUSCATION]: "Limpar código ofuscado (Deep Healer) e restaurar nomes semânticos.",
            [SecurityVector.INJECTION]: "Aplicar sanitização profunda via AST (Sovereign Shield) e validar fluxos de dados.",
            [SecurityVector.LEAK]: "Remover segredos e migrar para Vault nativo do projeto.",
            [SecurityVector.INFRASTRUCTURE]: "Aplicar sandboxing e restringir chamadas nativas perigosas.",
            [SecurityVector.LOGIC_BOMB]: "Auditoria manual PhD recomendada para fluxos assíncronos complexos."
        };
        return remediations[vector] || "Revisão por PhD de Segurança necessária.";
    }
}

