export class ForbiddenPolicy {
    static isForbiddenDir(dir: string): boolean {
        const normalized = dir.replace(/\\/g, "/").toLowerCase();
        const segments = normalized.split("/");

        if (this.hasForbiddenSegment(segments)) return true;
        if (segments.includes(".agent")) return this.isForbiddenAgentDir(normalized, segments);
        return false;
    }

    private static hasForbiddenSegment(segments: string[]): boolean {
        const forbidden = new Set([".git", ".gemini", "restore", "forensics", "__pycache__", "node_modules", ".venv", "dist", "build"]);
        return segments.some(p => forbidden.has(p));
    }

    private static isForbiddenAgentDir(normalized: string, segments: string[]): boolean {
        if (normalized.includes("fast-android-build")) return false;
        const sub = segments.slice(segments.indexOf(".agent"));
        const allowed = new Set([".agent", "skills"]);
        return !sub.every(p => allowed.has(p));
    }
}

export class HeadingRules implements LintRule {
    check(lines: string[], i: number, stripped: string, file: string, context: { hMap: Map<string, number>, errs: any[] }): void {
        if (!stripped.startsWith("#")) return;

        if (!/^#+\s/.test(stripped)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD001: Heading levels should be followed by a space", 
                severity: "medium", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: stripped,
                context: "MarkdownAuditor" 
            });
        }

        if (i > 0 && (lines[i - 1]?.trim() || "") !== "") {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD022: Headings should be surrounded by blank lines (above)", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: lines[i-1] || "",
                context: "MarkdownAuditor" 
            });
        }

        const nextLine = lines[i + 1]?.trim() || "";
        if (i < lines.length - 1 && nextLine !== "" && !nextLine.startsWith("#")) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD022: Headings should be surrounded by blank lines (below)", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: nextLine,
                context: "MarkdownAuditor" 
            });
        }

        const text = stripped.replace(/^#+\s+/, "");
        if (context.hMap.has(text)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: `MD024: Duplicate heading: '${text}'`, 
                severity: "medium", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: text,
                context: "MarkdownAuditor" 
            });
        }
        context.hMap.set(text, i);

        if (/[.,;:!?]$/.test(text)) {
            context.errs.push({ 
                file, 
                line: i + 1, 
                issue: "MD026: Trailing punctuation in heading", 
                severity: "low", 
                agent: "markdown_auditor",
                role: "DOCUMENTATION_ENGINEER",
                emoji: "✍️",
                stack: "Documentation",
                evidence: text,
                context: "MarkdownAuditor" 
            });
        }
    }
}

