export class StructureClassifier {
    /**
     * 🧠 Classifica a natureza estrutural de um arquivo.
     */
    static classify(file: string, info: any): "STRUCTURAL" | "FACADE" | "LOGIC" {
        const compType = info.component_type || "";
        const complexity = info.complexity || 0;

        // Tier 1: STRUCTURAL — Arquivos sem lógica testável
        if (["PACKAGE_MARKER", "CONFIG", "INTERFACE"].includes(compType)) {
            return "STRUCTURAL";
        }

        // Tier 1b: Low complexity files are considered structural
        if (complexity <= 5) {
            return "STRUCTURAL";
        }

        // Tier 2: FACADE — Complexidade baixa, apenas delegação
        if (complexity <= 15) {
            return "FACADE";
        }

        // Tier 3: LOGIC — Tudo o resto precisa de cobertura profunda
        return "LOGIC";
    }
}

export class HalsteadAnalyst {
    static calculate(content: string): { volume: number; difficulty: number; effort: number } {
        const operators = content.match(/[+\-*/%=<>!&|^~?:]+|&&|\|\||\.\.\.|\?\./g) || [];
        const uniqueOperators = new Set(operators);

        const operands = content.match(/\b[a-zA-Z_]\w*\b/g) || [];
        const uniqueOperands = new Set(operands);

        const n1 = uniqueOperators.size;
        const n2 = uniqueOperands.size;
        const N1 = operators.length;
        const N2 = operands.length;

        const totalUnique = n1 + n2;
        const volume = totalUnique > 0 ? totalUnique * Math.log2(totalUnique) : 0;
        const difficulty = n1 > 0 ? (n1 / 2) * (N2 / Math.max(1, n2)) : 0;
        const effort = volume * difficulty;

        return { volume, difficulty, effort };
    }
}

export class DepthIntelligence {
    static async calculateDepthAudit(projectRoot: string, tsFiles: string[], metadataCache: Record<string, any>): Promise<DepthSummary> {
        const metrics: DepthMetric[] = [];
        const stats = { SOVEREIGN: 0, LEGACY: 0, SHALLOW: 0 };

        const concurrencyLimit = 15;
        for (let i = 0; i < tsFiles.length; i += concurrencyLimit) {
            const batch = tsFiles.slice(i, i + concurrencyLimit);
            await Promise.all(batch.map(sovPath => 
                this.processFileDepth(sovPath, projectRoot, metadataCache, metrics, stats)
            ));
        }
        
        return { stats, metrics };
    }

    private static async processFileDepth(sovPath: string, projectRoot: string, metadataCache: Record<string, any>, metrics: DepthMetric[], stats: any) {
        try {
            const relPath = path.relative(projectRoot, sovPath).replace(/\\/g, "/");
            const metadata = metadataCache[relPath] || { semantic_blocks: [] };

            // Use semantic blocks from Rust as atomic weight
            const atomicWeight = (metadata.semantic_blocks || []).length * 15;
            const tsDepth = await TsDepthScorer.calculate(sovPath, atomicWeight);

            const { status, rank } = this.determineSovereignty(tsDepth);

            if (status === "🚀 SOVEREIGN") stats.SOVEREIGN++;
            else if (status === "⚠️ LEGACY-STYLE") stats.LEGACY++;
            else stats.SHALLOW++;

            metrics.push({
                path: relPath,
                depth: tsDepth,
                status: status as DepthMetric["status"],
                complexity_rank: rank
            });
        } catch (err) {
            logger.error(`💥 Erro depths ${sovPath}: ${err}`);
        }
    }

    private static determineSovereignty(depth: number): { status: string, rank: string } {
        if (depth > 500) return { status: "🚀 SOVEREIGN", rank: "PhD (Arquitetura Profunda)" };
        if (depth > 200) return { status: "⚠️ LEGACY-STYLE", rank: "Senior (Lógica Estruturada)" };
