export const deepClean = (text: any): string => {
    if (typeof text !== 'string') return String(text || "");
    return text
        .replace(/^[>\s|,\.:;]+/, "")
        .replace(/[`*]/g, "")
        .replace(/[>|]{1,}/g, "")
        .replace(/[,%]/g, "")
        .replace(/:---/g, "")
        .trim();
};

