    // More robust regex: matches headers with any level of nesting (#, ##, etc.)
    // and ignores potential icons or emojis at the start of the header name
    const parts = md.split(new RegExp(`^#+\\s+.*${header.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'mi'));
    const contentPart = parts[1];
    if (!contentPart) return "";
    const sectionContent = contentPart.split(/\n#+/m)[0];
    return (sectionContent || "").trim();
};

export const parseTable = (content: string) => {
    if (!content) return [];
    const lines = content.split('\n').map(l => l.trim().replace(/^>\s*/, '').trim());
    const tableLines = lines.filter(l => l.startsWith('|') && !l.includes(':---'));
    if (tableLines.length < 2) return [];

    const firstLine = tableLines[0];
    const headers = firstLine.split('|').filter(c => c.trim() !== "").map(c => deepClean(c));
    const rows = tableLines.slice(1).map(line => {
        return line.split('|').filter(c => c.trim() !== "").map(c => deepClean(c));
    });

    return rows.map(row => {
        const obj: any = {};
        headers.forEach((h, i) => {
            if (h) obj[h] = row[i] || "";
        });
        return obj;
    }).filter(row => Object.values(row).some(v => v !== ""));
};

export class EntropySection {
    render(mapData: Record<string, any>, limit: number = 200): string {
        const entries: Array<{ file: string; complexity: number; instability: number }> = [];

        for (const [f, info] of Object.entries(mapData)) {
            const file = f.toLowerCase().replace(/\\/g, "/");
            if (file.includes("/.agent/") || file.startsWith(".agent/")) continue;
            if (file.includes("legacy_restore") || file.endsWith("__init__.py")) continue;

            entries.push({
                file: f,
                complexity: (info as any).complexity || 1,
                instability: (info as any).coupling?.instability || 0,
            });
        }

        entries.sort((a, b) => b.complexity - a.complexity);

        const rows = entries.slice(0, limit).map(e => {
            const basename = e.file.split(/[\\/]/).pop() || e.file;
            return `> | \`${basename}\` | \`${e.complexity}\` | \`${Math.round(e.instability * 100)}%\` |`;
        });

        return [
            "> | Componente | Complex. | Instabilidade (Prob.) |",
            "> | :--- | :---: | :--- |",
            ...rows,
            "",
        ].join("\n");
    }
}

export async function extractPythonFingerprint(content: string, name: string): Promise<AtomicFingerprint> {
    const extractor = new FingerprintExtractor();
    return await extractor.extractPython(content, name);
}

export async function extractTSFingerprint(content: string, name: string): Promise<AtomicFingerprint | null> {
    const extractor = new FingerprintExtractor();
    return await extractor.extractTS(content, name);
}

export function capitalize(s: string): string {
    return s.charAt(0).toUpperCase() + s.slice(1);
}

export function computeDeltas(legacy: AtomicFingerprint, current: AtomicFingerprint, agent: string): AgentDelta[] {
    return DeltaEngine.compute(legacy, current, agent);
}

export function computeScore(deltas: AgentDelta[]): number {
    return DeltaEngine.computeScore(deltas);
}

export class ComponentMappingStrategy {
    static mapType(relPath: string): string {
        const p = relPath.toLowerCase().replace(/\\/g, "/");
        if (p.includes("/engines/")) return "ENGINE";
        if (p.includes("/core/")) return "CORE";
        if (p.includes("/utils/")) return "UTIL";
        if (p.includes("/diagnostics/") || p.includes("/analysis/")) return "LOGIC";
        if (p.includes("/test/") || p.includes(".test.") || p.includes("_test.")) return "TEST";
        if (p.endsWith(".md") || p.endsWith(".txt")) return "DOC";
        return "UNKNOWN";
    }
}
